def local_declaration(
    name: str,
    source: str,
    *,
    source_file: str = "papers/Fixture/PaperInterface.lean",
    line: int = 1,
) -> object:
    match = AUDIT.DECL_RE.match(source)
    assert match is not None
    return AUDIT.LocalDeclaration(
        name=name,
        kind=match.group(1),
        source=source,
        source_file=source_file,
        line=line,
    )


