def lean_import_closure_record(
    root: Path,
    interface: Path,
    sources: list[Path],
) -> dict[str, object]:
    """Build a minimal validated Lean-owned closure fixture."""

    source_records: list[dict[str, object]] = []
    modules: list[str] = []
    for source in sources:
        relative = source.resolve().relative_to(root.resolve()).as_posix()
        module = IMPORT_CLOSURE.module_name_for_path(relative)
        assert module is not None
        content = source.read_bytes()
        modules.append(module)
        source_records.append(
            {
                "module": module,
                "path": relative,
                "byte_length": len(content),
                "sha256": hashlib.sha256(content).hexdigest(),
            }
        )
    entrypoint = interface.resolve().relative_to(root.resolve()).as_posix()
    entry_module = IMPORT_CLOSURE.module_name_for_path(entrypoint)
    assert entry_module is not None
    return IMPORT_CLOSURE.validated_lean_import_closure_payload(
        {
            "schema": IMPORT_CLOSURE.WORKTREE_IDENTITY_SCHEMA,
            "entrypoint": entrypoint,
            "entry_module": entry_module,
            "lean_loaded_modules": sorted(modules),
            "sources": sorted(source_records, key=lambda item: str(item["path"])),
            "external_import_modules": [],
            "external_module_artifacts_sha256": (
                IMPORT_CLOSURE.external_module_artifacts_sha256([])
            ),
            "build_controls": [
                {
                    "path": relative,
                    "tracked_in_index": True,
                    "untracked": False,
                    "path_kind": "file",
                    "byte_length": 0,
                    "sha256": "0" * 64,
                }
                for relative in IMPORT_CLOSURE.WORKTREE_IDENTITY_CONTROL_PATHS
            ],
            "lake_routing": {
                "schema": IMPORT_CLOSURE.LAKE_ROUTING_SCHEMA,
                "kind": "lean",
                "sha256": "0" * 64,
                "byte_length": 0,
            },
        }
    )


