def elaborated_dependency_manifest(
    root: str,
    edges: list[tuple[str, str, str]] | None = None,
    *,
    atoms: list[dict[str, object]] | None = None,
) -> dict[str, object]:
    """Return a minimal complete Lean dependency graph for static unit tests."""

    graph_edges = edges or []
    nodes = {root}
    for source, target, _role in graph_edges:
        nodes.update((source, target))
    manifest: dict[str, object] = {
        "semantic_dependency_graph": {
            "schema": 1,
            "root_declaration": root,
            "complete": True,
            "realization_complete": True,
            "nodes": [
                {"declaration": declaration}
                for declaration in sorted(nodes)
            ],
            "edges": [
                {"source": source, "target": target, "role": role}
                for source, target, role in graph_edges
            ],
            "failures": [],
        }
    }
    if atoms is not None:
        manifest["sha256"] = "f" * 64
        manifest["atoms"] = atoms
    return manifest


def elaborated_bare_spec_pair_manifests(
    evidence: str,
    spec: str,
    *,
    extra_type_target: str | None = None,
) -> dict[str, dict[str, object]]:
    """Return minimal normalized-graph fixtures for a bare theorem/Spec pair."""

    declarations = [(evidence, "theorem", "1" * 64), (spec, "definition", "2" * 64)]
    edges = [
        {
            "source": evidence,
            "target": spec,
            "role": "type_uses_constant",
        }
    ]
    if extra_type_target is not None:
        declarations.append((extra_type_target, "definition", "3" * 64))
        edges.append(
            {
                "source": evidence,
                "target": extra_type_target,
                "role": "type_uses_constant",
            }
        )
    dependency_graph = {
        "schema": 1,
        "root_declaration": evidence,
        "complete": True,
        "realization_complete": True,
        "nodes": [
            {
                "declaration": declaration,
                "module_origin": "Fixture.Paper",
                "origin_class": "review_closure",
                "declaration_kind": kind,
                "semantic_identity_sha256": semantic_sha,
            }
            for declaration, kind, semantic_sha in declarations
        ],
        "edges": edges,
        "failures": [],
        "semantic_external_module_origins": [],
        "realization_external_module_origins": [],
    }
    transparent_graph = {
        "schema": 1,
        "complete": True,
        "nodes": [
            {
                "path": "result",
                "kind": "forall",
                "semantic_sha256": "4" * 64,
            }
        ],
        "edges": [],
        "failures": [],
    }
    return {
        evidence: {
            "declaration_kind": "theorem",
            "semantic_dependency_graph": dependency_graph,
        },
        spec: {
            "declaration_kind": "definition",
            "conclusion_mode": "type_and_value",
            "elaborated_transparent_result_value_graph": transparent_graph,
        },
    }


class RecursiveFieldReceiptPreservationTests(unittest.TestCase):
    def test_missing_slot_does_not_erase_independent_field_receipt(self) -> None:
        first = AUDIT.FieldInfo(
            structure="Fixture.Model",
            field="first",
            type="Nat",
            path="Fixture.Model.first",
            line=1,
            source_file="papers/Fixture/Model.lean",
            nested_structures=[],
            risk_terms=[],
            constructor_argument_index=0,
            projection_fqn="Fixture.Model.first",
        )
        second = AUDIT.FieldInfo(
            structure="Fixture.Model",
            field="second",
            type="Nat",
            path="Fixture.Model.second",
            line=2,
            source_file="papers/Fixture/Model.lean",
            nested_structures=[],
            risk_terms=[],
            constructor_argument_index=1,
            projection_fqn="Fixture.Model.second",
        )
        material = {
            "schema": AUDIT.RECURSIVE_FIELD_SAFETY_LOCATOR_SCHEMA,
            "kind": "projection",
            "declaration": first.projection_fqn,
            "field_index": first.constructor_argument_index,
        }
        identity = AUDIT.recursive_field_safety_locator_identity(material)
        with patch.object(
            AUDIT,
            "run_lean_recursive_field_proposition_sorts",
            return_value={
                identity: {
                    "status": "ok",
                    "value_sort": "false",
                    "payload_safety": "structural_data",
                }
            },
        ):
            receipts, errors = AUDIT.lean_recursive_field_proposition_sorts(
                root=ROOT,
                import_module="Fixture.PaperInterface",
                fields=[first, second],
                no_lean=False,
            )
        self.assertEqual(receipts["Fixture.Model.first"]["receipt"]["status"], "ok")
        self.assertEqual(receipts["Fixture.Model.second"]["receipt"]["status"], "error")
        self.assertTrue(any("missing Lean field-safety receipt" in error for error in errors))


class TypeWitnessReceiptPreservationTests(unittest.TestCase):
    def test_missing_declaration_is_not_accepted_as_an_empty_witness_list(self) -> None:
        declarations = ["Fixture.emptyWitnesses", "Fixture.unavailable"]
        with patch.object(
            AUDIT,
            "run_lean_type_witness_payload_safeties",
            return_value={"Fixture.emptyWitnesses": []},
        ):
            receipts, errors = AUDIT.lean_type_witness_payload_safeties(
                root=ROOT,
                import_module="Fixture.PaperInterface",
                qualified_declarations=declarations,
                no_lean=False,
            )
        self.assertEqual(receipts, {"Fixture.emptyWitnesses": []})
        self.assertFalse(any("Fixture.emptyWitnesses:" in error for error in errors))
        self.assertTrue(
            any(
                "Fixture.unavailable: Lean Type-witness payload-safety "
                "verification returned no valid receipt after "
                "declaration-local isolation" in error
                for error in errors
            ),
            errors,
        )


class EffectiveAnalysisManifestTests(unittest.TestCase):
    def test_exact_review_manifest_progress_is_rendered_without_affecting_surface(
        self,
    ) -> None:
        reviewed = "Fixture.PaperInterface.reviewed"
        manifest = {
            "sha256": "a" * 64,
            "elaborated_execution_state_refinement_shape": {
                "schema": 1,
                "scan_complete": True,
                "has_refl_trans_gen_path": False,
                "has_relation_valued_state_transition": False,
                "detected": False,
            },
        }

        def fresh_manifests(*_args: object, **kwargs: object) -> dict[str, object]:
            callback = kwargs.get("progress_callback")
            self.assertTrue(callable(callback))
            assert callable(callback)
            callback(
                {
                    "batch_number": 1,
                    "batch_total": 1,
                    "root_count": 1,
                    "status": "started",
                }
            )
            callback(
                {
                    "batch_number": 1,
                    "batch_total": 1,
                    "root_count": 1,
                    "completed_count": 1,
                    "missing_count": 0,
                    "status": "finished",
                }
            )
            return {reviewed: manifest}

        with (
            patch(
                "scripts.lean_signature_manifest.run_lean_signature_manifests",
                side_effect=fresh_manifests,
            ),
            patch(
                "scripts.lean_signature_manifest.signature_manifest_digest",
                side_effect=lambda value: str(value["sha256"]),
            ),
            patch(
                "scripts.lean_signature_manifest.semantic_dependency_manifest",
                return_value={"semantic_dependency_sha256": "d" * 64},
            ),
            patch.object(AUDIT, "source_record_progress") as progress,
        ):
            digests, surfaces, errors = AUDIT.elaborated_review_signature_surfaces(
                root=ROOT,
                import_module="Fixture.PaperInterface",
                row_names=["reviewed"],
                qualified_row_refs={"reviewed": reviewed},
                no_lean=False,
            )

        self.assertEqual(errors, [])
        self.assertEqual(digests, {reviewed: "a" * 64})
        self.assertEqual(surfaces, {reviewed: manifest})
        self.assertEqual(
            [call.args[0] for call in progress.call_args_list],
            [
                "exact elaborated review-signature graph request 1/1 started (1 roots)",
                "exact elaborated review-signature graph request 1/1 finished (1 roots; 1 complete; 0 missing)",
            ],
        )

    def test_prevalidated_effective_and_record_roots_avoid_fresh_lean(self) -> None:
        """Every exact current request kind may reuse authenticated manifests."""

        def manifest(digest: str) -> dict[str, object]:
            return {
                "sha256": digest,
                "elaborated_execution_state_refinement_shape": {
                    "schema": 1,
                    "scan_complete": True,
                    "has_refl_trans_gen_path": False,
                    "has_relation_valued_state_transition": False,
                    "detected": False,
                },
            }

        reviewed = "Fixture.PaperInterface.reviewed"
        effective = "Fixture.Implementation.effective"
        record_root = "Fixture.Model.Record"
        prevalidated = {
            reviewed: manifest("a" * 64),
            effective: manifest("b" * 64),
            record_root: manifest("c" * 64),
        }
        with (
            patch(
                "scripts.lean_signature_manifest.run_lean_signature_manifests",
                return_value={},
            ) as run_manifests,
            patch(
                "scripts.lean_signature_manifest.signature_manifest_digest",
                side_effect=lambda value: str(value["sha256"]),
            ),
            patch(
                "scripts.lean_signature_manifest.semantic_dependency_manifest",
                return_value={"semantic_dependency_sha256": "d" * 64},
            ),
        ):
            digests, surfaces, errors = AUDIT.elaborated_review_signature_surfaces(
                root=ROOT,
                import_module="Fixture.PaperInterface",
                row_names=["reviewed"],
                qualified_row_refs={"reviewed": reviewed},
                analysis_qualified_names=[effective],
                additional_qualified_names=[record_root],
                prevalidated_manifests=prevalidated,
                no_lean=False,
            )

        self.assertEqual(errors, [])
        self.assertEqual(run_manifests.call_args.args[2], [])
        self.assertEqual(
            digests,
            {reviewed: "a" * 64, effective: "b" * 64},
        )
        self.assertEqual(set(surfaces), {reviewed, effective, record_root})

    def test_prevalidated_review_root_reduces_fresh_lean_request(self) -> None:
        """Only exact prevalidated roots may bypass the fresh Lean batch."""

        def manifest(digest: str) -> dict[str, object]:
            return {
                "sha256": digest,
                "elaborated_execution_state_refinement_shape": {
                    "schema": 1,
                    "scan_complete": True,
                    "has_refl_trans_gen_path": False,
                    "has_relation_valued_state_transition": False,
                    "detected": False,
                },
            }

        reviewed = "Fixture.PaperInterface.reviewed"
        effective = "Fixture.Implementation.effective"
        record_root = "Fixture.Model.Record"
        prior = manifest("a" * 64)
        fresh = {
            effective: manifest("b" * 64),
            record_root: manifest("c" * 64),
        }
        with (
            patch(
                "scripts.lean_signature_manifest.run_lean_signature_manifests",
                return_value=fresh,
            ) as run_manifests,
            patch(
                "scripts.lean_signature_manifest.signature_manifest_digest",
                side_effect=lambda value: str(value["sha256"]),
            ),
            patch(
                "scripts.lean_signature_manifest.semantic_dependency_manifest",
                return_value={"semantic_dependency_sha256": "d" * 64},
            ),
        ):
            digests, surfaces, errors = AUDIT.elaborated_review_signature_surfaces(
                root=ROOT,
                import_module="Fixture.PaperInterface",
                row_names=["reviewed"],
                qualified_row_refs={"reviewed": reviewed},
                analysis_qualified_names=[effective],
                additional_qualified_names=[record_root],
                prevalidated_manifests={reviewed: prior},
                no_lean=False,
            )

        self.assertEqual(errors, [])
        self.assertEqual(
            run_manifests.call_args.args[2],
            sorted([effective, record_root]),
        )
        self.assertEqual(
            digests,
            {reviewed: "a" * 64, effective: "b" * 64},
        )
        self.assertEqual(set(surfaces), {reviewed, effective, record_root})

    def test_seed_rejected_prior_manifest_returns_to_fresh_lean_request(self) -> None:
        """A cache-seed rejection cannot retain prevalidated status."""

        def manifest(digest: str) -> dict[str, object]:
            return {
                "sha256": digest,
                "elaborated_execution_state_refinement_shape": {
                    "schema": 1,
                    "scan_complete": True,
                    "has_refl_trans_gen_path": False,
                    "has_relation_valued_state_transition": False,
                    "detected": False,
                },
            }

        accepted = "Fixture.PaperInterface.accepted"
        mutated = "Fixture.PaperInterface.mutated"
        prior = {
            accepted: manifest("a" * 64),
            mutated: manifest("b" * 64),
        }
        prevalidated = AUDIT.seeded_prior_review_signature_manifests(
            prior,
            {accepted},
        )
        fresh_mutated = manifest("c" * 64)
        with (
            patch(
                "scripts.lean_signature_manifest.run_lean_signature_manifests",
                return_value={mutated: fresh_mutated},
            ) as run_manifests,
            patch(
                "scripts.lean_signature_manifest.signature_manifest_digest",
                side_effect=lambda value: str(value["sha256"]),
            ),
            patch(
                "scripts.lean_signature_manifest.semantic_dependency_manifest",
                return_value={"semantic_dependency_sha256": "d" * 64},
            ),
        ):
            digests, surfaces, errors = AUDIT.elaborated_review_signature_surfaces(
                root=ROOT,
                import_module="Fixture.PaperInterface",
                row_names=["accepted", "mutated"],
                qualified_row_refs={
                    "accepted": accepted,
                    "mutated": mutated,
                },
                prevalidated_manifests=prevalidated,
                no_lean=False,
            )

        self.assertEqual(errors, [])
        self.assertEqual(run_manifests.call_args.args[2], [mutated])
        self.assertEqual(digests[accepted], "a" * 64)
        self.assertEqual(digests[mutated], "c" * 64)
        self.assertEqual(set(surfaces), {accepted, mutated})

