    def test_raw_resume_bindings_are_reconstructed_from_frozen_map_sources(self) -> None:
        """The journal coordinate is a frozen source binding, not a row label."""

        qualified = "Fixture.PaperInterface.reviewed"
        frozen_source = (
            "namespace Fixture.PaperInterface\n"
            "theorem reviewed : True := by trivial\n"
            "theorem unconfigured : False := by contradiction\n"
            "end Fixture.PaperInterface\n"
        )
        with tempfile.TemporaryDirectory() as temporary:
            paper_dir = Path(temporary) / "Fixture"
            paper_dir.mkdir()
            interface = paper_dir / "PaperInterface.lean"
            # The mutable worktree text must not influence a raw scan's
            # checkpoint coordinate once the scan captured its source bytes.
            interface.write_text(
                "namespace Fixture.PaperInterface\n"
                "theorem reviewed : False := by contradiction\n"
                "end Fixture.PaperInterface\n",
                encoding="utf-8",
            )
            bindings, duplicates = AUDIT.source_record_current_manifest_resume_bindings(
                paper_dir=paper_dir,
                qualified_row_refs={"nonsemantic-map-row": qualified},
                selected_row_source_paths={"nonsemantic-map-row": interface},
                source_text_by_path={interface.resolve(): frozen_source},
            )

        self.assertEqual(duplicates, set())
        self.assertEqual(set(bindings), {qualified})
        self.assertEqual(bindings[qualified]["source_file"], "PaperInterface.lean")
        self.assertEqual(bindings[qualified]["line_number"], 2)
        self.assertIn("theorem reviewed : True", bindings[qualified]["lean_source_declaration"])
        self.assertNotIn("unconfigured", bindings[qualified]["lean_source_declaration"])

    def test_authenticated_publish_includes_validated_nonrow_manifests(self) -> None:
        reviewed = "Fixture.PaperInterface.reviewed"
        structural = "Fixture.Model.Structural"
        malformed = "Fixture.Model.Malformed"
        dependency = "d" * 64

        def manifest(digest: str, *, graph: object) -> dict[str, object]:
            return {
                "sha256": digest,
                "dependency": dependency,
                "elaborated_proposition_graph": graph,
            }

        reviewed_manifest = manifest("a" * 64, graph={"schema": 1})
        structural_manifest = manifest("b" * 64, graph={"schema": 1, "nodes": []})
        malformed_manifest = manifest("c" * 64, graph=None)
        reviewed_graph_sha256 = AUDIT.elaborated_proposition_graph_sha256(
            reviewed_manifest["elaborated_proposition_graph"]
        )
        configured_row = {
            "qualified_declaration": reviewed,
            "elaborated_signature_sha256": "a" * 64,
            "semantic_dependency_sha256": dependency,
            "elaborated_proposition_graph_sha256": reviewed_graph_sha256,
        }
        with (
            patch.object(AUDIT, "signature_manifest_cache_context", return_value={}),
            patch.object(
                AUDIT,
                "signature_manifest_digest",
                side_effect=lambda value: str(value["sha256"]),
            ),
            patch.object(
                AUDIT,
                "semantic_dependency_manifest",
                side_effect=lambda value: {
                    "semantic_dependency_sha256": value["dependency"]
                },
            ),
            patch.object(
                AUDIT,
                "merge_authenticated_manifest_store",
                # A shared store may retain a valid root owned by another
                # producer.  It must not be reported as accepted by this raw
                # source-record publication.
                return_value={reviewed, structural, "Fixture.Prior.retained"},
            ) as publish,
        ):
            accepted = AUDIT.publish_source_record_signature_manifest_store(
                root=ROOT,
                paper_dir=ROOT / "papers" / "Fixture",
                import_module="Fixture.PaperInterface",
                semantic_dependency_modules=("Fixture.PaperInterface",),
                configured_review_rows=[configured_row],
                manifests={
                    reviewed: reviewed_manifest,
                    structural: structural_manifest,
                    malformed: malformed_manifest,
                },
            )

        self.assertEqual(accepted, {reviewed, structural})
        candidates = {
            candidate["qualified_declaration"]: candidate
            for candidate in publish.call_args.kwargs["candidates"]
        }
        self.assertEqual(set(candidates), {reviewed, structural})
        binding = candidates[structural]["authority_binding"]
        self.assertEqual(binding["kind"], "successful_source_record_manifest")
        self.assertEqual(binding["qualified_declaration"], structural)
        self.assertEqual(binding["elaborated_signature_sha256"], "b" * 64)
        self.assertEqual(binding["semantic_dependency_sha256"], dependency)
        self.assertEqual(
            binding["elaborated_proposition_graph_sha256"],
            AUDIT.elaborated_proposition_graph_sha256(
                structural_manifest["elaborated_proposition_graph"]
            ),
        )
        self.assertNotIn("elaborated_proposition_graph", binding)

