    def _run_reuse(
        self,
        *,
        current_source: str = "theorem reviewed : True := by trivial",
        cached_context_override: dict[str, object] | None = None,
        current_context_override: dict[str, object] | None = None,
        carrier_row_count: int = 1,
        source_authorized: bool = True,
        dependency_digest: str | None = None,
        item_revalidation_matches: bool = True,
    ) -> tuple[dict[str, dict[str, object]], dict[str, object]]:
        from scripts import review_dashboard

        qualified = "Fixture.PaperInterface.reviewed"
        signature = "a" * 64
        prior_dependency = "b" * 64
        declaration = "theorem reviewed : True := by trivial"
        context: dict[str, object] = {
            "schema": 3,
            "import_module": "Fixture.PaperInterface",
            "olean_fingerprint": ["c" * 64, 10],
            "helper_fingerprint": ["d" * 64, 20],
            "semantic_hash_tool_identity": {
                "resolved_path": "/fixture/hash",
                "sha256": "e" * 64,
            },
            "canonical_representation": MANIFESTS.CANONICAL_REPRESENTATION,
            "audit_scope_fingerprint": MANIFESTS._audit_scope_fingerprint(
                "Fixture.PaperInterface",
                ("c" * 64, 10),
                ("Fixture.PaperInterface",),
            ),
            "audit_modules": ["Fixture.PaperInterface"],
            "semantic_module_fingerprints": [
                ["Fixture.PaperInterface", ["c" * 64, 10]]
            ],
        }
        cached_context = dict(context)
        current_context = dict(context)
        if cached_context_override:
            cached_context.update(cached_context_override)
        if current_context_override:
            current_context.update(current_context_override)
        proposition_graph = {"schema": 1, "nodes": []}
        manifest = {
            "sha256": signature,
            "carrier": "full Lean graph",
            "elaborated_proposition_graph": proposition_graph,
        }
        raw = {
            "paper": "Fixture",
            "configured_review_rows": [
                {
                    "row": "reviewed",
                    "qualified_declaration": qualified,
                    "lean_source_declaration": declaration,
                    "elaborated_signature_sha256": signature,
                    "semantic_dependency_sha256": prior_dependency,
                    "elaborated_proposition_graph_sha256": (
                        AUDIT.elaborated_proposition_graph_sha256(
                            proposition_graph
                        )
                    ),
                }
            ],
        }
        carrier_row = {
            "full_name": qualified,
            "lean_signature_sha256": signature,
            "lean_signature_manifest": manifest,
        }
        cache = {
            "schema": review_dashboard.PAPER_INTERFACE_CACHE_SCHEMA,
            "paper": "Fixture",
            "rows": [dict(carrier_row) for _ in range(carrier_row_count)],
            "signature_contexts": {"PaperInterface.lean": cached_context},
        }
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            paper_dir = root / "papers" / "Fixture"
            source_path = paper_dir / "PaperInterface.lean"

            def loaded(path: Path) -> dict[str, object]:
                return raw if Path(path).name == "source_record_audit.json" else cache

            with (
                patch.object(AUDIT, "load_json_object", side_effect=loaded),
                patch.object(AUDIT, "source_record_audit_receipt_error", return_value=""),
                patch.object(
                    AUDIT,
                    "source_record_raw_reusable_item_metadata_error",
                    return_value="",
                ),
                patch.object(
                    AUDIT,
                    "source_record_raw_scan_completeness_error",
                    return_value="",
                ),
                patch.object(
                    AUDIT,
                    "_source_record_prior_manifest_source_authority",
                    return_value={qualified} if source_authorized else set(),
                ),
                patch.object(AUDIT, "source_proof_fidelity_context", return_value={}),
                patch.object(
                    AUDIT,
                    "signature_manifest_cache_context",
                    return_value=current_context,
                ),
                patch.object(
                    AUDIT,
                    "signature_manifest_digest",
                    side_effect=lambda value: str(value.get("sha256") or ""),
                ),
                patch.object(
                    AUDIT,
                    "run_lean_signature_manifest_revalidations",
                    return_value={
                        qualified: {
                            "schema": 1,
                            "semantic_dependency_graph": {},
                            "elaborated_execution_state_refinement_shape": {},
                        }
                    },
                ),
                patch.object(
                    AUDIT,
                    "signature_manifest_item_revalidation_matches",
                    return_value=item_revalidation_matches,
                ),
                patch.object(
                    AUDIT,
                    "reattach_semantic_dependency_module_identities",
                    side_effect=lambda _root, manifests, timeout_seconds: {
                        key: dict(value) for key, value in manifests.items()
                    },
                ),
                patch.object(
                    AUDIT,
                    "semantic_dependency_manifest",
                    return_value={
                        "semantic_dependency_sha256": dependency_digest
                        or prior_dependency
                    },
                ),
                patch.object(
                    review_dashboard,
                    "paper_interface_cache_file",
                    return_value=paper_dir
                    / ".review_traces"
                    / "paper_interface_cache.json",
                ),
                patch.object(
                    review_dashboard,
                    "review_source_module",
                    return_value="Fixture.PaperInterface",
                ),
                patch.object(
                    review_dashboard,
                    "paper_owned_module_names_in_import_closure",
                    return_value=("Fixture.PaperInterface",),
                ),
            ):
                return AUDIT.reusable_prior_review_signature_manifests(
                    root=root,
                    paper_dir=paper_dir,
                    requested_declaration_sources={qualified: current_source},
                    requested_declaration_source_paths={qualified: source_path},
                    source_contract_statement_map={"items": {}},
                )

