def reusable_item_receipt(
    kind: str,
    digest: str,
    *,
    marker: str = "a",
) -> dict[str, object]:
    """Return a complete generated item-local reuse receipt for tests."""

    alternate = "b" if marker == "a" else "a"
    return {
        "source_record_item_digest_schema": REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
        "source_record_item_semantic_id": marker * 64,
        "source_record_item_context_sha256": alternate * 64,
        "source_record_item_sha256": digest,
        "reviewed_elaborated_signature_identities": [
            {
                "qualified_declaration": "Fixture.PaperInterface.fixture_row",
                "elaborated_signature_sha256": ("c" if marker == "a" else "d")
                * 64,
            }
        ],
        "source_record_item_reuse_eligibility": {
            "eligible": True,
            "blockers": [],
        },
    }


