    def test_target_route_and_generated_item_omissions_fail_closed(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            paper, configured, qualified, statement_map = self._fixture(Path(tmpdir))
            targets = [self.EVIDENCE]

