class RecursiveFieldSelectedRouteScopeTests(unittest.TestCase):
    @staticmethod
    def manifest(root: str, edges: list[tuple[str, str, str]]) -> dict[str, object]:
        names = {root}
        for source, target, _role in edges:
            names.update({source, target})
        return {
            "semantic_dependency_graph": {
                "schema": 1,
                "root_declaration": root,
                "complete": True,
                "realization_complete": True,
                "nodes": [
                    {
                        "declaration": name,
                        "module_origin": "Fixture",
                        "origin_class": "review_closure",
                        "declaration_kind": "theorem",
                        "semantic_identity_sha256": hashlib.sha256(
                            name.encode("utf-8")
                        ).hexdigest(),
                        "statement_reachable": True,
                    }
                    for name in sorted(names)
                ],
                "edges": [
                    {"source": source, "target": target, "role": role}
                    for source, target, role in edges
                ],
                "failures": [],
                "semantic_external_module_origins": [],
                "realization_external_module_origins": [],
                "semantic_graph_sha256": "a" * 64,
                "realization_graph_sha256": "b" * 64,
            }
        }

    def test_exact_elaborated_edge_selects_reachable_support_only(self) -> None:
        root = "Fixture.Interface.Iris"
        reachable = "Fixture.Support.Cedar"
        dormant = "Fixture.Support.Larch"
        scope = AUDIT.recursive_field_rows_reachable_from_selected_review_routes(
            source_selected_rows=["ordinary"],
            formalization_scope_target_rows=[],
            effective_rows=["ordinary", "reachable", "dormant"],
            qualified_row_refs={
                "ordinary": root,
                "reachable": reachable,
                "dormant": dormant,
            },
            local_declarations=[],
            elaborated_signature_sha256_by_qualified={root: "c" * 64},
            elaborated_manifests_by_qualified={
                root: self.manifest(
                    root, [(root, reachable, "proof_uses_constant")]
                )
            },
        )
        self.assertTrue(scope["reachability_analysis_complete"])
        self.assertEqual(scope["included_rows"], ["ordinary", "reachable"])
        self.assertEqual(
            scope["excluded_unreachable_supplemental_rows"], ["dormant"]
        )
        reached = next(item for item in scope["rows"] if item["row"] == "reachable")
        self.assertEqual(
            reached["selected_route_paths"][0]["declaration_path"],
            [root, reachable],
        )

    def test_source_tokens_and_comments_cannot_create_graph_edges(self) -> None:
        root = "Fixture.Interface.Iris"
        dormant = "Fixture.Support.Cedar"
        lexical_decoy = local_declaration(
            root,
            "theorem Iris : True := by -- Cedar\n  trivial",
        )
        scope = AUDIT.recursive_field_rows_reachable_from_selected_review_routes(
            source_selected_rows=["ordinary"],
            formalization_scope_target_rows=[],
            effective_rows=["ordinary", "dormant"],
            qualified_row_refs={"ordinary": root, "dormant": dormant},
            local_declarations=[lexical_decoy],
            elaborated_manifests_by_qualified={root: self.manifest(root, [])},
        )
        self.assertTrue(scope["reachability_analysis_complete"])
        self.assertEqual(scope["included_rows"], ["ordinary"])
        self.assertEqual(
            scope["excluded_unreachable_supplemental_rows"], ["dormant"]
        )

    def test_missing_graph_fails_closed_and_retains_supplemental_rows(self) -> None:
        root = "Fixture.Interface.Iris"
        supplemental = "Fixture.Support.Cedar"
        scope = AUDIT.recursive_field_rows_reachable_from_selected_review_routes(
            source_selected_rows=["ordinary"],
            formalization_scope_target_rows=[],
            effective_rows=["ordinary", "support"],
            qualified_row_refs={"ordinary": root, "support": supplemental},
            local_declarations=[],
            elaborated_manifests_by_qualified={},
        )
        self.assertFalse(scope["reachability_analysis_complete"])
        self.assertEqual(scope["included_rows"], ["ordinary", "support"])
        self.assertTrue(scope["analysis_errors"])


class RawProducerTransitiveIdentityTests(unittest.TestCase):
    def test_registered_engine_tree_memoizes_raw_producer_identity(self) -> None:
        """An exact clean engine may reuse provenance, never a mutable result."""

        identity = {
            "path": (
                "skills/econcs-formalizer/scripts/source_record_audit.py"
                "#fresh-raw-generation"
            ),
            "sha256": "a" * 64,
            "status": "present",
        }
        producer = Mock(return_value=identity)
        AUDIT._registered_raw_generation_code_identity.cache_clear()
        try:
            with (
                patch.object(
                    AUDIT,
                    "_UNCACHED_SOURCE_RECORD_RAW_GENERATION_CODE_IDENTITY",
                    producer,
                ),
                patch.object(
                    AUDIT,
                    "_source_record_raw_generation_code_identity",
                    producer,
                ),
                patch.object(
                    AUDIT,
                    "validate_runtime_engine_registration",
                    return_value=SimpleNamespace(engine_tree_sha256="b" * 64),
                ),
            ):
                first = AUDIT.source_record_raw_producer_code_identities()
                producer_entry = next(
                    item for item in first if item["path"].endswith("#fresh-raw-generation")
                )
                producer_entry["sha256"] = "mutated by caller"
                second = AUDIT.source_record_raw_producer_code_identities()
        finally:
            AUDIT._registered_raw_generation_code_identity.cache_clear()

        producer.assert_called_once_with()
        second_entry = next(
            item for item in second if item["path"].endswith("#fresh-raw-generation")
        )
        self.assertEqual(second_entry, identity)

    def test_dirty_or_unregistered_engine_recomputes_raw_producer_identity(
        self,
    ) -> None:
        """No cache may authenticate provenance without exact engine bytes."""

        identity = {
            "path": (
                "skills/econcs-formalizer/scripts/source_record_audit.py"
                "#fresh-raw-generation"
            ),
            "sha256": "c" * 64,
            "status": "present",
        }
        producer = Mock(return_value=identity)
        AUDIT._registered_raw_generation_code_identity.cache_clear()
        try:
            with (
                patch.object(
                    AUDIT,
                    "_UNCACHED_SOURCE_RECORD_RAW_GENERATION_CODE_IDENTITY",
                    producer,
                ),
                patch.object(
                    AUDIT,
                    "_source_record_raw_generation_code_identity",
                    producer,
                ),
                patch.object(
                    AUDIT,
                    "validate_runtime_engine_registration",
                    side_effect=AUDIT.EngineRevisionError("unregistered engine"),
                ),
            ):
                AUDIT.source_record_raw_producer_code_identities()
                AUDIT.source_record_raw_producer_code_identities()
        finally:
            AUDIT._registered_raw_generation_code_identity.cache_clear()

        self.assertEqual(producer.call_count, 2)

    def test_identity_is_independent_of_checkout_path(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            parent = Path(tmpdir)

            def make_checkout(name: str) -> tuple[Path, Path]:
                root = parent / name
                scripts = root / "scripts"
                scripts.mkdir(parents=True)
                (scripts / "helper.py").write_text(
                    "def semantic_value():\n    return 1\n",
                    encoding="utf-8",
                )
                entry = root / "producer.py"
                entry.write_text(
                    "from scripts.helper import semantic_value\n"
                    "def _run_audit():\n"
                    f"    {SOURCE_RECORD_RAW_PRODUCER_BEGIN_MARKER}\n"
                    "    result = semantic_value()\n"
                    f"    {SOURCE_RECORD_RAW_PRODUCER_END_MARKER}\n"
                    "    return result\n",
                    encoding="utf-8",
                )
                return root, entry

            first_root, first_entry = make_checkout("first-clone")
            second_root, second_entry = make_checkout("unrelated/worktree")
            first = AUDIT._source_record_raw_generation_code_identity(
                entry_path=first_entry, repository_root=first_root
            )
            second = AUDIT._source_record_raw_generation_code_identity(
                entry_path=second_entry, repository_root=second_root
            )

        self.assertEqual(first["status"], "present")
        self.assertEqual(second, first)

