    def test_cross_module_second_level_change_invalidates_but_unrelated_does_not(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            scripts = root / "scripts"
            scripts.mkdir()
            entry = root / "producer.py"
            entry.write_text(
                "from scripts.first import first\n"
                "def _run_audit():\n"
                f"    {SOURCE_RECORD_RAW_PRODUCER_BEGIN_MARKER}\n"
                "    result = first()\n"
                f"    {SOURCE_RECORD_RAW_PRODUCER_END_MARKER}\n"
                "    return result\n",
                encoding="utf-8",
            )
            first = scripts / "first.py"
            first.write_text(
                "from scripts.second import second\n"
                "def first():\n"
                "    return second()\n"
                "def unrelated():\n"
                "    return 10\n",
                encoding="utf-8",
            )
            second = scripts / "second.py"
            second.write_text("def second():\n    return 1\n", encoding="utf-8")

            def identity() -> dict[str, str]:
                return AUDIT._source_record_raw_generation_code_identity(
                    entry_path=entry, repository_root=root
                )

            baseline = identity()
            self.assertEqual(baseline["status"], "present")
            first.write_text(
                "from scripts.second import second\n"
                "def first():\n"
                "    return second()\n"
                "def unrelated():\n"
                "    return 999\n",
                encoding="utf-8",
            )
            self.assertEqual(identity(), baseline)
            second.write_text("def second():\n    return 2\n", encoding="utf-8")
            changed = identity()
            self.assertEqual(changed["status"], "present")
            self.assertNotEqual(changed["sha256"], baseline["sha256"])

    def test_unresolved_repository_import_fails_closed(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
