class SemanticModelReviewTests(unittest.TestCase):
    def test_transparent_spec_owner_uses_validated_value_telescope_only(self) -> None:
        def atom(ref: str, role: str, canonical: object) -> dict[str, object]:
            value: dict[str, object] = {
                "ref": ref,
                "role": role,
                "canonical": canonical,
                "display": str(canonical),
            }
            if role != "conclusion":
                value["binder_info"] = "explicit"
            return value

        proof = "Fixture.Paper.proof"
        spec = "Fixture.Paper.spec"
        surface = AUDIT.SemanticModelReviewSurface(
            reviewed_qualified_name=spec,
            reviewed_declaration="def spec : Prop := True",
            effective_declaration=local_declaration(
                proof, "theorem proof : spec := by trivial"
            ),
            review_alias_expansion={
                "schema": 2,
                "route_kind": "explicit_structurally_validated_semantic_contract_companion",
                "complete": True,
                "structural_alpha_normalized_equal": True,
                "surface_role": "transparent_spec_body_owner",
                "reviewed_declaration": spec,
                "effective_declaration": proof,
            },
            uses_effective_target=True,
            analysis_qualified_name=proof,
            analysis_declaration="def spec : Prop := True",
            header_inputs=[{"names": "x", "type": "Nat"}],
            conclusion_inputs=[
                {
                    "names": "h",
                    "type": "P x",
                    "input_origin": "result_forall",
                }
            ],
        )
        full_manifest = {
            "sha256": "a" * 64,
            "atoms": [
                atom("b/0", "parameter", {"tag": "x"}),
                atom("b/1", "assumption", {"tag": "h"}),
                # This atom is introduced by terminal proposition reduction,
                # not by the source-written transparent definition value.
                atom("b/2", "parameter", {"tag": "reduced"}),
                atom("result", "conclusion", {"tag": "result"}),
            ],
        }
        presentation = {
            "schema": 1,
            "reduction": "definition_value_outer_telescope",
            "atoms": [
                atom("b/0", "parameter", {"tag": "x"}),
                atom("b/1", "assumption", {"tag": "h"}),
                atom("result", "conclusion", {"tag": "spec-result"}),
            ],
        }
        positional, routes, errors = AUDIT.semantic_contract_positional_signature_manifests(
            review_surfaces={"spec_row": surface},
            elaborated_manifests_by_qualified={
                proof: full_manifest,
                spec: {"transparent_value_presentation_telescope": presentation},
            },
        )
        self.assertEqual(errors, [])
        self.assertEqual(
            [atom["ref"] for atom in positional["spec_row"]["atoms"]],
            ["b/0", "b/1", "result"],
        )
        self.assertEqual(
            positional["spec_row"]["sha256"],
            positional["spec_row"][
                "transparent_spec_presentation_telescope_sha256"
            ],
        )
        self.assertEqual(
            positional["spec_row"]["paired_proof_signature_sha256"],
            "a" * 64,
        )
        self.assertEqual(
            positional["spec_row"]["atoms"][-1],
            presentation["atoms"][-1],
        )
        self.assertNotEqual(
            positional["spec_row"]["atoms"][-1],
            full_manifest["atoms"][-1],
        )
        self.assertEqual(
            routes["spec_row"]["route_kind"],
            "validated_transparent_spec_definition_value_telescope",
        )
        _, unadapted_errors = AUDIT.elaborated_visible_input_binder_atom_groups(
            visible_inputs=surface.header_inputs,
            manifest=full_manifest,
        )
        self.assertTrue(unadapted_errors)
        _, adapted_errors = AUDIT.elaborated_visible_input_binder_atom_groups(
            visible_inputs=surface.header_inputs + surface.conclusion_inputs,
            manifest=positional["spec_row"],
        )
        self.assertEqual(adapted_errors, [])
        paths, path_errors = AUDIT.elaborated_result_input_path_receipts(
            header_inputs=surface.header_inputs,
            conclusion_inputs=surface.conclusion_inputs,
            manifest=positional["spec_row"],
        )
        self.assertEqual(path_errors, [])
        self.assertEqual(
            paths[0]["terminal_conclusion_atom"],
            AUDIT.signature_manifest_atom_identity(presentation["atoms"][-1]),
        )

        mismatched = deepcopy(presentation)
        mismatched["atoms"][1]["canonical"] = {"tag": "other"}
        _, _, mismatch_errors = AUDIT.semantic_contract_positional_signature_manifests(
            review_surfaces={"spec_row": surface},
            elaborated_manifests_by_qualified={
                proof: full_manifest,
                spec: {"transparent_value_presentation_telescope": mismatched},
            },
        )
        self.assertTrue(
            any("not an exact prefix" in error for error in mismatch_errors),
            mismatch_errors,
        )

    def test_graph_pair_defers_only_until_complete_manifest_phase(self) -> None:
        evidence = "Fixture.Paper.route"
        spec = "Fixture.Paper.payload"
        evidence_source = "theorem route : payload := by sorry"
        spec_source = (
            "def payload : Prop := by\n"
            "  exact forall n : Nat, n = n"
        )
        semantic_declarations = [
            local_declaration(evidence, evidence_source),
            local_declaration(spec, spec_source),
        ]
        routes = [
            {
                "source_item": "source_theorem",
                "evidence_declaration": evidence,
                "spec_declaration": spec,
            }
        ]
        manifests = elaborated_bare_spec_pair_manifests(evidence, spec)

        provisional_surfaces, provisional_errors = (
            AUDIT.semantic_model_review_contract_companion_surfaces(
                companion_routes=routes,
                semantic_declarations=semantic_declarations,
                proposition_aliases=AUDIT.parse_proposition_aliases(
                    semantic_declarations
                ),
                type_aliases=None,
                elaborated_manifests_by_qualified={
                    evidence: manifests[evidence]
                },
                defer_manifest_dependent_errors=True,
            )
        )
        self.assertEqual(provisional_surfaces, {})
        self.assertEqual(provisional_errors, [])

        missing_surfaces, missing_errors = (
            AUDIT.semantic_model_review_contract_companion_surfaces(
                companion_routes=routes,
                semantic_declarations=semantic_declarations,
                proposition_aliases=AUDIT.parse_proposition_aliases(
                    semantic_declarations
                ),
                type_aliases=None,
                elaborated_manifests_by_qualified={
                    evidence: manifests[evidence]
                },
            )
        )
        self.assertEqual(missing_surfaces, {})
        self.assertTrue(
            any("not an exact transparent" in error for error in missing_errors),
            missing_errors,
        )

        bad_manifests = elaborated_bare_spec_pair_manifests(
            evidence,
            spec,
            extra_type_target="Fixture.Paper.unrelated",
        )
        bad_surfaces, bad_errors = (
            AUDIT.semantic_model_review_contract_companion_surfaces(
                companion_routes=routes,
                semantic_declarations=semantic_declarations,
                proposition_aliases=AUDIT.parse_proposition_aliases(
                    semantic_declarations
                ),
                type_aliases=None,
                elaborated_manifests_by_qualified=bad_manifests,
            )
        )
        self.assertEqual(bad_surfaces, {})
        self.assertTrue(
            any("not an exact transparent" in error for error in bad_errors),
            bad_errors,
        )

    def test_transparent_spec_bare_result_uses_exact_lean_graph_pair(self) -> None:
        """A ProofInterface endpoint may name, rather than repeat, its Spec."""

        evidence = "Fixture.ProofInterface.route"
        spec = "Fixture.PaperInterface.payload"
        evidence_source = "theorem route : PaperInterface.payload := by sorry"
        spec_source = "def payload : Prop := forall n : Nat, n = n"
        semantic_declarations = [
            local_declaration(evidence, evidence_source),
            local_declaration(spec, spec_source),
        ]
        manifests = elaborated_bare_spec_pair_manifests(evidence, spec)

