    def test_contract_pair_reconciles_omitted_leading_spec_parameters(self) -> None:
        """Header-aligned omitted implicits use enclosing binders, not placeholders."""

        spec = local_declaration(
            "Fixture.Paper.payload",
            "def payload {Alpha Beta : Type} [Inhabited Alpha] [Inhabited Beta] "
            "(f : Alpha -> Beta) : Prop := "
            "forall (x : Alpha), f x = f x",
        )
        evidence = local_declaration(
            "Fixture.Paper.route",
            "theorem route {Left Right : Type} [Inhabited Left] [Inhabited Right] "
            "(g : Left -> Right) : payload g := by sorry",
        )
        aliases = AUDIT.parse_proposition_aliases([spec, evidence])
        surfaces = AUDIT.semantic_contract_pair_structural_surfaces(
            evidence_qualified_name=evidence.name,
            evidence_source=evidence.source,
            spec_qualified_name=spec.name,
            spec_source=spec.source,
            proposition_aliases=aliases,
            type_aliases=None,
        )

        self.assertIsNotNone(surfaces)
        assert surfaces is not None
        self.assertEqual(surfaces[0], surfaces[1])
        self.assertTrue(
            AUDIT.precloseout_contract_pair_has_equal_signature_surface(
                evidence.source,
                spec.source,
                evidence_qualified=evidence.name,
                spec_qualified=spec.name,
                proposition_aliases=aliases,
                type_aliases=None,
            )
        )

        nonaligned_evidence = local_declaration(
            "Fixture.Paper.nonaligned",
            "theorem nonaligned {Left Right : Type} [Inhabited Left] "
            "[Inhabited Right] (g : Left -> Left) : payload g := by sorry",
        )
        self.assertIsNone(
            AUDIT.semantic_contract_pair_structural_surfaces(
                evidence_qualified_name=nonaligned_evidence.name,
                evidence_source=nonaligned_evidence.source,
                spec_qualified_name=spec.name,
                spec_source=spec.source,
                proposition_aliases=aliases,
                type_aliases=None,
            )
        )

        named_evidence = local_declaration(
            "Fixture.Paper.named",
            "theorem named {Left Right : Type} [Inhabited Left] "
            "[Inhabited Right] (g : Left -> Right) : "
            "payload (f := g) := by sorry",
        )
        self.assertIsNone(
            AUDIT.semantic_contract_pair_structural_surfaces(
                evidence_qualified_name=named_evidence.name,
                evidence_source=named_evidence.source,
                spec_qualified_name=spec.name,
                spec_source=spec.source,
                proposition_aliases=aliases,
                type_aliases=None,
            )
        )

    def test_contract_pair_accepts_transparent_local_instance_spec(self) -> None:
        """A canonical scoped instance still exposes every Prop premise."""

        spec = local_declaration(
            "Fixture.Paper.payload",
            "def payload {Alpha : Type} [Fintype Alpha] (f : Alpha -> Nat) : Prop :=\n"
            "  letI : DecidableEq Alpha := Classical.decEq Alpha\n"
            "  forall x : Alpha, Ready x -> f x = f x",
        )
        evidence = local_declaration(
            "Fixture.Paper.route",
            "theorem route {Beta : Type} [Fintype Beta] (g : Beta -> Nat) : "
            "payload g := by sorry",
        )
        aliases = AUDIT.parse_proposition_aliases([spec, evidence])

        surfaces = AUDIT.semantic_contract_pair_structural_surfaces(
            evidence_qualified_name=evidence.name,
            evidence_source=evidence.source,
            spec_qualified_name=spec.name,
            spec_source=spec.source,
            proposition_aliases=aliases,
            type_aliases=None,
        )

        self.assertIsNotNone(surfaces)
        assert surfaces is not None
        self.assertEqual(surfaces[0], surfaces[1])
        self.assertIn("letI:DecidableEq", surfaces[0]["alpha_normalized_result"])

        analysis = AUDIT.semantic_model_spec_analysis_declaration(
            spec.source, surfaces[1]
        )
        self.assertNotIn("letI", analysis)
        companion_surfaces, errors = (
            AUDIT.semantic_model_review_contract_companion_surfaces(
                companion_routes=[
                    {
                        "source_item": "source_theorem",
                        "evidence_declaration": evidence.name,
                        "spec_declaration": spec.name,
                    }
                ],
                semantic_declarations=[spec, evidence],
                proposition_aliases=aliases,
                type_aliases=None,
            )
        )
        self.assertEqual(errors, [])
        self.assertEqual(
            companion_surfaces[spec.name].conclusion_inputs,
            [
                {
                    "names": "x",
                    "type": "Alpha",
                    "input_origin": "result_forall",
                },
                {
                    "names": "result_premise_1",
                    "type": "Ready x",
                    "input_origin": "result_arrow",
                },
            ],
        )

    def test_classical_instance_projection_rejects_arbitrary_local_bindings(self) -> None:
        """Only the canonical anonymous DecidableEq implementation is removable."""

        canonical = (
            "letI : DecidableEq Alpha := Classical.decEq Alpha\n"
            "  forall x : Alpha, Ready x -> Goal x"
        )
        self.assertEqual(
            AUDIT.semantic_model_strip_classical_decidable_eq_layout_instance(canonical),
            "  forall x : Alpha, Ready x -> Goal x",
        )
        for noncanonical in (
            "let count : Nat := 0\n  forall x : Alpha, Goal x",
            "letI instance : DecidableEq Alpha := Classical.decEq Alpha\n"
            "  forall x : Alpha, Goal x",
            "letI : DecidableEq Alpha := chooseDecidableEq Alpha\n"
            "  forall x : Alpha, Goal x",
            "letI : DecidableEq Alpha := Classical.decEq Beta\n"
            "  forall x : Alpha, Goal x",
            "letI : DecidableEq Alpha := Classical.decEq Alpha\n  Goal",
        ):
            self.assertEqual(
                AUDIT.semantic_model_strip_classical_decidable_eq_layout_instance(
                    noncanonical
                ),
                noncanonical,
            )

