        self.assertEqual(original_errors, [])
        self.assertEqual(renamed_errors, [])
        self.assertEqual(original, renamed)
        self.assertEqual(original[0][0]["ref"], "b/0")
        self.assertEqual(original[1][0]["ref"], "b/1")

