    def test_record_dependency_carries_name_independent_lean_binder_atoms(self) -> None:
        manifest = elaborated_dependency_manifest(
            "Fixture.reviewed",
            atoms=[
                {
                    "ref": "b/0",
                    "role": "parameter",
                    "binder_info": "default",
                    "canonical": {"tag": "fixture-model"},
                },
                {
                    "ref": "b/1",
                    "role": "parameter",
                    "binder_info": "default",
                    "canonical": {"tag": "fixture-model"},
                },
                {
                    "ref": "result",
                    "role": "conclusion",
                    "canonical": {"tag": "fixture-result"},
                },
            ],
        )
        model = AUDIT.StructureInfo(
            name="Fixture.Model",
            source_file="papers/Fixture/Model.lean",
            line=1,
            parameters=[],
            parameter_types={},
            fields=[fixture_field("Fixture.Model", "valid", "True")],
        )

        def dependencies(names: str) -> tuple[list[dict[str, object]], list[str]]:
            declaration = (
                f"theorem reviewed ({names} : Fixture.Model) : True := by trivial"
            )
            errors: list[str] = []
            items = AUDIT.conclusion_dependency_items(
                row_names=["reviewed"],
                declarations={"reviewed": declaration},
                row_inputs={
                    "reviewed": AUDIT.visible_inputs_from_declaration(declaration)
                },
                row_records={"reviewed": ["Fixture.Model"]},
                fields_by_root={"Fixture.Model": model.fields},
                local_declarations=[],
                aliases={},
                structures={"Fixture.Model": model},
                proposition_heads={"True"},
                data_heads=set(AUDIT.KNOWN_DATA_TYPE_HEADS),
                semantic_declarations=[],
                proposition_aliases={},
                row_qualified_names={"reviewed": "Fixture.reviewed"},
                elaborated_manifests_by_qualified={
                    "Fixture.reviewed": manifest
                },
                elaborated_input_atom_errors=errors,
            )
            return items, errors

        original, original_errors = dependencies("first second")
        renamed, renamed_errors = dependencies("renamedFirst renamedSecond")
        self.assertEqual(original_errors, [])
        self.assertEqual(renamed_errors, [])
        self.assertEqual(len(original), 1)
        self.assertEqual(len(renamed), 1)
        self.assertEqual(
            original[0]["elaborated_outer_binder_atoms"],
            renamed[0]["elaborated_outer_binder_atoms"],
        )
        self.assertEqual(
            original[0]["fully_qualified_expanded_binder_type_canonical"],
            "Fixture.Model",
        )

        missing_errors: list[str] = []
        declaration = "theorem reviewed (model : Fixture.Model) : True := by trivial"
        missing = AUDIT.conclusion_dependency_items(
            row_names=["reviewed"],
            declarations={"reviewed": declaration},
            row_inputs={
                "reviewed": AUDIT.visible_inputs_from_declaration(declaration)
            },
            row_records={"reviewed": ["Fixture.Model"]},
            fields_by_root={"Fixture.Model": model.fields},
            local_declarations=[],
            aliases={},
            structures={"Fixture.Model": model},
            proposition_heads={"True"},
            data_heads=set(AUDIT.KNOWN_DATA_TYPE_HEADS),
            semantic_declarations=[],
            proposition_aliases={},
            row_qualified_names={"reviewed": "Fixture.reviewed"},
            elaborated_manifests_by_qualified={},
            elaborated_input_atom_errors=missing_errors,
        )
        self.assertEqual(len(missing), 1)
        self.assertEqual(missing[0]["elaborated_outer_binder_atoms"], [])
        self.assertTrue(missing_errors)

