    def test_execution_refinement_migration_reissues_only_source_routed_legacy_surface(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            paper_dir = Path(tmpdir) / "papers" / "Fixture"
            audit_dir = paper_dir / "audit"
            audit_dir.mkdir(parents=True)
            payload = {
                "semantic_model_items": [
                    {
                        "source_statement_association": {
                            "role": AUDIT.EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE,
                            "source_item_identities": [{"source_key": "result"}],
                        },
                        "semantic_shape_flags": {},
                        "expanded_lean_surface": {
                            "binder_domains": [],
                            "record_parameter_types": [],
                            "record_field_types": [
                                {"expanded_type": "State → State → Prop"},
                                {
                                    "expanded_type": (
                                        "Relation.ReflTransGen transition initial terminal"
                                    )
                                },
                            ],
                            "terminal_result": {"expanded_type": "True"},
                        },
                    }
                ]
            }
            (audit_dir / "source_record_audit.json").write_text(
                json.dumps(payload), encoding="utf-8"
            )
            self.assertTrue(
                AUDIT.source_record_raw_has_execution_state_refinement_surface(
                    paper_dir
                )
            )

            payload["semantic_model_items"][0].pop("source_statement_association")
            (audit_dir / "source_record_audit.json").write_text(
                json.dumps(payload), encoding="utf-8"
            )
            self.assertFalse(
                AUDIT.source_record_raw_has_execution_state_refinement_surface(
                    paper_dir
                )
            )

    def test_semantic_model_expands_type_aliases_and_result_only_records(self) -> None:
        aliases = AUDIT.parse_semantic_type_aliases(
            [
                local_declaration(
                    "Fixture.Pebble",
                    "def Pebble (n : Nat) : Type := PMF (Fin n)",
                ),
                local_declaration(
                    "Fixture.Quartz",
                    "abbrev Quartz (n : Nat) : Type := Pebble n",
                ),
                local_declaration(
                    "Fixture.Cobalt",
                    "def Cobalt : Type := WithTop Real",
                ),
            ]
        )
        result_model = AUDIT.StructureInfo(
            name="Fixture.Model",
            source_file="papers/Fixture/Model.lean",
            line=1,
            parameters=["α"],
            parameter_types={"α": "Type"},
            fields=[
                AUDIT.FieldInfo(
                    structure="Fixture.Model",
                    field="law",
                    type="PMF (Fin 3)",
                    path="Fixture.Model.law",
                    line=3,
                    source_file="papers/Fixture/Model.lean",
                    nested_structures=[],
                    risk_terms=[],
                )
            ],
        )
        items = AUDIT.semantic_model_audit_items(
            row_names=["neutral_row"],
            declarations={
                "neutral_row": (
                    "theorem neutral_row (n : Nat) (law : Quartz n) : "
                    "∃ m : Model, ∃ r : Cobalt, True := by sorry"
                )
            },
            row_inputs={
                "neutral_row": [
                    {"names": "n", "type": "Nat"},
                    {"names": "law", "type": "Quartz n"},
                ]
            },
            row_records={"neutral_row": []},
            fields_by_root={},
            proposition_aliases={},
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
            type_aliases=aliases,
            structures={"Fixture.Model": result_model},
        )

        item = items[0]
        binder = item["expanded_lean_surface"]["binder_domains"][1][
            "expanded_type"
        ]
        terminal = item["expanded_lean_surface"]["terminal_result"][
            "expanded_type"
        ]
        self.assertIn("PMF (Fin n)", binder)
        self.assertIn("WithTop Real", terminal)
        self.assertEqual(
            item["expanded_lean_surface"]["record_roots"], ["Fixture.Model"]
        )
        self.assertEqual(
            item["expanded_lean_surface"]["record_parameter_types"][0][
                "expanded_type"
            ],
            "Type",
        )
        self.assertTrue(item["semantic_shape_flags"]["generic_or_restricted_carrier"])
        self.assertTrue(item["semantic_shape_flags"]["probabilistic_model"])
        self.assertTrue(
            item["semantic_shape_flags"]["finite_or_ordered_probability_domain"]
        )
        self.assertTrue(item["semantic_shape_flags"]["extended_rate_codomain"])
        self.assertTrue(
            AUDIT.semantic_model_feature_flags(
                [],
                {"alpha_normalized_type": "True"},
                [{"alpha_normalized_type": "PMF Rating"}],
                [{"alpha_normalized_type": "Type"}],
            )["generic_or_restricted_carrier"]
        )
        for law_type in ("PMF Rating", "Measure Rating"):
            law_flags = AUDIT.semantic_model_feature_flags(
                [],
                {"alpha_normalized_type": "True"},
                [{"alpha_normalized_type": law_type}],
                [],
            )
            self.assertTrue(law_flags["probabilistic_model"])
            self.assertFalse(law_flags["conditioning_and_calibration_semantics"])
            self.assertFalse(law_flags["expectation_definedness"])
            self.assertFalse(
                law_flags["null_cell_totalization_and_partition_scope"]
            )

        indexed_flags = AUDIT.semantic_model_feature_flags(
            [{"alpha_normalized_type": "Fin (n + 2)"}],
            {"alpha_normalized_type": "True"},
            [],
            [],
        )
        self.assertTrue(indexed_flags["nontrivial_finite_index_expression"])
        self.assertTrue(indexed_flags["finite_carrier"])
        subtype_flags = AUDIT.semantic_model_feature_flags(
            [{"alpha_normalized_type": "Subtype (fun x : Real => 0 < x)"}],
            {"alpha_normalized_type": "True"},
            [],
            [],
        )
        self.assertTrue(subtype_flags["generic_or_restricted_carrier"])
        self.assertFalse(subtype_flags["finite_carrier"])
        self.assertIn(
            "finite carrier with nontrivial index arithmetic",
            AUDIT.semantic_model_dimension_shape_basis(
                "carrier_and_domain", indexed_flags
            ),
        )

        indexed_item = AUDIT.semantic_model_audit_items(
            row_names=["indexed_row"],
            declarations={
                "indexed_row": (
                    "theorem indexed_row (n : Nat) (x : Fin (n + 2)) : True := by trivial"
                )
            },
            row_inputs={
                "indexed_row": [
                    {"names": "n", "type": "Nat"},
                    {"names": "x", "type": "Fin (n + 2)"},
                ]
            },
            row_records={},
            fields_by_root={},
            proposition_aliases={},
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
        )[0]
        indexed_carrier_dimension = next(
            dimension
            for dimension in indexed_item["dimensions"]
            if dimension["id"] == "carrier_and_domain"
        )
        self.assertTrue(
            indexed_carrier_dimension[
                "requires_parameter_translation_when_detected"
            ]
        )
        self.assertTrue(indexed_carrier_dimension["requires_checked_bridge_when_detected"])
        self.assertTrue(
            indexed_carrier_dimension[
                "requires_cardinality_boundary_analysis_when_detected"
            ]
        )

