    def test_semantic_model_expands_imported_transparent_terminal_term_dependencies(self) -> None:
        def item_for(primary: str, secondary: str) -> dict[str, object]:
            return AUDIT.semantic_model_audit_items(
                row_names=["row"],
                declarations={
                    "row": (
                        f"theorem row : {primary} = {primary} := by rfl"
                    )
                },
                row_inputs={"row": []},
                row_records={},
                fields_by_root={},
                proposition_aliases={},
                dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
                row_qualified_names={"row": "Fixture.row"},
                semantic_declarations=[
                    local_declaration(
                        f"Fixture.{primary}",
                        f"noncomputable def {primary} : ℝ := Imported.{secondary}",
                    ),
                    local_declaration(
                        f"Fixture.Imported.{secondary}",
                        (
                            f"noncomputable def {secondary} : ℝ := "
                            "∫ x : Fin 3, (x : ℝ) "
                            "∂(PMF.uniformOfFintype (Fin 3)).toMeasure"
                        ),
                        source_file="papers/Fixture/ImportedModel.lean",
                    ),
                ],
            )[0]

        item = item_for("Pebble", "Quartz")
        renamed = item_for("Slate", "Flint")
        surface = item["expanded_lean_surface"]
        assert isinstance(surface, dict)
        dependencies = surface["terminal_term_dependency_surface"]
        assert isinstance(dependencies, dict)
        self.assertEqual(dependencies["schema"], 1)
        definitions = dependencies["transparent_definitions"]
        assert isinstance(definitions, list)
        self.assertEqual(
            [definition["declaration"] for definition in definitions],
            ["Fixture.Imported.Quartz", "Fixture.Pebble"],
        )
        quartz = next(
            definition
            for definition in definitions
            if definition["declaration"] == "Fixture.Imported.Quartz"
        )
        self.assertTrue(quartz["semantic_construct_flags"]["probability_law_construct"])
        self.assertTrue(
            quartz["semantic_construct_flags"]["integration_or_expectation_construct"]
        )
        self.assertTrue(quartz["semantic_relevant"])
        self.assertEqual(quartz["source_file"], "papers/Fixture/ImportedModel.lean")
        self.assertRegex(str(quartz["declaration_sha256"]), r"^[0-9a-f]{64}$")
        self.assertRegex(str(quartz["body_sha256"]), r"^[0-9a-f]{64}$")
        self.assertEqual(
            quartz["dependency_chain"],
            ["Fixture.Pebble", "Fixture.Imported.Quartz"],
        )

        flags = item["semantic_shape_flags"]
        renamed_flags = renamed["semantic_shape_flags"]
        self.assertTrue(flags["terminal_term_model_surface"])
        self.assertTrue(flags["terminal_term_expectation_surface"])
        self.assertTrue(flags["probabilistic_model"])
        self.assertTrue(flags["finite_carrier"])
        self.assertTrue(flags["finite_or_ordered_probability_domain"])
        self.assertEqual(flags, renamed_flags)
        detected = {
            dimension["id"]: dimension["detected_from_expanded_surface"]
            for dimension in item["dimensions"]
        }
        self.assertTrue(detected["carrier_and_domain"])
        self.assertTrue(detected["probability_support_endpoints"])
        self.assertTrue(detected["joint_law_and_state_evolution"])
        self.assertFalse(detected["conditioning_and_calibration_semantics"])
        self.assertTrue(detected["expectation_definedness"])
        self.assertFalse(
            detected["null_cell_totalization_and_partition_scope"]
        )
        expectation = next(
            dimension
            for dimension in item["dimensions"]
            if dimension["id"] == "expectation_definedness"
        )
        self.assertEqual(
            expectation["expanded_shape_basis"],
            [
                "transparent terminal definition closure with integration or expectation construct"
            ],
        )
        joint_law = next(
            dimension
            for dimension in item["dimensions"]
            if dimension["id"] == "joint_law_and_state_evolution"
        )
        self.assertTrue(joint_law["requires_checked_bridge_when_detected"])
        self.assertTrue(joint_law["requires_transformed_law_analysis_when_detected"])
        self.assertTrue(
            joint_law[
                "requires_distribution_parameterization_analysis_when_detected"
            ]
        )

    def test_measure_kernel_carrier_transport_requires_coherence_analysis(self) -> None:
        self.assertTrue(
            AUDIT.semantic_model_term_construct_flags(
                "MeasureTheory.Measure.map f mu"
            )["measure_kernel_carrier_transport_construct"]
        )
        self.assertFalse(
            AUDIT.semantic_model_term_construct_flags(
                "Fixture.Measure.map f mu"
            )["measure_kernel_carrier_transport_construct"]
        )
        self.assertTrue(
            AUDIT.semantic_model_term_construct_flags(
                "μ.map f", known_measure_kernel_carrier_names={"μ"}
            )["measure_kernel_carrier_transport_construct"]
        )
        self.assertTrue(
            AUDIT.semantic_model_term_construct_flags(
                "κ.map f", known_measure_kernel_carrier_names={"κ"}
            )["measure_kernel_carrier_transport_construct"]
        )
        self.assertFalse(
            AUDIT.semantic_model_term_construct_flags(
                "box.map f", known_measure_kernel_carrier_names={"μ"}
            )["measure_kernel_carrier_transport_construct"]
        )
        self.assertFalse(
            AUDIT.semantic_model_term_construct_flags(
                "Fixture.Measure.map f μ", known_measure_kernel_carrier_names={"μ"}
            )["measure_kernel_carrier_transport_construct"]
        )
        self.assertFalse(
            AUDIT.semantic_model_standard_measure_kernel_carrier_type(
                "List (Measure (Fin 2))"
            )
        )
        self.assertFalse(
            AUDIT.semantic_model_standard_measure_kernel_carrier_type(
                "Fixture.Measure (Fin 2)"
            )
        )

        def item_for(
            primary: str,
            secondary: str,
            transport: str,
            *,
            carrier_name: str = "mu",
        ) -> dict[str, object]:
            return AUDIT.semantic_model_audit_items(
                row_names=["row"],
                declarations={
                    "row": (
                        f"theorem row ({carrier_name} : Measure (Fin 2)) : "
                        f"{primary} {carrier_name} = {primary} {carrier_name} := by rfl"
                    )
                },
                row_inputs={
                    "row": [
                        {"names": carrier_name, "type": "Measure (Fin 2)"}
                    ]
                },
                row_records={},
                fields_by_root={},
                proposition_aliases={},
                dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
                row_qualified_names={"row": "Fixture.row"},
                semantic_declarations=[
                    local_declaration(
                        f"Fixture.{primary}",
                        (
                            f"noncomputable def {primary} "
                            f"({carrier_name} : Measure (Fin 2)) : Measure (Fin 2) := "
                            f"Imported.{secondary} {carrier_name}"
                        ),
                    ),
                    local_declaration(
                        f"Fixture.Imported.{secondary}",
                        (
                            f"noncomputable def {secondary} "
                            f"({carrier_name} : Measure (Fin 2)) : Measure (Fin 2) := {transport}"
                        ),
                        source_file="papers/Fixture/ImportedModel.lean",
                    ),
                ],
            )[0]

        item = item_for(
            "Pebble", "Quartz", "MeasureTheory.Measure.map (fun x => x) mu"
        )
        renamed = item_for(
            "Slate", "Flint", "MeasureTheory.Measure.map (fun x => x) mu"
        )
        flags = item["semantic_shape_flags"]
        self.assertTrue(flags["probabilistic_model"])
        self.assertTrue(flags["measure_kernel_carrier_transport_construct"])
        self.assertEqual(flags, renamed["semantic_shape_flags"])

        joint_law = next(
            dimension
            for dimension in item["dimensions"]
            if dimension["id"] == "joint_law_and_state_evolution"
        )
        self.assertTrue(joint_law["detected_from_expanded_surface"])
        self.assertTrue(
            joint_law[
                "requires_source_carrier_coherence_analysis_when_detected"
            ]
        )
        self.assertIn(
            "source-carrier coherence analysis",
            str(item["required_check"]),
        )
        prompt = PROMPT.judge_prompt("Fixture", [item])
        self.assertIn("source_carrier_coherence_analysis", prompt)
        self.assertIn("all-rate indexed family", prompt)
        self.assertTrue(
            any(
                "standard Measure/Kernel carrier transport" in basis
                for basis in joint_law["expanded_shape_basis"]
            ),
            joint_law["expanded_shape_basis"],
        )

        dot_item = item_for(
            "Granite", "Basalt", "μ.map (fun x => x)", carrier_name="μ"
        )
        renamed_dot_item = item_for(
            "Marble", "Onyx", "ν.map (fun x => x)", carrier_name="ν"
        )
        self.assertTrue(
            dot_item["semantic_shape_flags"][
                "measure_kernel_carrier_transport_construct"
            ]
        )
        self.assertEqual(
            dot_item["semantic_shape_flags"],
            renamed_dot_item["semantic_shape_flags"],
        )

        root_dot = AUDIT.semantic_model_audit_items(
            row_names=["row"],
            declarations={
                "row": (
                    "theorem row (μ : Measure (Fin 2)) : "
                    "μ.map (fun x => x) = μ.map (fun x => x) := by rfl"
                )
            },
            row_inputs={"row": [{"names": "μ", "type": "Measure (Fin 2)"}]},
            row_records={},
            fields_by_root={},
            proposition_aliases={},
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
        )[0]
        self.assertTrue(
            root_dot["semantic_shape_flags"][
                "measure_kernel_carrier_transport_construct"
            ]
        )

        local_helper = AUDIT.semantic_model_audit_items(
            row_names=["row"],
            declarations={
                "row": (
                    "theorem row (μ : Measure (Fin 2)) "
                    "(box : List (Measure (Fin 2))) : "
                    "Pebble μ box = Pebble μ box := by rfl"
                )
            },
            row_inputs={
                "row": [
                    {"names": "μ", "type": "Measure (Fin 2)"},
                    {"names": "box", "type": "List (Measure (Fin 2))"},
                ]
            },
            row_records={},
            fields_by_root={},
            proposition_aliases={},
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
            row_qualified_names={"row": "Fixture.row"},
            semantic_declarations=[
                local_declaration(
                    "Fixture.Pebble",
                    (
                        "noncomputable def Pebble (μ : Measure (Fin 2)) "
                        "(box : List (Measure (Fin 2))) : Measure (Fin 2) := box.map"
                    ),
                ),
            ],
        )[0]
        self.assertFalse(
            local_helper["semantic_shape_flags"][
                "measure_kernel_carrier_transport_construct"
            ]
        )

        plain = AUDIT.semantic_model_audit_items(
            row_names=["row"],
            declarations={
                "row": "theorem row (mu : Measure (Fin 2)) : mu = mu := by rfl"
            },
            row_inputs={"row": [{"names": "mu", "type": "Measure (Fin 2)"}]},
            row_records={},
            fields_by_root={},
            proposition_aliases={},
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
        )[0]
        plain_flags = plain["semantic_shape_flags"]
        self.assertTrue(plain_flags["probabilistic_model"])
        self.assertFalse(plain_flags["measure_kernel_carrier_transport_construct"])
        plain_joint_law = next(
            dimension
            for dimension in plain["dimensions"]
            if dimension["id"] == "joint_law_and_state_evolution"
        )
        self.assertFalse(
            plain_joint_law[
                "requires_source_carrier_coherence_analysis_when_detected"
            ]
        )

    def test_semantic_model_terminal_conditioning_construct_triggers_only_partition_dimensions(
        self,
    ) -> None:
        item = AUDIT.semantic_model_audit_items(
            row_names=["row"],
            declarations={"row": "theorem row : Pebble = Pebble := by rfl"},
            row_inputs={"row": []},
            row_records={},
            fields_by_root={},
            proposition_aliases={},
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
            row_qualified_names={"row": "Fixture.row"},
            semantic_declarations=[
                local_declaration(
                    "Fixture.Pebble", "noncomputable def Pebble : ℝ := Quartz"
                ),
                local_declaration(
                    "Fixture.Quartz",
                    (
                        "noncomputable def Quartz : ℝ := "
                        "MeasureTheory.condExp μ f x"
                    ),
                ),
            ],
        )[0]

        flags = item["semantic_shape_flags"]
        self.assertTrue(flags["terminal_term_conditioning_surface"])
        self.assertFalse(flags["terminal_term_expectation_surface"])
        detected = {
            dimension["id"]: dimension["detected_from_expanded_surface"]
            for dimension in item["dimensions"]
        }
        self.assertTrue(detected["conditioning_and_calibration_semantics"])
        self.assertFalse(detected["expectation_definedness"])
        self.assertTrue(
            detected["null_cell_totalization_and_partition_scope"]
        )
        conditioning = next(
            dimension
            for dimension in item["dimensions"]
            if dimension["id"] == "conditioning_and_calibration_semantics"
        )
        null_cell = next(
            dimension
            for dimension in item["dimensions"]
            if dimension["id"] == "null_cell_totalization_and_partition_scope"
        )
        expected_basis = [
            "transparent terminal definition closure with conditioning or partition construct"
        ]
        self.assertEqual(conditioning["expanded_shape_basis"], expected_basis)
        self.assertEqual(null_cell["expanded_shape_basis"], expected_basis)

    def test_semantic_model_terminal_opaque_or_bounded_term_path_requires_bridge(self) -> None:
        opaque_item = AUDIT.semantic_model_audit_items(
            row_names=["row"],
            declarations={"row": "theorem row : Crate = 0 := by rfl"},
            row_inputs={"row": []},
            row_records={},
            fields_by_root={},
            proposition_aliases={},
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
            row_qualified_names={"row": "Fixture.row"},
            semantic_declarations=[
                local_declaration("Fixture.Crate", "opaque Crate : ℝ")
            ],
        )[0]
        opaque_surface = opaque_item["expanded_lean_surface"]
        assert isinstance(opaque_surface, dict)
        opaque_dependencies = opaque_surface["terminal_term_dependency_surface"]
        assert isinstance(opaque_dependencies, dict)
        self.assertEqual(
            opaque_dependencies["unexpanded_local_term_heads"][0]["declaration"],
            "Fixture.Crate",
        )
        self.assertTrue(
            opaque_item["semantic_shape_flags"]["unexpanded_local_term_surface"]
        )
        opaque_detected = {
            dimension["id"]: dimension["detected_from_expanded_surface"]
            for dimension in opaque_item["dimensions"]
        }
        self.assertTrue(opaque_detected["conditioning_and_calibration_semantics"])
        self.assertTrue(opaque_detected["expectation_definedness"])
        self.assertTrue(
            opaque_detected["null_cell_totalization_and_partition_scope"]
        )
        opaque_joint_law = next(
            dimension
            for dimension in opaque_item["dimensions"]
            if dimension["id"] == "joint_law_and_state_evolution"
        )
        self.assertTrue(opaque_joint_law["detected_from_expanded_surface"])
        self.assertTrue(opaque_joint_law["requires_checked_bridge_when_detected"])

        bounded = AUDIT.semantic_model_terminal_term_dependency_surface(
            "Pebble = 0",
            [
                local_declaration("Fixture.Pebble", "def Pebble : ℝ := Quartz"),
                local_declaration(
                    "Fixture.Quartz",
                    "def Quartz : ℝ := PMF.uniformOfFintype (Fin 3)",
                ),
            ],
            {},
            None,
            context_namespace="Fixture",
            max_depth=1,
            max_nodes=4,
        )
        self.assertFalse(bounded["scan_complete"])
        self.assertEqual(bounded["scan_limits"], {"max_depth": 1, "max_nodes": 4})
        self.assertTrue(
            any(
                item["reason"] == "terminal_term_dependency_max_depth"
                for item in bounded["unexpanded_local_term_heads"]
            )
        )

