    def test_schema_two_requires_all_expanded_probability_dimensions(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            status = Path(tmpdir) / "status.json"
            status.write_text(
                json.dumps(
                    {
                        "review_surface": {
                            "semantic_model_review": {
                                "schema": AUDIT.SEMANTIC_MODEL_REVIEW_LEGACY_SCHEMA,
                                "required_dimensions": list(
                                    AUDIT.SEMANTIC_MODEL_LEGACY_DIMENSION_ORDER
                                ),
                            }
                        }
                    }
                ),
                encoding="utf-8",
            )
            legacy_dimensions, legacy_errors = AUDIT.semantic_model_review_config(
                status
            )

            status.write_text(
                json.dumps(
                    {
                        "review_surface": {
                            "semantic_model_review": {
                                "schema": AUDIT.SEMANTIC_MODEL_REVIEW_SCHEMA,
                                "required_dimensions": list(
                                    AUDIT.SEMANTIC_MODEL_LEGACY_DIMENSION_ORDER
                                ),
                            }
                        }
                    }
                ),
                encoding="utf-8",
            )
            partial_dimensions, partial_errors = AUDIT.semantic_model_review_config(
                status
            )

            status.write_text(
                json.dumps(
                    {
                        "review_surface": {
                            "semantic_model_review": {
                                "schema": AUDIT.SEMANTIC_MODEL_REVIEW_SCHEMA,
                                "required_dimensions": list(
                                    AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER
                                ),
                            }
                        }
                    }
                ),
                encoding="utf-8",
            )
            complete_dimensions, complete_errors = AUDIT.semantic_model_review_config(
                status
            )

        self.assertEqual(partial_dimensions, [])
        self.assertEqual(legacy_errors, [])
        self.assertEqual(
            legacy_dimensions, list(AUDIT.SEMANTIC_MODEL_LEGACY_DIMENSION_ORDER)
        )
        self.assertTrue(
            any("must require every expanded-semantic dimension" in error for error in partial_errors)
        )
        self.assertEqual(complete_errors, [])
        self.assertEqual(
            complete_dimensions, list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER)
        )

    def test_semantic_model_lane_marks_unconfigured_source_route_as_an_error(self) -> None:
        common = {
            "row_names": ["row"],
            "declarations": {
                "row": "theorem row (law : PMF (Fin 2)) : True := by trivial"
            },
            "row_inputs": {"row": [{"names": "law", "type": "PMF (Fin 2)"}]},
            "row_records": {},
            "fields_by_root": {},
            "proposition_aliases": {},
        }
        unconfigured_item = AUDIT.semantic_model_audit_items(
            **common, dimensions=[]
        )[0]
        unconfigured_item["source_statement_association"] = {
            "role": "direct_source_route",
            "source_item_identities": [{"source_key": "source_result"}],
        }
        errors = AUDIT.semantic_model_dimension_configuration_errors(
            [unconfigured_item], []
        )
        self.assertEqual(len(errors), 1)
        self.assertIn("no semantic dimensions were configured", errors[0])

        nonsemantic_item = dict(unconfigured_item)
        nonsemantic_item.pop("source_statement_association")
        self.assertEqual(
            AUDIT.semantic_model_dimension_configuration_errors(
                [nonsemantic_item], []
            ),
            [],
        )

        item = AUDIT.semantic_model_audit_items(
            **common,
            dimensions=list(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER),
        )[0]
        dimensions = {dimension["id"]: dimension for dimension in item["dimensions"]}
        self.assertEqual(
            set(dimensions), set(AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER)
        )
        self.assertTrue(
            dimensions["joint_law_and_state_evolution"][
                "detected_from_expanded_surface"
            ]
        )

