    def test_repository_exposed_prop_alias_compatibility_fails_closed(self) -> None:
        mutations = {
            "imported_wrapper": lambda surface: surface.update(
                {"terminal_result_origin": "declared_terminal_result"}
            ),
            "opaque_dependency": lambda surface: surface[
                "terminal_term_dependency_surface"
            ]["unexpanded_local_term_heads"].append(
                {"declaration": "Fixture.Hidden", "reason": "opaque"}
            ),
            "unmatched_terminal": lambda surface: surface["terminal_result"].update(
                {
                    "expanded_type": "Fixture.OtherCondition",
                    "alpha_normalized_type": "Fixture.OtherCondition",
                }
            ),
            "empty_wrapper": lambda surface: surface.update({"binder_domains": []}),
            "hidden_type": lambda surface: surface[
                "unexpanded_local_type_heads"
            ].append({"declaration": "Fixture.HiddenType"}),
            "bounded_scan": lambda surface: surface[
                "terminal_term_dependency_surface"
            ].update(
                {
                    "scan_complete": False,
                    "incomplete_reasons": ["max_depth"],
                }
            ),
        }
        for label, mutate in mutations.items():
            with self.subTest(label=label):
                surface = deepcopy(
                    self._fully_exposed_incomplete_prop_alias_surface()
                )
                mutate(surface)
                self.assertFalse(
                    REPO.incomplete_alias_exposes_complete_terminal_proposition(
                        surface, surface["review_alias_expansion"]
                    )
                )

