    def test_invalid_direct_route_anchor_does_not_suppress_other_routes(self) -> None:
        """Each selected source item is independently byte-verified."""

        valid_qualified = "Fixture.Paper.validEndpoint"
        invalid_qualified = "Fixture.Paper.invalidEndpoint"
        valid_declaration = "theorem validEndpoint (x : Nat) : x = x := by rfl"
        invalid_declaration = "theorem invalidEndpoint (x : Nat) : x = x := by rfl"
        source_lines = [
            "Theorem 1. The valid endpoint holds.",
            "Theorem 2. The malformed endpoint holds.",
        ]
        source_text = "\n".join(source_lines) + "\n"
        source_digest = hashlib.sha256(source_text.encode("utf-8")).hexdigest()

        def anchor(line: int, *, corrupt_quote: bool = False) -> dict[str, object]:
            quote = (
                "Theorem 2. A different endpoint holds."
                if corrupt_quote
                else source_lines[line - 1]
            )
            return {
                "path": "source.txt",
                "line_start": line,
                "line_end": line,
                "quoted_text": quote,
                "quoted_text_sha256": hashlib.sha256(
                    quote.encode("utf-8")
                ).hexdigest(),
            }

        source_map: dict[str, object] = {
            "source_coverage_mode": "named_theoretical_statements",
            "source_artifact_path": "source.txt",
            "source_artifact_sha256": source_digest,
            "items": {
                "valid_endpoint": {
                    "source_kind": "theorem",
                    "source_location": "source.txt:1-1",
                    "source_anchor_evidence": [anchor(1)],
                    "lean_declarations": [valid_qualified],
                },
                "invalid_endpoint": {
                    "source_kind": "theorem",
                    "source_location": "source.txt:2-2",
                    "source_anchor_evidence": [anchor(2, corrupt_quote=True)],
                    "lean_declarations": [invalid_qualified],
                },
            },
        }
        items: list[dict[str, object]] = [
            {
                "row": "valid_row",
                "judgment_key": "semantic-model::valid",
                "qualified_declaration": valid_qualified,
                "lean_source_declaration": valid_declaration,
                "required_check": "Review the valid endpoint.",
            },
            {
                "row": "invalid_row",
                "judgment_key": "semantic-model::invalid",
                "qualified_declaration": invalid_qualified,
                "lean_source_declaration": invalid_declaration,
                "required_check": "Review the malformed endpoint.",
            },
        ]

        with tempfile.TemporaryDirectory() as temporary:
            paper = Path(temporary) / "papers" / "Fixture"
            audit = paper / "audit"
            audit.mkdir(parents=True)
            (paper / "source.txt").write_text(source_text, encoding="utf-8")
            (paper / "status.json").write_text(
                json.dumps({"status": "formalized"}), encoding="utf-8"
            )
            (audit / "paper_statement_map.json").write_text(
                json.dumps(source_map), encoding="utf-8"
            )
            attached, errors, counts = (
                AUDIT.attach_explicit_direct_source_route_associations(
                    items,
                    paper_dir=paper,
                    paper_statement_map=source_map,
                    declarations={
                        "valid_row": valid_declaration,
                        "invalid_row": invalid_declaration,
                    },
                    row_qualified_names={
                        "valid_row": valid_qualified,
                        "invalid_row": invalid_qualified,
                    },
                    elaborated_signature_sha256_by_qualified={
                        valid_qualified: hashlib.sha256(
                            b"elaborated valid signature"
                        ).hexdigest(),
                        invalid_qualified: hashlib.sha256(
                            b"elaborated invalid signature"
                        ).hexdigest(),
                    },
                )
            )

        self.assertEqual(counts["explicit_direct_route_declaration_count"], 2)
        self.assertEqual(counts["explicit_direct_route_source_item_count"], 2)
        self.assertEqual(counts["explicit_direct_route_association_count"], 1)
        self.assertIn("source_statement_association", attached[0])
        self.assertNotIn("source_statement_association", attached[1])
        self.assertTrue(
            any(
                "`invalid_endpoint` provenance is not byte-verified" in error
                for error in errors
            ),
            errors,
        )

