    def test_source_proof_ledger_enters_semantic_judge_context_and_digest(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "papers" / "Fixture"
            audit = paper / "audit"
            audit.mkdir(parents=True)
            (audit / "source_proof_fidelity.json").write_text(
                json.dumps(
                    {
                        "schema": 1,
                        "paper": "Fixture",
                        "source_artifact_path": "source.tex",
                        "source_artifact_sha256": "a" * 64,
                        "review_status": "defects_recorded",
                        "reviewed_proof_scopes": [
                            {
                                "source_locator": "source.tex:10-25",
                                "semantic_scope": "tail comparison",
                                "outcome": "defect_recorded",
                            }
                        ],
                        "model_conventions": [
                            {
                                "id": "FIXTURE-EVENT-CALIBRATION",
                                "source_locator": "source.tex:4-12",
                                "formal_meaning": "Calibration is an equality over every measurable event rather than a selected point-fiber conditional value.",
                                "checked_scope": "The raw joint law covers atomic and atomless event probabilities.",
                            }
                        ],
                        "checked_proof_steps": [
                            {
                                "id": "FIXTURE-FINITE-MIXTURE",
                                "source_locator": "source.tex:26-33",
                                "source_step": "Take the finite weighted mixture used in the proof.",
                                "checked_conclusion": "The embedded event probabilities scale by the stated component weights.",
                                "scope": "Finite measurable mixture only; no arbitrary disintegration claim.",
                            }
                        ],
                        "defects": [
                            {
                                "source_locator": "source.tex:18-21",
                                "source_claim": "tail inequality direction",
                                "repair_obligation": "prove the monotone comparison",
                                "resolution": "open_proof_obligation",
                            }
                        ],
                    }
                ),
                encoding="utf-8",
            )
            context = AUDIT.source_proof_fidelity_context(paper)

        assert context is not None
        self.assertEqual(context["model_conventions"][0]["id"], "FIXTURE-EVENT-CALIBRATION")
        self.assertEqual(context["checked_proof_steps"][0]["id"], "FIXTURE-FINITE-MIXTURE")
        prompt = PROMPT.judge_prompt("Fixture", [], context)
        self.assertIn("source-proof fidelity ledger", prompt)
        self.assertIn("source.tex:18-21", prompt)
        self.assertIn("FIXTURE-EVENT-CALIBRATION", prompt)
        self.assertIn("FIXTURE-FINITE-MIXTURE", prompt)
        self.assertIn("model_conventions and checked_proof_steps", prompt)
        self.assertIn("not by Lean declaration name", prompt)
        self.assertIn("literal legal action space", prompt)
        self.assertIn("source_statement_association", prompt)
        self.assertIn("ordered tuple, a multiset, or a bounded stock", prompt)
        self.assertIn("noncomputable existence selector", prompt)
        self.assertIn("self-characterization", prompt)
        self.assertIn("distinct semantic worlds", prompt)
        self.assertIn("fixed profile is not an all-profile theorem", prompt)
        self.assertIn("polynomial-time bound", prompt)
        self.assertIn("output's arity and projection policy", prompt)
        self.assertIn("duplicate-invalid ballots", prompt)
        self.assertIn("one coherent admissible witness", prompt)
        self.assertIn("nonempty realized fibers", prompt)
        self.assertIn("source and Lean input domains", prompt)
        self.assertIn("state transitions, termination conditions", prompt)
        self.assertIn("numeric representations, and cost scopes", prompt)
        self.assertIn("checked global bridge", prompt)
        self.assertIn("hidden_subtype_predicate", prompt)
        self.assertIn("only the subtype's value projection is witness data", prompt)
        changed = {**context, "review_status": "reviewed_no_defects"}
        self.assertNotEqual(
            AUDIT.stable_digest({"source_proof_fidelity": context}),
            AUDIT.stable_digest({"source_proof_fidelity": changed}),
        )

