    def test_source_record_scope_context_pins_corrected_target_identity(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "papers" / "Fixture"
            paper.mkdir(parents=True)
            scope = {
                "kind": "author_approved_corrected_model",
                "scope_id": "Fixture-corrected-model",
                "approval": {
                    "artifact_path": "docs/GOVERNING_CORRECTED_MODEL.md",
                    "artifact_sha256": "a" * 64,
                },
                "base_archive": {
                    "path": "source.tar.gz",
                    "sha256": "b" * 64,
                },
                "model_spec_declaration": "Fixture.ClarifiedSourceModel",
                "target_result_declarations": [
                    "Fixture.PaperInterface.corrected_result"
                ],
                "correction_ids": ["FIXTURE-CORRECTION"],
                "archival_equivalence_claimed": False,
            }
            governing_corrections = [
                {
                    "id": "FIXTURE-CORRECTION",
                    "clause": "Use the approved finite corrected model.",
                    "source_anchor": "source.tex:1-5",
                    "relation": "author_approved_correction",
                    "model_evidence": "Fixture.ClarifiedSourceModel",
                    "does_not_claim_archive_derivation": True,
                }
            ]
            (paper / "status.json").write_text(
                json.dumps(
                    {
                        "formalization_scope": scope,
                        "governing_corrections": governing_corrections,
                    }
                ),
                encoding="utf-8",
            )
            original = AUDIT.formalization_scope_context(paper)

            assert original is not None
            self.assertEqual(
                original["target_result_declarations"],
                ["Fixture.PaperInterface.corrected_result"],
            )
            self.assertEqual(original["correction_ids"], ["FIXTURE-CORRECTION"])
            self.assertFalse(original["archival_equivalence_claimed"])

            scope["correction_ids"] = ["FIXTURE-CORRECTION", "FIXTURE-RATE"]
            governing_corrections.append(
                {
                    "id": "FIXTURE-RATE",
                    "clause": "Use a positive finite rate.",
                    "source_anchor": "source.tex:6-8",
                    "relation": "author_approved_additional_assumption",
                    "model_evidence": "Fixture.ClarifiedSourceModel",
                    "does_not_claim_archive_derivation": True,
                }
            )
            (paper / "status.json").write_text(
                json.dumps(
                    {
                        "formalization_scope": scope,
                        "governing_corrections": governing_corrections,
                    }
                ),
                encoding="utf-8",
            )
            changed = AUDIT.formalization_scope_context(paper)

            governing_corrections[0]["clause"] = (
                "Use the approved finite corrected model with a positive rate."
            )
            (paper / "status.json").write_text(
                json.dumps(
                    {
                        "formalization_scope": scope,
                        "governing_corrections": governing_corrections,
                    }
                ),
                encoding="utf-8",
            )
            content_changed = AUDIT.formalization_scope_context(paper)

        assert changed is not None
        assert content_changed is not None
        self.assertNotEqual(original["scope_sha256"], changed["scope_sha256"])
        self.assertNotEqual(
            changed["governing_corrections_sha256"],
            content_changed["governing_corrections_sha256"],
        )
        self.assertNotEqual(changed["scope_sha256"], content_changed["scope_sha256"])
        self.assertEqual(
            changed["correction_ids"], ["FIXTURE-CORRECTION", "FIXTURE-RATE"]
        )

