class SemanticContextRequirementTests(unittest.TestCase):
    def _context_fixture(
        self,
        paper: Path,
        *,
        requirement_extra: dict[str, object] | None = None,
        anchor_override: list[dict[str, object]] | None = None,
    ) -> tuple[Path, dict[str, object]]:
        source = (
            "The true ranking orders candidates by decreasing intrinsic value.\n"
            "The scale parameter is strictly positive.\n"
        )
        (paper / "source.txt").write_text(source, encoding="utf-8")
        quote = "The true ranking orders candidates by decreasing intrinsic value."
        requirement: dict[str, object] = {
            "kind": "true_order_convention",
            "source_location": "source.txt:1",
            "explanation": (
                "The source fixes the orientation used when comparing the true "
                "ranking with a formal rank order."
            ),
            "source_anchor_evidence": [
                {
                    "path": "source.txt",
                    "line_start": 1,
                    "line_end": 1,
                    "quoted_text": quote,
                    "quoted_text_sha256": hashlib.sha256(
                        quote.encode("utf-8")
                    ).hexdigest(),
                }
            ],
        }
        if requirement_extra:
            requirement.update(requirement_extra)
        if anchor_override is not None:
            requirement["source_anchor_evidence"] = anchor_override
        payload: dict[str, object] = {
            "source_artifact_path": "source.txt",
            "source_artifact_sha256": hashlib.sha256(
                source.encode("utf-8")
            ).hexdigest(),
            "source_coverage_mode": "named_theoretical_statements",
            # Deliberately do not opt into global anchors: a context anchor
            # must still be required by its dedicated source-only lane.
            "source_anchor_evidence_required": False,
            "items": {
                "source_statement_navigation_only": {
                    "lean_declarations": ["Fixture.renamed_endpoint"],
                    "semantic_context_requirements": [requirement],
                }
            },
        }
        audit = paper / "audit"
        audit.mkdir(parents=True)
        map_path = audit / "paper_statement_map.json"
        map_path.write_text(json.dumps(payload), encoding="utf-8")
        (paper / "status.json").write_text(
            json.dumps({"status": "partially formalized"}), encoding="utf-8"
        )
        return map_path, payload

    def test_byte_pinned_context_enters_prompt_without_lean_route_credit(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "Fixture"
            paper.mkdir()
            map_path, payload = self._context_fixture(paper)

            findings = EVIDENCE.semantic_context_requirement_findings(
                paper,
                "partially formalized",
                map_path,
                payload,
            )
            manifest_findings = EVIDENCE.check_source_manifest(
                paper, "partially formalized"
            )
            contexts, errors = AUDIT.source_map_semantic_context_requirements(paper)

        self.assertEqual(findings, [])
        self.assertEqual(manifest_findings, [])
        self.assertEqual(errors, [])
        self.assertEqual(len(contexts), 1)
        context = contexts[0]
        self.assertEqual(context["source_item_key"], "source_statement_navigation_only")
        self.assertEqual(context["kind"], "true_order_convention")
        self.assertEqual(context["source_location"], "source.txt:1")
        self.assertIn("orientation", str(context["explanation"]))
        self.assertNotIn("lean_declarations", context)
        prompt = PROMPT.judge_prompt(
            "Fixture", [], semantic_context_requirements=contexts
        )
        self.assertIn("semantic-context requirements", prompt)
        self.assertIn("cannot discharge that obligation", prompt)
        self.assertIn("source.txt:1", prompt)
        self.assertNotIn("Fixture.renamed_endpoint", prompt)

        def source_pinned_item(source_item: dict[str, object]) -> dict[str, object]:
            return {
                "row": "source_row",
                "judgment_key": "row.h : P",
                "source_contract_association": {
                    "source_item_identities": [
                        {
                            "source_semantic_sha256": (
                                AUDIT.source_record_source_item_semantic_sha256(
                                    source_item, ""
                                )
                            )
                        }
                    ],
                    "reviewed_declaration_identity": {
                        "qualified_declaration": "Fixture.source_row"
                    },
                },
            }

        item_digest_kwargs = {
            "row_qualified_names": {"source_row": "Fixture.source_row"},
            "elaborated_signature_sha256_by_qualified": {
            "Fixture.source_row": "b" * 64
            },
        }
        source_item = payload["items"]["source_statement_navigation_only"]
        assert isinstance(source_item, dict)
        changed_payload = json.loads(json.dumps(payload))
        changed_source_item = changed_payload["items"][
            "source_statement_navigation_only"
        ]
        assert isinstance(changed_source_item, dict)
        changed_contexts = changed_source_item["semantic_context_requirements"]
        assert isinstance(changed_contexts, list)
        changed_context = changed_contexts[0]
        assert isinstance(changed_context, dict)
        changed_context["explanation"] = "A changed semantic convention."
        left = [source_pinned_item(source_item)]
        right = [source_pinned_item(changed_source_item)]
        AUDIT.attach_source_record_item_digests(
            left,
            paper_statement_map=payload,
            **item_digest_kwargs,
        )
        AUDIT.attach_source_record_item_digests(
            right,
            paper_statement_map=changed_payload,
            **item_digest_kwargs,
        )
        self.assertNotEqual(
            left[0]["source_record_item_sha256"],
            right[0]["source_record_item_sha256"],
        )

    def test_item_digest_scopes_context_and_ledger_to_source_identity(self) -> None:
        def context(label: str) -> dict[str, object]:
            quote = f"The source fixes {label}."
            return {
                "kind": "source_model_condition",
                "source_location": "source.txt:1",
                "explanation": f"The reviewed source model uses {label}.",
                "source_anchor_evidence": [
                    {
                        "path": "source.txt",
                        "line_start": 1,
                        "line_end": 1,
                        "quoted_text": quote,
                        "quoted_text_sha256": hashlib.sha256(
                            quote.encode("utf-8")
                        ).hexdigest(),
                    }
                ],
            }

        def source_item(label: str, convention_id: str) -> dict[str, object]:
            return {
                "statement": f"Theorem: {label}.",
                "source_kind": "theorem",
                "source_status": "exact",
                "semantic_context_requirements": [context(label)],
                "model_convention_ids": [convention_id],
            }

        def ledger_record(convention_id: str, detail: str) -> dict[str, object]:
            return {
                "id": convention_id,
                "source_locator": "source.txt:1",
                "classification": "documented_additional_assumption",
                "formal_meaning": f"The carrier has {detail}.",
                "why_needed": "The source model needs the stated finite carrier condition.",
                "checked_scope": "The paper-facing endpoint exposes the condition.",
            }

        def source_pinned_item(item: dict[str, object]) -> dict[str, object]:
            return {
                "row": "source_row",
                "judgment_key": "row.h : P",
                "source_contract_association": {
                    "source_item_identities": [
                        {
                            "source_semantic_sha256": (
                                AUDIT.source_record_source_item_semantic_sha256(
                                    item, ""
                                )
                            )
                        }
                    ],
                    "reviewed_declaration_identity": {
                        "qualified_declaration": "Fixture.source_row"
                    },
                },
            }

        source_a = source_item("condition A", "FIXTURE-CONVENTION-A")
        source_b = source_item("condition B", "FIXTURE-CONVENTION-B")
        base_map: dict[str, object] = {
            "items": {
                "navigation_a": source_a,
                "navigation_b": source_b,
            }
        }
        base_ledger: dict[str, object] = {
            "model_conventions": [
                ledger_record("FIXTURE-CONVENTION-A", "condition A"),
                ledger_record("FIXTURE-CONVENTION-B", "condition B"),
            ]
        }
        kwargs = {
            "row_qualified_names": {"source_row": "Fixture.source_row"},
            "elaborated_signature_sha256_by_qualified": {
                "Fixture.source_row": "b" * 64
            },
        }

        base = [source_pinned_item(source_a)]
        AUDIT.attach_source_record_item_digests(
            base,
            paper_statement_map=base_map,
            source_proof_fidelity=base_ledger,
            **kwargs,
        )
        self.assertTrue(base[0]["source_record_item_reuse_eligibility"]["eligible"])
        base_digest = base[0]["source_record_item_sha256"]

        unrelated_map = json.loads(json.dumps(base_map))
        unrelated_b = unrelated_map["items"]["navigation_b"]
        assert isinstance(unrelated_b, dict)
        unrelated_contexts = unrelated_b["semantic_context_requirements"]
        assert isinstance(unrelated_contexts, list)
        unrelated_context = unrelated_contexts[0]
        assert isinstance(unrelated_context, dict)
        unrelated_context["explanation"] = "A changed but unrelated source model condition."
        unrelated_ledger = json.loads(json.dumps(base_ledger))
        unrelated_record = unrelated_ledger["model_conventions"][1]
        assert isinstance(unrelated_record, dict)
        unrelated_record["formal_meaning"] = "The carrier has a changed condition B."
        unchanged = [source_pinned_item(source_a)]
        AUDIT.attach_source_record_item_digests(
            unchanged,
            paper_statement_map=unrelated_map,
            source_proof_fidelity=unrelated_ledger,
            **kwargs,
        )
        self.assertEqual(base_digest, unchanged[0]["source_record_item_sha256"])

        related_map = json.loads(json.dumps(base_map))
        related_a = related_map["items"]["navigation_a"]
        assert isinstance(related_a, dict)
        related_contexts = related_a["semantic_context_requirements"]
        assert isinstance(related_contexts, list)
        related_context = related_contexts[0]
        assert isinstance(related_context, dict)
        related_context["explanation"] = "A changed source model condition A."
        related_context_item = [source_pinned_item(related_a)]
        AUDIT.attach_source_record_item_digests(
            related_context_item,
            paper_statement_map=related_map,
            source_proof_fidelity=base_ledger,
            **kwargs,
        )
        self.assertNotEqual(
            base_digest, related_context_item[0]["source_record_item_sha256"]
        )

        related_ledger = json.loads(json.dumps(base_ledger))
        related_record = related_ledger["model_conventions"][0]
        assert isinstance(related_record, dict)
        related_record["formal_meaning"] = "The carrier has a changed condition A."
        related_ledger_item = [source_pinned_item(source_a)]
        AUDIT.attach_source_record_item_digests(
            related_ledger_item,
            paper_statement_map=base_map,
            source_proof_fidelity=related_ledger,
            **kwargs,
        )
        self.assertNotEqual(
            base_digest, related_ledger_item[0]["source_record_item_sha256"]
        )

    def test_context_rejects_route_fields(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "Fixture"
            paper.mkdir()
            map_path, payload = self._context_fixture(
                paper,
                requirement_extra={"lean_declaration": "Fixture.smuggled"},
            )
            findings = EVIDENCE.semantic_context_requirement_findings(
                paper,
                "partially formalized",
                map_path,
                payload,
            )
            contexts, errors = AUDIT.source_map_semantic_context_requirements(paper)

        messages = [finding.message for finding in findings]
        self.assertTrue(
            any("unsupported field(s): lean_declaration" in message for message in messages)
        )
        # The helper fails before treating the malformed requirement as source
        # context.
        self.assertEqual(contexts, [])
        self.assertTrue(any("unsupported field(s): lean_declaration" in error for error in errors))

    def test_context_requires_its_own_exact_anchor_without_global_opt_in(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "Fixture"
            paper.mkdir()
            invalid_anchor = [
                {
                    "path": "source.txt",
                    "line_start": 1,
                    "line_end": 1,
                    "quoted_text": "A different source quote.",
                    "quoted_text_sha256": hashlib.sha256(
                        b"A different source quote."
                    ).hexdigest(),
                }
            ]
            map_path, payload = self._context_fixture(
                paper,
                anchor_override=invalid_anchor,
            )
            findings = EVIDENCE.semantic_context_requirement_findings(
                paper,
                "partially formalized",
                map_path,
                payload,
            )
            manifest_findings = EVIDENCE.check_source_manifest(
                paper, "partially formalized"
            )
            contexts, errors = AUDIT.source_map_semantic_context_requirements(paper)

        messages = [finding.message for finding in findings]
        manifest_messages = [finding.message for finding in manifest_findings]
        self.assertTrue(
            any("does not equal the exact normalized source line slice" in message for message in messages)
        )
        self.assertTrue(
            any(
                "does not equal the exact normalized source line slice" in message
                for message in manifest_messages
            )
        )
        self.assertEqual(contexts, [])
        self.assertTrue(
            any("does not equal the exact normalized source line slice" in error for error in errors)
        )


class EqualityDefinedPartitionContextTests(unittest.TestCase):
    def partition_context(self) -> dict[str, object]:
        quote = (
            "Users have the same declared class exactly when their complete "
            "feature vectors are equal."
        )
        return {
            "kind": "equality_defined_partition",
            "source_location": "source.txt:1",
            "explanation": (
                "The source defines the declared classes as exactly the equality "
                "classes of complete feature vectors, so both logical directions "
                "must be preserved."
            ),
            "source_anchor_evidence": [
                {
                    "path": "source.txt",
                    "line_start": 1,
                    "line_end": 1,
                    "quoted_text": quote,
                    "quoted_text_sha256": hashlib.sha256(
                        quote.encode("utf-8")
                    ).hexdigest(),
                }
            ],
            "equality_partition_contract": {
                "schema": 1,
                "relation": "feature_equality_iff_class_equality",
                "feature_description": "complete feature vectors",
                "class_description": "declared classes",
                "required_directions": [
                    "feature_equality_implies_class_equality",
                    "class_equality_implies_feature_equality",
                ],
            },
        }

    def map_payload(
        self, context: dict[str, object]
    ) -> dict[str, object]:
        quote = context["source_anchor_evidence"][0]["quoted_text"]
        assert isinstance(quote, str)
        return {
            "source_artifact_path": "source.txt",
            "source_artifact_sha256": hashlib.sha256(
                (quote + "\n").encode("utf-8")
            ).hexdigest(),
            "source_coverage_mode": "named_theoretical_statements",
            "items": {
                # Deliberately no declaration-like source key: route binding
                # below comes from generated source/signature identities.
                "source_semantic_contract": {
                    "claim_bearing": True,
                    "source_kind": "proposition",
                    "source_location": "source.txt:1",
                    "semantic_context_requirements": [context],
                }
            },
        }

    def test_context_is_source_only_and_requires_both_directions(self) -> None:
        context = self.partition_context()
        payload = self.map_payload(context)
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "Fixture"
            paper.mkdir()
            quote = context["source_anchor_evidence"][0]["quoted_text"]
            assert isinstance(quote, str)
            (paper / "source.txt").write_text(quote + "\n", encoding="utf-8")
            audit = paper / "audit"
            audit.mkdir()
            map_path = audit / "paper_statement_map.json"
            map_path.write_text(json.dumps(payload), encoding="utf-8")
            findings = EVIDENCE.semantic_context_requirement_findings(
                paper, "partially formalized", map_path, payload
            )
            contexts, errors = AUDIT.source_map_semantic_context_requirements(paper)

            malformed = json.loads(json.dumps(payload))
            malformed_context = malformed["items"]["source_semantic_contract"][
                "semantic_context_requirements"
            ][0]
            malformed_context["equality_partition_contract"][
                "required_directions"
            ] = ["class_equality_implies_feature_equality"]
            malformed_findings = EVIDENCE.semantic_context_requirement_findings(
                paper, "partially formalized", map_path, malformed
            )

        self.assertEqual(findings, [])
        self.assertEqual(errors, [])
        self.assertEqual(len(contexts), 1)
        projected = contexts[0]
        self.assertEqual(projected["kind"], "equality_defined_partition")
        self.assertIn("equality_partition_contract", projected)
        self.assertNotIn("lean_declaration", json.dumps(projected))
        self.assertTrue(
            any(
                "must contain exactly `feature_equality_implies_class_equality`"
                in finding.message
                for finding in malformed_findings
            ),
            malformed_findings,
        )

    def generated_partition_dimension(self) -> tuple[dict[str, object], dict[str, object]]:
        context = self.partition_context()
        source_map = self.map_payload(context)
        source_item = source_map["items"]["source_semantic_contract"]
        assert isinstance(source_item, dict)
        source_identity = AUDIT.semantic_contract_source_identity(
            "source_semantic_contract", source_item
        )
        declaration = "theorem opaque_endpoint (x : Nat) : x = x := by rfl"
        qualified = "Fixture.Interface.opaque_endpoint"
        declaration_identity = AUDIT.reviewed_declaration_identity(
            qualified, declaration
        )
        assert declaration_identity is not None
        signature_sha = hashlib.sha256(b"opaque elaborated surface").hexdigest()
        signature = {
            "qualified_declaration": qualified,
            "elaborated_signature_sha256": signature_sha,
        }
        association = {
            "schema": 2,
            "association_origin": AUDIT.EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN,
            "role": AUDIT.EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE,
            "source_item_identities": [source_identity],
            "reviewed_declaration_identity": declaration_identity,
            "reviewed_elaborated_signature_identity": signature,
            "semantic_association_sha256": AUDIT.semantic_source_association_digest(
                [source_identity], signature
            ),
        }
        item: dict[str, object] = {
            "row": "unrelated_navigation_label",
            "judgment_key": "semantic-model::opaque",
            "qualified_declaration": qualified,
            "dimensions": [
                {
                    "id": "expanded_binders_and_domain",
                    "detected_from_expanded_surface": False,
                    "required_check": "ordinary semantic review",
                }
            ],
            "source_statement_association": association,
        }
        items, errors, counts = AUDIT.attach_equality_defined_partition_requirements(
            [item],
            paper_statement_map=source_map,
            elaborated_signature_sha256_by_qualified={qualified: signature_sha},
        )
        self.assertEqual(errors, [])
        self.assertEqual(counts["equality_defined_partition_context_count"], 1)
        self.assertEqual(counts["equality_defined_partition_requirement_count"], 1)
        return items[0], source_map

    def test_generated_dimension_is_source_association_bound_not_name_bound(self) -> None:
        item, _source_map = self.generated_partition_dimension()
        dimension = next(
            dimension
            for dimension in item["dimensions"]
            if dimension["id"] == AUDIT.SOURCE_EQUALITY_PARTITION_DIMENSION
        )
        self.assertTrue(dimension["required_from_source_pinned_context"])
        self.assertTrue(dimension["requires_source_equality_partition_analysis"])
        self.assertEqual(
            dimension["source_equality_partition"]["schema"], 1
        )
        self.assertEqual(
            dimension["source_equality_partition_association"]["schema"], 2
        )
        self.assertNotIn("unrelated_navigation_label", json.dumps(dimension))

    def test_source_scoped_dimension_extends_but_does_not_replace_base_checklist(self) -> None:
        item, _source_map = self.generated_partition_dimension()
        partition_dimension = next(
            dimension
            for dimension in item["dimensions"]
            if dimension["id"] == AUDIT.SOURCE_EQUALITY_PARTITION_DIMENSION
        )
        base_dimensions = [
            {"id": dimension}
            for dimension in sorted(EVIDENCE.SEMANTIC_MODEL_REVIEW_DIMENSIONS)
        ]
        dimensions = [*base_dimensions, partition_dimension]

        self.assertEqual(
            EVIDENCE.semantic_model_item_dimension_ids_error(dimensions),
            "",
        )

        missing_base = [
            dimension
            for dimension in dimensions
            if dimension["id"] != "carrier_and_domain"
        ]
        self.assertIn(
            "omit a required schema-2 base dimension",
            EVIDENCE.semantic_model_item_dimension_ids_error(missing_base),
        )

        unmarked_partition = json.loads(json.dumps(dimensions))
        for dimension in unmarked_partition:
            if dimension["id"] == AUDIT.SOURCE_EQUALITY_PARTITION_DIMENSION:
                dimension.pop("requires_source_equality_partition_analysis")
        self.assertIn(
            "explicitly generated source-pinned",
            EVIDENCE.semantic_model_item_dimension_ids_error(unmarked_partition),
        )

        unsupported = [*dimensions, {"id": "unrelated_extension"}]
        self.assertIn(
            "unsupported non-base extension",
            EVIDENCE.semantic_model_item_dimension_ids_error(unsupported),
        )

    def test_sidecar_cannot_omit_either_partition_direction(self) -> None:
        item, _source_map = self.generated_partition_dimension()
        dimensions = item["dimensions"]
        partition_dimension = next(
            dimension
            for dimension in dimensions
            if dimension["id"] == AUDIT.SOURCE_EQUALITY_PARTITION_DIMENSION
        )
        pin = partition_dimension["source_equality_partition_association"][
            "semantic_association_sha256"
        ]

        def response() -> dict[str, object]:
            return {
                "classification": "semantic_model_review",
                "semantic_model_dimensions": {
                    "expanded_binders_and_domain": {
                        "verdict": "matches_source_model",
                        "source_locator": "source.txt:1",
                        "semantic_comparison": "The ordinary domain is unchanged.",
                        "lean_evidence": "The expanded endpoint quantifies over its stated domain.",
                    },
                    AUDIT.SOURCE_EQUALITY_PARTITION_DIMENSION: {
                        "verdict": "matches_source_model",
                        "source_locator": "source.txt:1",
                        "semantic_comparison": (
                            "The source requires exact equality classes rather than "
                            "only within-class feature agreement."
                        ),
                        "lean_evidence": "The expanded model exposes the exact two-way condition.",
                        "source_equality_partition_analysis": {
                            "semantic_association_sha256": pin,
                            "relation": "feature_equality_iff_class_equality",
                            "feature_equality_implies_class_equality": {
                                "verdict": "exposed_as_source_model_condition",
                                "lean_evidence": "The expanded model includes feature equality implying equal class labels.",
                            },
                            "class_equality_implies_feature_equality": {
                                "verdict": "exposed_as_source_model_condition",
                                "lean_evidence": "The expanded model includes equal class labels implying feature equality.",
                            },
                            "lean_bridge_evidence": "Together the two expanded implications give the required iff.",
                        },
                    },
                },
            }

        self.assertTrue(EVIDENCE.semantic_model_judgment_is_complete(item, response()))
        for omitted in (
            "feature_equality_implies_class_equality",
            "class_equality_implies_feature_equality",
        ):
            incomplete = response()
            analysis = incomplete["semantic_model_dimensions"][
                AUDIT.SOURCE_EQUALITY_PARTITION_DIMENSION
            ]["source_equality_partition_analysis"]
            del analysis[omitted]
            self.assertFalse(
                EVIDENCE.semantic_model_judgment_is_complete(item, incomplete),
                omitted,
            )

        weaker = response()
        weaker_analysis = weaker["semantic_model_dimensions"][
            AUDIT.SOURCE_EQUALITY_PARTITION_DIMENSION
        ]["source_equality_partition_analysis"]
        weaker_analysis["class_equality_implies_feature_equality"][
            "verdict"
        ] = "missing_or_weaker"
        self.assertFalse(
            EVIDENCE.semantic_model_judgment_is_complete(item, weaker),
            "a one-way within-class agreement cannot support a full source-model match",
        )

    def test_non_opt_in_contexts_keep_feature_scoped_engine_identity_unchanged(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper = root / "papers" / "Fixture"
            audit = paper / "audit"
            audit.mkdir(parents=True)
            map_path = audit / "paper_statement_map.json"
            map_path.write_text(json.dumps({"items": {}}), encoding="utf-8")
            baseline = AUDIT.source_record_feature_scoped_engine_identities(root, paper)

            map_path.write_text(
                json.dumps(
                    {
                        "items": {
                            "ordinary_source_context": {
                                "semantic_context_requirements": [
                                    {
                                        "kind": "ordinary_source_convention",
                                        "source_location": "source.txt:1",
                                        "explanation": "A source-only convention.",
                                        "source_anchor_evidence": [],
                                    }
                                ]
                            }
                        }
                    }
                ),
                encoding="utf-8",
            )
            unchanged = AUDIT.source_record_feature_scoped_engine_identities(root, paper)

        self.assertEqual(baseline, unchanged)
        self.assertNotIn(
            AUDIT.EQUALITY_DEFINED_PARTITION_CONTEXT_SURFACE_ENGINE_IDENTITY,
            unchanged,
        )


class SourceRecordDigestTests(unittest.TestCase):
    def setUp(self) -> None:
        # These are intentionally static ``--no-lean`` generator fixtures.
        # Supply an explicit synthetic Lean-owned receipt so they exercise the
        # raw producer without weakening the production CLI's closure gate.
        def provider(root: Path, **_kwargs: object) -> Mock:
            value = Mock()
            value.root = Path(root).resolve()
            value.finalization_problems.return_value = ()
            return value

        def fixture_closure(
            root: Path,
            paper_dir: Path,
            **_kwargs: object,
        ) -> tuple[object, str]:
            status_path = paper_dir / "status.json"
            interface = AUDIT.review_source_path(root, paper_dir, status_path)
            sources = {
                interface.resolve(),
                *AUDIT.diagnostic_imported_paper_lean_files(root, [interface]),
            }
            record = lean_import_closure_record(
                root, interface, sorted(sources)
            )
            return (
                AUDIT.source_record_lean_import_closure_from_record(
                    root, interface, record
                ),
                "",
            )

        provider_patch = patch.object(
            AUDIT, "WorktreeImportClosureProvider", side_effect=provider
        )
        closure_patch = patch.object(
            AUDIT,
            "source_record_lean_import_closure_for_paper",
            side_effect=fixture_closure,
        )
        provider_patch.start()
        closure_patch.start()
        self.addCleanup(provider_patch.stop)
        self.addCleanup(closure_patch.stop)

