    def test_aggregate_only_semantic_item_keeps_exact_route_signature(self) -> None:
        """A missing source identity must not erase a verified Lean route.

        The route is useful for the normal named-theory hidden-premise
        projection, while the absent source identity still forbids narrow LLM
        judgment reuse.
        """

        qualified = "Fixture.PaperInterface.corrected_target"
        declaration = "theorem corrected_target (model : Model) : True := by trivial"
        declaration_sha = hashlib.sha256(declaration.encode("utf-8")).hexdigest()
        signature_sha = hashlib.sha256(b"elaborated corrected target").hexdigest()
        items: list[dict[str, object]] = [
            {
                "judgment_key": "semantic-model::corrected-target",
                "qualified_declaration": qualified,
                "reviewed_declaration_identity": {
                    "qualified_declaration": qualified,
                    "declaration_sha256": declaration_sha,
                },
                "lean_source_declaration": declaration,
            }
        ]

        AUDIT.attach_source_record_item_digests(
            items,
            row_qualified_names={"corrected_target": qualified},
            elaborated_signature_sha256_by_qualified={qualified: signature_sha},
        )

        item = items[0]
        self.assertEqual(
            item["source_record_item_reuse_eligibility"],
            {
                "eligible": False,
                "blockers": ["no source-content semantic identity"],
            },
        )
        self.assertNotIn("source_record_item_sha256", item)
        self.assertEqual(
            item["reviewed_elaborated_signature_identities"],
            [
                {
                    "qualified_declaration": qualified,
                    "elaborated_signature_sha256": signature_sha,
                }
            ],
        )
        self.assertEqual(
            reusable_item_metadata_error(
                item,
                expected_item_digest_schema=REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            ),
            "",
        )
        self.assertEqual(
            EVIDENCE.corrected_model_raw_item_freshness_mode(item),
            ("aggregate", ""),
        )
        self.assertEqual(
            source_record_raw_reusable_item_metadata_error(
                {"semantic_model_items": items},
                expected_item_digest_schema=REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            ),
            "",
        )
        self.assertEqual(
            REPO.source_record_expected_item_digests(
                {"semantic_model_items": items}
            ),
            {},
        )
        malformed = {
            **item,
            "reviewed_elaborated_signature_identities": [
                {
                    "qualified_declaration": qualified,
                    "elaborated_signature_sha256": "not-a-sha256",
                }
            ],
        }
        self.assertIn(
            "without a SHA-256 digest",
            reusable_item_metadata_error(
                malformed,
                expected_item_digest_schema=REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            ),
        )
        self.assertEqual(
            EVIDENCE.corrected_model_raw_item_freshness_mode(malformed)[0],
            None,
        )

    def test_item_digest_binds_expanded_premise_and_result_surface(self) -> None:
        """Distinct theorem premises cannot share a reusable receipt.

        Binder labels are deliberately excluded from the identity, but the
        actual delta-expanded premise and the target result must remain bound.
        This is the regression that prevents one theorem's `0 < alpha`,
        `alpha < 1`, and unrelated premise from inheriting one judgment.
        """

        qualified = "Fixture.PaperInterface.endpoint"
        source_item: dict[str, object] = {
            "statement": "The source theorem has a constrained parameter.",
            "source_kind": "theorem",
            "source_status": "exact",
        }
        source_map: dict[str, object] = {"items": {"source_result": source_item}}
        source_identity = AUDIT.source_record_source_item_semantic_sha256(
            source_item, ""
        )

        def item(
            binder: str,
            *,
            expanded_input: str,
            result: str = "Target alpha",
        ) -> dict[str, object]:
            return {
                "row": "endpoint",
                "judgment_key": f"endpoint.{binder} : Alias alpha",
                "kind": "semantic_proposition_premise",
                "input": {"names": binder, "type": "Alias alpha"},
                "expanded_input_type": expanded_input,
                "row_result_type": result,
                "source_contract_association": {
                    "source_item_identities": [
                        {"source_semantic_sha256": source_identity}
                    ],
                    "reviewed_declaration_identity": {
                        "qualified_declaration": qualified
                    },
                },
            }

        items = [
            item("hleft", expanded_input="0 < alpha"),
            item("hright", expanded_input="alpha < 1"),
            item("hrenamed", expanded_input="0 < alpha"),
            item(
                "hsamepremise",
                expanded_input="0 < alpha",
                result="OtherTarget alpha",
            ),
        ]
        AUDIT.attach_source_record_item_digests(
            items,
            paper_statement_map=source_map,
            row_qualified_names={"endpoint": qualified},
            elaborated_signature_sha256_by_qualified={qualified: "a" * 64},
        )

        self.assertTrue(
            all(
                item["source_record_item_reuse_eligibility"]["eligible"]
                for item in items
            )
        )
        self.assertNotEqual(
            items[0]["source_record_item_sha256"],
            items[1]["source_record_item_sha256"],
        )
        self.assertEqual(
            items[0]["source_record_item_sha256"],
            items[2]["source_record_item_sha256"],
        )
        self.assertNotEqual(
            items[0]["source_record_item_sha256"],
            items[3]["source_record_item_sha256"],
        )

    def test_item_and_raw_receipts_pin_coverage_protocol(self) -> None:
        qualified = "Fixture.PaperInterface.endpoint"
        source_item: dict[str, object] = {
            "statement": "The source endpoint holds.",
            "source_kind": "theorem",
            "source_status": "exact",
        }
        source_map: dict[str, object] = {"items": {"source_result": source_item}}
        source_identity = AUDIT.source_record_source_item_semantic_sha256(
            source_item, ""
        )

        def generated_item() -> dict[str, object]:
            return {
                "row": "endpoint",
                "judgment_key": "endpoint.h : Ready model",
                "expanded_input_type": "Ready model",
                "row_result_type": "Result model",
                "source_contract_association": {
                    "source_item_identities": [
                        {"source_semantic_sha256": source_identity}
                    ],
                    "reviewed_declaration_identity": {
                        "qualified_declaration": qualified
                    },
                },
            }

        digests: list[str] = []
        raw_digests: list[str] = []
        for protocol_digest in ("a" * 64, "b" * 64):
            items = [generated_item()]
            with patch.object(
                AUDIT,
                "formalization_coverage_protocol_digest",
                return_value=protocol_digest,
            ):
                AUDIT.attach_source_record_item_digests(
                    items,
                    paper_statement_map=source_map,
                    row_qualified_names={"endpoint": qualified},
                    elaborated_signature_sha256_by_qualified={qualified: "c" * 64},
                )
            digests.append(str(items[0]["source_record_item_sha256"]))

            raw_payload = {
                "formalization_coverage_protocol_sha256": protocol_digest,
                "source_record_input_fingerprint": {
                    "formalization_coverage_protocol_sha256": protocol_digest,
                },
            }
            stamp_source_record_audit_receipts(raw_payload)
            raw_digests.append(str(raw_payload["source_record_audit_sha256"]))

        self.assertNotEqual(digests[0], digests[1])
        self.assertNotEqual(raw_digests[0], raw_digests[1])

    def test_statement_map_hash_binds_aggregate_freshness_without_unpinned_reuse(self) -> None:
        """Map drift refreshes the aggregate without inventing item-level credit."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper = root / "papers" / "Fixture"
            audit = paper / "audit"
            audit.mkdir(parents=True)
            (paper / "PaperInterface.lean").write_text(
                "namespace Fixture\n"
                "theorem semantic_row (h : True) : True := h\n"
                "end Fixture\n",
                encoding="utf-8",
            )
            (paper / "status.json").write_text(
                json.dumps(
                    {
                        "review_surface": {
                            "source_file": "papers/Fixture/PaperInterface.lean",
                            "include_names": ["semantic_row"],
                        }
                    }
                ),
                encoding="utf-8",
            )
            map_path = audit / "paper_statement_map.json"
            first_map = '{"source_coverage_mode":"named_theoretical_statements"}\n'
            second_map = '{"source_coverage_mode":"named_theoretical_statements"}\n\n'
            map_path.write_text(first_map, encoding="utf-8")

            def generate(name: str) -> dict[str, object]:
                out = root / name
                with patch.object(
                    sys,
                    "argv",
                    [
                        "source_record_audit.py",
                        "--paper",
                        "Fixture",
                        "--root",
                        str(root),
                        "--out",
                        str(out),
                        "--no-lean",
                    ],
                ):
                    self.assertEqual(AUDIT.main(), 0)
                return json.loads(out.read_text(encoding="utf-8"))

            with patch.object(
                AUDIT,
                "source_premise_consistency_items",
                return_value=([], ""),
            ):
                first = generate("first.json")
                map_path.write_text(second_map, encoding="utf-8")
                second = generate("second.json")

        first_map_sha = hashlib.sha256(first_map.encode("utf-8")).hexdigest()
        second_map_sha = hashlib.sha256(second_map.encode("utf-8")).hexdigest()
        self.assertEqual(first["paper_statement_map_sha256"], first_map_sha)
        self.assertEqual(second["paper_statement_map_sha256"], second_map_sha)
        self.assertNotEqual(
            first["source_record_audit_sha256"],
            second["source_record_audit_sha256"],
        )
        first_item = first["boundary_input_items"][0]
        second_item = second["boundary_input_items"][0]
        self.assertNotIn("paper_statement_map_sha256", first_item)
        self.assertNotIn("paper_statement_map_sha256", second_item)
        self.assertEqual(
            first_item["source_record_item_reuse_eligibility"],
            {
                "eligible": False,
                "blockers": [
                    "no source-content semantic identity",
                    "no exact current elaborated review-route signature",
                ],
            },
        )
        self.assertEqual(
            second_item["source_record_item_reuse_eligibility"],
            first_item["source_record_item_reuse_eligibility"],
        )
        self.assertNotIn("source_record_item_sha256", first_item)
        self.assertNotIn("source_record_item_sha256", second_item)
        judgment_key = str(first_item["judgment_key"])
        self.assertEqual(judgment_key, str(second_item["judgment_key"]))
        self.assertFalse(
            REPO.source_record_judgment_current(
                judgment_key,
                {
                    "source_record_audit_sha256": first["source_record_audit_sha256"],
                    "source_record_item_sha256": "a" * 64,
                    "source_record_item_digest_schema": (
                        REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA
                    ),
                },
                digest=str(second["source_record_audit_sha256"]),
                expected_item_digests={},
            )
        )

