    def test_precloseout_projection_requires_alpha_equal_direct_spec_binders(self) -> None:
        """Only an exact current direct judgment can cover its transparent Spec twin."""

        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "Fixture"
            audit = paper / "audit"
            audit.mkdir(parents=True)
            (paper / "status.json").write_text(
                json.dumps({"status": "partially formalized"}), encoding="utf-8"
            )
            declarations = {
                "evidence_row": (
                    "theorem evidence (α : Type) (h : α = α) : "
                    "∀ x : α, x = x := by rfl"
                ),
                "spec_row": (
                    "abbrev spec (β : Type) (g : β = β) : Prop := "
                    "∀ y : β, y = y"
                ),
            }
            direct_key = "evidence_row.h : α = α"
            spec_key = "spec_row.g : β = β"
            inputs = [
                {
                    "row": "evidence_row",
                    "input": {"names": "h", "type": "α = α"},
                    "kind": "semantic_proposition_premise",
                    "judgment_key": direct_key,
                },
                {
                    "row": "spec_row",
                    "input": {"names": "g", "type": "β = β"},
                    "kind": "semantic_proposition_premise",
                    "judgment_key": spec_key,
                },
            ]
            semantic_model_items = [
                {
                    "semantic_contract_group": {
                        "schema": 1,
                        "structural_alpha_normalized_equal": True,
                        "member_rows": [
                            {
                                "role": "direct_evidence",
                                "qualified_declaration": "Fixture.Paper.evidence",
                            },
                            {
                                "role": "transparent_spec",
                                "qualified_declaration": "Fixture.Paper.spec",
                            },
                        ],
                        "source_item_identities": [{"source_key": "source_result"}],
                        "surface_root": {"surface": "spec"},
                        "direct_evidence_type": {"surface": "evidence"},
                    }
                }
            ]
            from scripts import audit_repository as repository
            receipt_items: list[dict[str, object]] = []

            with patch.object(
                repository,
                "semantic_contract_precloseout_exact_contract_pairs",
                return_value=(("Fixture.Paper.evidence", "Fixture.Paper.spec"),),
            ):
                covered = AUDIT.precloseout_contract_covered_boundary_input_keys(
                    paper,
                    inputs,
                    qualified_row_refs={
                        "evidence_row": "Fixture.Paper.evidence",
                        "spec_row": "Fixture.Paper.spec",
                    },
                    declarations=declarations,
                    proposition_aliases={},
                    type_aliases=None,
                    conclusion_dependency_items=[],
                    semantic_model_items=semantic_model_items,
                    statement_ledger_covered_input_keys=set(),
                    projection_items=receipt_items,
                )
                current_direct_ledger = AUDIT.precloseout_contract_covered_boundary_input_keys(
                    paper,
                    inputs,
                    qualified_row_refs={
                        "evidence_row": "Fixture.Paper.evidence",
                        "spec_row": "Fixture.Paper.spec",
                    },
                    declarations=declarations,
                    proposition_aliases={},
                    type_aliases=None,
                    conclusion_dependency_items=[],
                    semantic_model_items=semantic_model_items,
                    statement_ledger_covered_input_keys={direct_key},
                )

        self.assertEqual(covered, {spec_key})
        self.assertEqual(current_direct_ledger, {spec_key})
        self.assertEqual(
            REPO.source_record_required_input_judgment_keys(
                {
                    "expected_input_judgment_keys": [direct_key, spec_key],
                    "statement_ledger_covered_boundary_input_keys": sorted(covered),
                    "conclusion_dependency_items": [],
                }
            ),
            {direct_key},
        )
        self.assertEqual(len(receipt_items), 1)
        receipt = receipt_items[0]
        self.assertEqual(
            receipt["source_item_keys"],
            ["source_result"],
        )
        self.assertEqual(receipt["direct_judgment_key"], direct_key)
        self.assertTrue(receipt["direct_source_record_judgment_required"])
        self.assertEqual(receipt["projected_spec_judgment_key"], spec_key)
        self.assertRegex(str(receipt["structural_surface_sha256"]), r"^[0-9a-f]{64}$")

