    def test_thin_paper_alias_uses_target_premises_in_boundary_lanes(self) -> None:
        """A wrapper must not erase the target theorem's caller-supplied proof.

        The source-map route and reviewed identity intentionally remain the
        paper-facing alias.  Only the semantic/boundary surface moves to the
        uniquely resolved target declaration.
        """

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper = root / "papers" / "Fixture"
            audit = paper / "audit"
            audit.mkdir(parents=True)
            (paper / "Implementation.lean").write_text(
                "namespace Fixture.Implementation\n"
                "def Quartz (n : Nat) : Prop := n = n\n"
                "theorem underlying (n : Nat) (h : Quartz n) : Quartz n := h\n"
                "end Fixture.Implementation\n",
                encoding="utf-8",
            )
            wrapper_source = (
                "import Fixture.Implementation\n\n"
                "namespace Fixture.PaperInterface\n"
                "abbrev endpoint := @Fixture.Implementation.underlying\n"
                "end Fixture.PaperInterface\n"
            )
            (paper / "PaperInterface.lean").write_text(
                wrapper_source, encoding="utf-8"
            )
            (paper / "status.json").write_text(
                json.dumps(
                    {
                        "review_surface": {
                            "source_file": "papers/Fixture/PaperInterface.lean",
                            "include_names": ["endpoint"],
                            "semantic_model_review": {
                                "schema": 1,
                                "required_dimensions": list(
                                    AUDIT.SEMANTIC_MODEL_LEGACY_DIMENSION_ORDER
                                ),
                            },
                        }
                    }
                ),
                encoding="utf-8",
            )
            (audit / "paper_statement_map.json").write_text(
                json.dumps(
                    {
                        "source_coverage_mode": "named_theoretical_statements",
                        "items": {
                            "theorem_1": {
                                "source_kind": "theorem",
                                "statement": "Theorem 1.",
                                "lean_declarations": [
                                    "Fixture.PaperInterface.endpoint"
                                ],
                            }
                        },
                    }
                ),
                encoding="utf-8",
            )
            out = root / "payload.json"
            with (
                patch.object(
                    AUDIT,
                    "source_premise_consistency_items",
                    return_value=([], ""),
                ),
                patch.object(
                    sys,
                    "argv",
                    [
                        "source_record_audit.py",
                        "--paper",
                        "Fixture",
                        "--root",
                        str(root),
                        "--out",
                        str(out),
                        "--no-lean",
                    ],
                ),
            ):
                self.assertEqual(AUDIT.main(), 0)
            payload = json.loads(out.read_text(encoding="utf-8"))

        row = payload["configured_review_rows"][0]
        self.assertEqual(
            row["qualified_declaration"], "Fixture.PaperInterface.endpoint"
        )
        self.assertIn("abbrev endpoint", row["lean_source_declaration"])
        self.assertEqual(
            row["effective_qualified_declaration"],
            "Fixture.Implementation.underlying",
        )
        self.assertIn("theorem underlying", row["effective_lean_source_declaration"])
        self.assertTrue(row["review_alias_expansion"]["alias_present"])
        self.assertTrue(row["review_alias_expansion"]["complete"])
        self.assertEqual(
            payload["row_visible_inputs"]["endpoint"],
            [
                {"names": "n", "type": "Nat"},
                {"names": "h", "type": "Quartz n"},
            ],
        )

        boundary = next(
            item
            for item in payload["boundary_input_items"]
            if item["row"] == "endpoint" and item["input"]["names"] == "h"
        )
        self.assertEqual(boundary["kind"], "semantic_proposition_premise")
        self.assertEqual(boundary["result_relation"], "equivalent")
        self.assertEqual(
            boundary["reviewed_declaration_identity"]["qualified_declaration"],
            "Fixture.PaperInterface.endpoint",
        )
        self.assertEqual(
            boundary["effective_qualified_declaration"],
            "Fixture.Implementation.underlying",
        )
        self.assertIn("abbrev endpoint", boundary["lean_source_declaration"])
        self.assertIn(
            "theorem underlying", boundary["effective_lean_source_declaration"]
        )

        dependency = next(
            item
            for item in payload["conclusion_dependency_items"]
            if item["row"] == "endpoint" and item["binder"] == "h"
        )
        self.assertEqual(dependency["kind"], "direct_conclusion_input")
        self.assertEqual(dependency["row_result_type"], "Quartz n")
        self.assertEqual(
            dependency["reviewed_declaration_identity"]["qualified_declaration"],
            "Fixture.PaperInterface.endpoint",
        )
        self.assertEqual(
            dependency["effective_qualified_declaration"],
            "Fixture.Implementation.underlying",
        )

