    def test_configured_review_preflight_checks_all_configured_rows_then_reuses_subset(self) -> None:
        lean_result = {
            "returncode": 0,
            "requested_checked_rows": [
                {
                    "row": "named_result",
                    "qualified_declaration": "Fixture.PaperInterface.named_result",
                },
                {
                    "row": "out_of_mode_result",
                    "qualified_declaration": "Fixture.PaperInterface.out_of_mode_result",
                },
            ],
            "checked_rows": [],
            "fresh_source_elaboration": {"mode": "isolated_temp_overlay"},
        }
        with patch.object(AUDIT, "lean_check", return_value=lean_result) as check:
            preflight = AUDIT.configured_review_reference_preflight(
                root=ROOT,
                paper_id="Fixture",
                interface_path=ROOT / "papers" / "Fixture" / "PaperInterface.lean",
                import_module="Fixture.PaperInterface",
                row_namespace="Fixture.PaperInterface",
                configured_rows=["named_result", "out_of_mode_result"],
                qualified_row_refs={
                    "named_result": "Fixture.PaperInterface.named_result",
                    "out_of_mode_result": "Fixture.PaperInterface.out_of_mode_result",
                },
                assumption_row_names=set(),
                missing_configured_rows=[],
                resolution_failures=[],
                no_lean=False,
                max_output_chars=1000,
            )

        self.assertEqual(preflight["status"], "passed")
        self.assertEqual(
            check.call_args.kwargs["row_names"],
            ["named_result", "out_of_mode_result"],
        )
        narrowed = AUDIT.lean_check_subset_from_configured_preflight(
            preflight,
            row_names=["named_result"],
            row_namespace="Fixture.PaperInterface",
            qualified_row_refs={
                "named_result": "Fixture.PaperInterface.named_result",
                "out_of_mode_result": "Fixture.PaperInterface.out_of_mode_result",
            },
        )
        self.assertEqual(
            narrowed["requested_checked_rows"],
            [
                {
                    "row": "named_result",
                    "qualified_declaration": "Fixture.PaperInterface.named_result",
                }
            ],
        )
        self.assertEqual(narrowed["checked_rows"], narrowed["requested_checked_rows"])

        zero_surface = AUDIT.lean_check_subset_from_configured_preflight(
            preflight,
            row_names=[],
            row_namespace="Fixture.PaperInterface",
            qualified_row_refs={
                "named_result": "Fixture.PaperInterface.named_result",
                "out_of_mode_result": "Fixture.PaperInterface.out_of_mode_result",
            },
        )
        self.assertEqual(
            zero_surface["command"],
            "skipped Lean check: no source-record rows or fields",
        )
        self.assertEqual(zero_surface["requested_checked_rows"], [])
        self.assertEqual(zero_surface["checked_rows"], [])
        self.assertEqual(
            zero_surface["fresh_source_elaboration"]["mode"],
            "not_run_without_lean",
        )

