    def test_audit_surface_digest_ignores_item_digest_metadata(self) -> None:
        plain = {
            "conclusion_dependency_items": [
                {
                    "judgment_key": "row.h : SourcePredicate x",
                    "line": 12,
                    "type": "SourcePredicate x",
                }
            ]
        }
        with_item_digest = {
            "conclusion_dependency_items": [
                {
                    "judgment_key": "row.h : SourcePredicate x",
                    "line": 12,
                    "type": "SourcePredicate x",
                    "source_record_item_sha256": "metadata-only",
                }
            ]
        }
        line_drift = {
            "conclusion_dependency_items": [
                {
                    "judgment_key": "row.h : SourcePredicate x",
                    "line": 13,
                    "type": "SourcePredicate x",
                    "source_record_item_sha256": "metadata-only",
                }
            ]
        }

        self.assertEqual(
            AUDIT.stable_digest(
                plain, volatile_keys=AUDIT.AUDIT_SURFACE_DIGEST_VOLATILE_KEYS
            ),
            AUDIT.stable_digest(
                with_item_digest,
                volatile_keys=AUDIT.AUDIT_SURFACE_DIGEST_VOLATILE_KEYS,
            ),
        )
        self.assertNotEqual(
            AUDIT.stable_digest(
                plain, volatile_keys=AUDIT.AUDIT_SURFACE_DIGEST_VOLATILE_KEYS
            ),
            AUDIT.stable_digest(
                line_drift, volatile_keys=AUDIT.AUDIT_SURFACE_DIGEST_VOLATILE_KEYS
            ),
        )

