    def test_direct_shared_digest_reuses_only_at_its_current_key(self) -> None:
        """A shared digest permits direct reuse but never an ambiguous remap."""

        first_key = "row.left : SourceAssumption"
        second_key = "row.right : SourceAssumption"
        legacy_key = "renamed_storage_key"
        shared_digest = "a" * 64
        current_digest = "b" * 64
        old_digest = "c" * 64
        first = {
            "judgment_key": first_key,
            **reusable_item_receipt(
                "semantic_proposition_premise", shared_digest, marker="a"
            ),
        }
        second = {
            "judgment_key": second_key,
            **reusable_item_receipt(
                "semantic_proposition_premise", shared_digest, marker="b"
            ),
        }
        payload = {
            "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
            "source_record_audit_sha256": current_digest,
            "boundary_input_items": [first, second],
        }
        expected_direct = {first_key: shared_digest, second_key: shared_digest}
        self.assertEqual(AUDIT.current_item_digests(payload), expected_direct)
        self.assertEqual(
            EVIDENCE.source_record_required_item_digests(payload), expected_direct
        )
        self.assertEqual(
            REPO.source_record_expected_item_digests(payload), expected_direct
        )
        self.assertEqual(
            GATE.current_item_digests(payload),
            {
                first_key: (REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA, shared_digest),
                second_key: (REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA, shared_digest),
            },
        )
        self.assertEqual(AUDIT.current_unique_item_digest_keys(payload), {})
        self.assertEqual(EVIDENCE.source_record_unique_item_digest_keys(payload), {})

        sidecar = {
            "schema": 1,
            "paper": "Fixture",
            "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
            "source_record_audit_sha256": old_digest,
            "validator": "fixture",
            "validated_at": "2026-07-27T00:00:00Z",
            "items": {
                first_key: {
                    "classification": "validated_source_assumption",
                    "source_record_item_digest_schema": (
                        REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA
                    ),
                    "source_record_item_sha256": shared_digest,
                },
                legacy_key: {
                    "classification": "validated_source_assumption",
                    "source_record_item_digest_schema": (
                        REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA
                    ),
                    "source_record_item_sha256": shared_digest,
                },
            },
        }
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "papers" / "Fixture"
            audit_dir = paper / "audit"
            audit_dir.mkdir(parents=True)
            (audit_dir / "source_record_match_llm.json").write_text(
                json.dumps(sidecar), encoding="utf-8"
            )
            self.assertEqual(
                set(AUDIT.current_source_record_judgments(paper, "Fixture", payload)),
                {first_key},
            )

        with patch.object(EVIDENCE, "source_record_audit_identity_error", return_value=""):
            self.assertEqual(
                set(EVIDENCE.current_source_record_judgment_items(payload, sidecar)),
                {first_key},
            )

        unique_payload = {**payload, "boundary_input_items": [first]}
        unique_sidecar = {
            **sidecar,
            "items": {legacy_key: sidecar["items"][legacy_key]},
        }
        self.assertEqual(
            AUDIT.current_unique_item_digest_keys(unique_payload),
            {shared_digest: first_key},
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            paper = Path(tmpdir) / "papers" / "Fixture"
            audit_dir = paper / "audit"
            audit_dir.mkdir(parents=True)
            (audit_dir / "source_record_match_llm.json").write_text(
                json.dumps(unique_sidecar), encoding="utf-8"
            )
            self.assertEqual(
                set(
                    AUDIT.current_source_record_judgments(
                        paper, "Fixture", unique_payload
                    )
                ),
                {first_key},
            )
        with patch.object(EVIDENCE, "source_record_audit_identity_error", return_value=""):
            self.assertEqual(
                set(
                    EVIDENCE.current_source_record_judgment_items(
                        unique_payload, unique_sidecar
                    )
                ),
                {first_key},
            )

    def test_source_record_judgments_use_review_not_extraction_protocol(self) -> None:
        key = "row.h : SourceAssumption"
        item_digest = "a" * 64
        audit_digest = "b" * 64
        audit_payload = {
            "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
            "source_record_audit_sha256": audit_digest,
            "formalization_coverage_protocol_sha256": "c" * 64,
            "boundary_input_items": [
                {
                    "judgment_key": key,
                    **reusable_item_receipt(
                        "semantic_proposition_premise", item_digest
                    ),
                }
            ],
        }
        sidecar = {
            "schema": 1,
            "paper": "Fixture",
            "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
            "source_record_audit_sha256": audit_digest,
            "validator": "fixture",
            "validated_at": "2026-08-02T00:00:00Z",
            "items": {
                key: {
                    "classification": "validated_source_assumption",
                    "source_record_item_digest_schema": (
                        REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA
                    ),
                    "source_record_item_sha256": item_digest,
                }
            },
        }

        self.assertEqual(
            AUDIT.current_source_record_judgments_from_payload(
                sidecar, "Fixture", audit_payload
            ),
            {},
        )
        current = {
            **sidecar,
            "formalization_review_protocol_sha256": (
                formalization_review_protocol_digest()
            ),
        }
        self.assertEqual(
            set(
                AUDIT.current_source_record_judgments_from_payload(
                    current, "Fixture", audit_payload
                )
            ),
            {key},
        )
        stale = {
            **current,
            "formalization_review_protocol_sha256": "d" * 64,
        }
        self.assertEqual(
            AUDIT.current_source_record_judgments_from_payload(
                stale, "Fixture", audit_payload
            ),
            {},
        )

        legacy_audit = {
            **audit_payload,
            "formalization_protocol_sha256": formalization_protocol_digest(),
        }
        legacy_audit.pop("formalization_coverage_protocol_sha256")
        self.assertEqual(
            set(
                AUDIT.current_source_record_judgments_from_payload(
                    sidecar, "Fixture", legacy_audit
                )
            ),
            {key},
        )
        with patch.object(
            EVIDENCE, "source_record_audit_identity_error", return_value=""
        ):
            self.assertEqual(
                EVIDENCE.current_source_record_judgment_items(
                    audit_payload, sidecar
                ),
                {},
            )
            self.assertEqual(
                set(
                    EVIDENCE.current_source_record_judgment_items(
                        audit_payload, current
                    )
                ),
                {key},
            )
            self.assertEqual(
                EVIDENCE.current_source_record_judgment_items(
                    audit_payload, stale
                ),
                {},
            )
            self.assertEqual(
                set(
                    EVIDENCE.current_source_record_judgment_items(
                        legacy_audit, sidecar
                    )
                ),
                {key},
            )

