    def test_conditional_constructor_inputs_remain_diagnostics_until_selected(
        self,
    ) -> None:
        """A type-compatible helper cannot create global paper-assumption debt."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper = root / "papers" / "Fixture"
            audit = paper / "audit"
            audit.mkdir(parents=True)
            (paper / "PaperInterface.lean").write_text(
                "namespace Fixture\n"
                "theorem buildGoal (n : Nat) (h : 0 < n) : n = n := rfl\n"
                "theorem endpoint (n : Nat) (hgoal : n = n) : n = n := hgoal\n"
                "end Fixture\n",
                encoding="utf-8",
            )
            (paper / "status.json").write_text(
                json.dumps(
                    {
                        "review_surface": {
                            "source_file": "papers/Fixture/PaperInterface.lean",
                            "include_names": ["endpoint"],
                        }
                    }
                ),
                encoding="utf-8",
            )
            (audit / "paper_statement_map.json").write_text("{}\n", encoding="utf-8")
            out = root / "payload.json"
            with (
                patch.object(
                    AUDIT,
                    "source_premise_consistency_items",
                    return_value=([], ""),
                ),
                patch.object(
                    AUDIT,
                    "enforce_elaborated_constructor_result_types",
                    return_value="",
                ),
                patch.object(
                    sys,
                    "argv",
                    [
                        "source_record_audit.py",
                        "--paper",
                        "Fixture",
                        "--root",
                        str(root),
                        "--out",
                        str(out),
                        "--no-lean",
                    ],
                ),
            ):
                self.assertEqual(AUDIT.main(), 0)
            payload = json.loads(out.read_text(encoding="utf-8"))

        dependency = next(
            item
            for item in payload["conclusion_dependency_items"]
            if item["judgment_key"] == "endpoint.hgoal : n = n"
        )
        candidate = dependency["conditional_constructors"][0]
        antecedent = candidate["required_source_antecedent_fields"][0]
        antecedent_key = f"{antecedent['structure']}.{antecedent['field']}"
        self.assertEqual(antecedent["structure"], "ConstructorInput")
        self.assertEqual(antecedent_key, "ConstructorInput.Fixture.buildGoal_input_1")
        self.assertNotIn(antecedent_key, payload["expected_field_judgment_keys"])
        self.assertNotIn(
            antecedent_key,
            {
                item["judgment_key"]
                for item in payload["recursive_field_items"]
            },
        )

        target_key = dependency["judgment_key"]
        checked_projection = {
            "constructor_declaration": candidate["declaration"],
            "conditional_constructor_result_type": candidate["result_type"],
            "source_antecedent_keys": [antecedent_key],
        }
        judgments = {
            target_key: {
                "classification": "proved_from_primitives",
                "checked_projection": checked_projection,
            }
        }
        missing = AUDIT.dependency_checked_projection_result(
            dependency, set(), judgments
        )
        self.assertFalse(missing.accepted)
        self.assertIn("lack current validated_source_assumption", missing.reason)

        judgments[antecedent_key] = {
            "classification": "validated_source_assumption",
            "source_location": "source.tex:12",
        }
        accepted = AUDIT.dependency_checked_projection_result(
            dependency, {antecedent_key}, judgments
        )
        self.assertTrue(accepted.accepted)

