    def test_result_local_lets_never_become_kr21_boundary_inputs(self) -> None:
        """Regression for 14 malformed KR21 boundary obligations from local lets."""

        declarations = AUDIT.parse_declarations(
            ROOT / "papers" / "KR21Monoculture" / "PaperInterface.lean"
        )
        namespace = "KR21Monoculture.PaperInterface."
        # These were the 14 pseudo-premises emitted before the source-boundary
        # parser recognized local theorem-result lets. The count is split by
        # source endpoint so changes to one local definition cannot silently
        # recreate an obligation under a different generated binder spelling.
        legacy_false_boundary_inputs = {
            "appendixB1_source_discrete_definition2_counterexample_semantic_complete": 1,
            "appendixB2_source_discrete_definition3_counterexample_semantic_complete": 2,
            "equationB1_counterexample_first_choice_x1_semantic_complete": 2,
            "equationB2_counterexample_first_choice_x2_semantic_complete": 2,
            "appendixC2_source_pairwise_full_events": 2,
            "theorem7_source_semantic_complete": 2,
            "equationC3_laplace_strict_conditional_ratio_eq_density_cdf_semantic_complete": 1,
            "theorem8_source_semantic_complete": 2,
        }
        expected_header_inputs = {
            "appendixB1_source_discrete_definition2_counterexample_semantic_complete": [],
            "appendixB2_source_discrete_definition3_counterexample_semantic_complete": [],
            "equationB1_counterexample_first_choice_x1_semantic_complete": [],
            "equationB2_counterexample_first_choice_x2_semantic_complete": [],
            "appendixC2_source_pairwise_full_events": [
                {"names": "theta xi xj", "type": "ℝ"},
                {"names": "htheta", "type": "0 < theta"},
                {"names": "hx", "type": "xj < xi"},
            ],
            "theorem7_source_semantic_complete": [
                {"names": "sigma xi xj", "type": "ℝ"},
                {"names": "hsigma", "type": "0 < sigma"},
                {"names": "hx", "type": "xj < xi"},
            ],
            "equationC3_laplace_strict_conditional_ratio_eq_density_cdf_semantic_complete": [
                {"names": "lam xi xj a", "type": "ℝ"},
                {"names": "hlam", "type": "0 < lam"},
            ],
            "theorem8_source_semantic_complete": [
                {"names": "sigma xi xj", "type": "ℝ"},
                {"names": "hsigma", "type": "0 < sigma"},
                {"names": "hx", "type": "xj < xi"},
            ],
        }

        self.assertEqual(sum(legacy_false_boundary_inputs.values()), 14)
        for row, expected_header in expected_header_inputs.items():
            with self.subTest(row=row):
                declaration = declarations[namespace + row]
                self.assertTrue(
                    AUDIT.result_type_starts_with_local_let(
                        AUDIT.declaration_result_type(declaration)
                    )
                )
                self.assertEqual(
                    AUDIT.header_inputs_from_declaration(declaration),
                    expected_header,
                )
                used_names = {
                    name
                    for visible_input in expected_header
                    for name in AUDIT.binder_names(visible_input["names"])
                }
                self.assertEqual(
                    AUDIT.conclusion_inputs_from_declaration(declaration, used_names),
                    [],
                )
                self.assertEqual(
                    AUDIT.visible_inputs_from_declaration(declaration),
                    expected_header,
                )

