    def test_consistent_adversarial_renaming_preserves_circular_verdict(self) -> None:
        def verdict(
            target: str,
            target_parameter: str,
            target_field_name: str,
            sibling: str,
            sibling_parameter: str,
            sibling_field_name: str,
            constructor_name: str,
            binder_name: str,
        ) -> tuple[int, int, bool]:
            target_field = fixture_field(
                target,
                target_field_name,
                f"∃ q : Nat, Wins {target_parameter} = true",
            )
            sibling_field = fixture_field(
                sibling,
                sibling_field_name,
                f"∃ r : Nat, Wins {sibling_parameter} = true",
            )
            structures = {
                target: AUDIT.StructureInfo(
                    target,
                    "papers/Fixture/Model.lean",
                    1,
                    [target_field],
                    [target_parameter],
                ),
                sibling: AUDIT.StructureInfo(
                    sibling,
                    "papers/Fixture/Imported.lean",
                    1,
                    [sibling_field],
                    [sibling_parameter],
                ),
            }
            constructor = local_declaration(
                constructor_name,
                f"def {constructor_name} (k : Nat) ({binder_name} : {sibling} k) : "
                f"{target} k := {{ {target_field_name} := {binder_name}.{sibling_field_name} }}",
            )
            valid, rejected = self.classify_record_constructor(
                constructor,
                target=target,
                target_field=target_field,
                structures=structures,
            )
            return len(valid), len(rejected), bool(rejected[0].circular_inputs)

        first = verdict(
            "Quartz",
            "a",
            "first",
            "Pebble",
            "b",
            "second",
            "whisper",
            "cargo",
        )
        renamed = verdict(
            "Assumptions",
            "u",
            "primitive",
            "Certificate",
            "v",
            "result",
            "deriveFromModel",
            "inputs",
        )
        self.assertEqual(first, (0, 1, True))
        self.assertEqual(renamed, first)

