    def test_unicode_generic_carrier_is_data_in_result_quantifier(self) -> None:
        """A Type*-kinded Unicode carrier remains data in ``∀ t : κ``.

        This is a semantic classification regression: the carrier kind, rather
        than the spelling of either the type or conclusion binder, determines
        whether the audit creates a source-assumption obligation.
        """

        declaration = (
            "theorem endpoint {κ : Type*} [Fintype κ] : "
            "∀ t : κ, True := by trivial"
        )
        data_heads = AUDIT.declaration_type_variable_heads(declaration)
        self.assertEqual(data_heads, {"κ"})
        self.assertTrue(AUDIT.is_definitely_data_type("κ", data_heads=data_heads))
        self.assertEqual(
            AUDIT.boundary_input_kind(
                "endpoint",
                {"names": "t", "type": "κ"},
                proposition_heads=set(),
                data_heads=data_heads,
            ),
            "",
        )

