    def test_transitive_axiom_and_hidden_projection_are_not_constructors(self) -> None:
        target_field = fixture_field("Quartz", "first", "Wins a = true")
        sibling_field = fixture_field("Pebble", "second", "Wins b = true")
        structures = {
            "Quartz": AUDIT.StructureInfo(
                "Quartz", "papers/Fixture/Model.lean", 1, [target_field], ["a"]
            ),
            "Pebble": AUDIT.StructureInfo(
                "Pebble", "papers/Fixture/Model.lean", 1, [sibling_field], ["b"]
            ),
        }
        for kind, provider_name, builder_name in (
            ("axiom", "smuggled", "directBuilder"),
            ("opaque", "sealed", "opaqueBuilder"),
            ("constant", "importedFact", "constantBuilder"),
        ):
            provider = local_declaration(
                provider_name,
                f"{kind} {provider_name} (n : Nat) : Wins n = true",
            )
            builder = local_declaration(
                builder_name,
                f"def {builder_name} (n : Nat) : Quartz n := "
                f"{{ first := {provider_name} n }}",
            )
            valid, rejected = self.classify_record_constructor(
                builder,
                target="Quartz",
                target_field=target_field,
                structures=structures,
                extra_declarations=[provider],
            )
            self.assertEqual(valid, [])
            self.assertIn("axiom/opaque/constant", rejected[0].circular_inputs[0])

        hidden_record = local_declaration(
            "stash", "axiom stash (n : Nat) : Pebble n"
        )
        hidden_projection = local_declaration(
            "extract",
            "theorem extract (n : Nat) : Wins n = true := (stash n).second",
        )
        indirect_builder = local_declaration(
            "indirectBuilder",
            "def indirectBuilder (n : Nat) : Quartz n := { first := extract n }",
        )
        valid, rejected = self.classify_record_constructor(
            indirect_builder,
            target="Quartz",
            target_field=target_field,
            structures=structures,
            extra_declarations=[hidden_record, hidden_projection],
        )
        self.assertEqual(valid, [])
        self.assertIn("axiom/opaque/constant", rejected[0].circular_inputs[0])

