    def test_duplicate_neutral_proposition_alias_short_names_require_lexical_context(self) -> None:
        alpha = local_declaration(
            "Alpha.Pebble",
            "def Pebble (u : Nat) : Prop := Wins u = true",
        )
        beta = local_declaration(
            "Beta.Pebble",
            "abbrev Pebble (u : Nat) : Prop := Eligible u",
        )
        forward = AUDIT.parse_proposition_aliases([alpha, beta])
        reverse = AUDIT.parse_proposition_aliases([beta, alpha])

        self.assertEqual(forward, reverse)
        self.assertEqual(set(forward), {"Alpha.Pebble", "Beta.Pebble"})
        self.assertEqual(
            AUDIT.proposition_type_relation(
                "Pebble candidate", "Wins candidate = true", forward
            ),
            "",
        )
        self.assertEqual(
            AUDIT.proposition_type_relation(
                "Pebble candidate", "Eligible candidate", forward
            ),
            "",
        )
        alpha_scoped = AUDIT.proposition_aliases_in_namespace(forward, "Alpha")
        beta_scoped = AUDIT.proposition_aliases_in_namespace(forward, "Beta")
        self.assertEqual(
            AUDIT.proposition_type_relation(
                "Pebble candidate", "Wins candidate = true", alpha_scoped
            ),
            "equivalent",
        )
        self.assertEqual(
            AUDIT.proposition_type_relation(
                "Pebble candidate", "Eligible candidate", beta_scoped
            ),
            "equivalent",
        )
        self.assertEqual(
            AUDIT.proposition_type_relation(
                "Alpha.Pebble candidate", "Wins candidate = true", forward
            ),
            "equivalent",
        )
        self.assertEqual(
            AUDIT.proposition_type_relation(
                "Beta.Pebble candidate", "Eligible candidate", forward
            ),
            "equivalent",
        )

