    def test_nested_aliases_in_conjunctions_and_implications_are_circular(self) -> None:
        target_field = fixture_field("Quartz", "first", "Wins a = true")
        structures = {
            "Quartz": AUDIT.StructureInfo(
                "Quartz", "papers/Fixture/Model.lean", 1, [target_field], ["a"]
            )
        }
        first = local_declaration(
            "Pebble",
            "def Pebble (u : Nat) : Prop := Wins u = true",
        )
        second = local_declaration(
            "Fog",
            "abbrev Fog (v : Nat) : Prop := Pebble v",
        )
        conjunction = local_declaration(
            "whisper",
            "def whisper (n : Nat) (h : Pebble n ∧ Regular n) : Quartz n := "
            "{ first := by simpa [Pebble] using h.1 }",
        )
        implication = local_declaration(
            "murmur",
            "def murmur (n : Nat) (r : Regular n) (h : Regular n -> Fog n) : "
            "Quartz n := { first := by simpa [Fog, Pebble] using h r }",
        )
        declarations = [first, second, conjunction, implication]
        proposition_aliases = AUDIT.parse_proposition_aliases(declarations)

        for constructor, expected_input in (
            (conjunction, "h : Pebble n ∧ Regular n"),
            (implication, "h : Regular n -> Fog n"),
        ):
            with self.subTest(constructor=constructor.name):
                valid, rejected = AUDIT.constructor_candidates(
                    local_declarations=[constructor],
                    excluded_declaration="reviewed",
                    target_type="Quartz n",
                    target_structures={"Quartz"},
                    forbidden_input_structures=None,
                    aliases={},
                    conclusion_fields=[target_field],
                    row_result_type="Wins n = true",
                    structures=structures,
                    proposition_heads={"Wins", "Pebble", "Fog", "Regular"},
                    proposition_aliases=proposition_aliases,
                    data_heads=set(AUDIT.KNOWN_DATA_TYPE_HEADS),
                    semantic_declarations=declarations,
                )
                self.assertEqual(valid, [])
                self.assertEqual(len(rejected), 1)
                self.assertTrue(
                    any(
                        expected_input in reason
                        for reason in rejected[0].circular_inputs
                    )
                )
                self.assertFalse(
                    any(
                        expected_input in reason
                        for reason in rejected[0].conditional_inputs
                    )
                )

