    def test_duplicate_neutral_short_names_are_qualified_and_order_invariant(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            alpha = root / "Alpha.lean"
            beta = root / "Beta.lean"
            alpha.write_text(
                "namespace Alpha\n"
                "structure Quartz (n : Nat) where\n"
                "  first : Wins n = true\n"
                "structure Cargo (n : Nat) where\n"
                "  slot : Quartz n\n"
                "abbrev Pebble (n : Nat) := Quartz n\n"
                "theorem echo (n : Nat) : Wins n = true := by trivial\n"
                "end Alpha\n",
                encoding="utf-8",
            )
            beta.write_text(
                "namespace Beta\n"
                "structure Quartz (n : Nat) where\n"
                "  second : Eligible n\n"
                "abbrev Pebble (n : Nat) := Quartz n\n"
                "theorem echo (n : Nat) : Eligible n := by trivial\n"
                "end Beta\n",
                encoding="utf-8",
            )

            forward = AUDIT.parse_structures(root, [alpha, beta])
            reverse = AUDIT.parse_structures(root, [beta, alpha])
            self.assertEqual(set(forward), set(reverse))
            self.assertEqual(
                set(forward), {"Alpha.Quartz", "Alpha.Cargo", "Beta.Quartz"}
            )
            self.assertEqual(forward["Alpha.Quartz"].fields[0].field, "first")
            self.assertEqual(forward["Beta.Quartz"].fields[0].field, "second")
            self.assertEqual(
                AUDIT.mentioned_structures("Quartz n", set(forward)),
                ["Alpha.Quartz", "Beta.Quartz"],
            )
            self.assertEqual(
                AUDIT.mentioned_structures("Alpha.Quartz n", set(forward)),
                ["Alpha.Quartz"],
            )

            aliases_forward = AUDIT.parse_structure_aliases([alpha, beta], forward)
            aliases_reverse = AUDIT.parse_structure_aliases([beta, alpha], reverse)
            self.assertEqual(aliases_forward, aliases_reverse)
            self.assertEqual(
                aliases_forward,
                {
                    "Alpha.Pebble": "Alpha.Quartz",
                    "Beta.Pebble": "Beta.Quartz",
                },
            )

            local_forward = {
                declaration.name: declaration.source
                for declaration in AUDIT.parse_local_declarations(
                    root, [alpha, beta]
                )
            }
            local_reverse = {
                declaration.name: declaration.source
                for declaration in AUDIT.parse_local_declarations(
                    root, [beta, alpha]
                )
            }
            self.assertEqual(local_forward, local_reverse)
            self.assertIn("Alpha.echo", local_forward)
            self.assertIn("Beta.echo", local_forward)

