    def test_structure_resolution_uses_parent_namespace_and_visible_arity(self) -> None:
        """A short record head must not pull in an unrelated imported record."""

        candidates = {
            "KR21Monoculture.Model",
            "AppliedModelingLib.Probability.Exponential.Model",
        }
        parameter_counts = {
            "KR21Monoculture.Model": 1,
            "AppliedModelingLib.Probability.Exponential.Model": 0,
        }

        # Lean resolves `Model` inside `KR21Monoculture.PaperInterface` through
        # the parent namespace.  The imported exponential model is not a second
        # source-model premise merely because it shares a short name.
        self.assertEqual(
            AUDIT.mentioned_structures(
                "Model n",
                candidates,
                context_namespace="KR21Monoculture.PaperInterface",
                structure_parameter_counts=parameter_counts,
            ),
            ["KR21Monoculture.Model"],
        )

        # Even without a lexical namespace, a visibly applied one-parameter
        # type cannot denote the nullary imported record.
        self.assertEqual(
            AUDIT.mentioned_structures(
                "Model n",
                candidates,
                structure_parameter_counts=parameter_counts,
            ),
            ["KR21Monoculture.Model"],
        )

    def test_enclosing_namespace_precedes_root_name_and_suffixes_stay_ambiguous(
        self,
    ) -> None:
        """Relative Lean names search their namespace before the repository root."""

        declarations = {
            "Model": "structure Model where\n  count : Nat",
            "Alpha.Model": "structure Model where\n  proof : False",
            "Other.Model": "structure Model where\n  value : Nat",
        }
        self.assertEqual(
            AUDIT.resolve_declaration_reference(
                "Model",
                declarations,
                preferred_namespace="Alpha.PaperInterface",
            ),
            "Alpha.Model",
        )
        self.assertEqual(
            AUDIT.mentioned_structures(
                "Model",
                set(declarations),
                context_namespace="Alpha.PaperInterface",
            ),
            ["Alpha.Model"],
        )

        suffix_only = {
            "Alpha.Model": declarations["Alpha.Model"],
            "Other.Model": declarations["Other.Model"],
        }
        with self.assertRaisesRegex(ValueError, "ambiguous declaration reference"):
            AUDIT.resolve_declaration_reference("Model", suffix_only)
        self.assertEqual(
            AUDIT.mentioned_structures("Model", set(suffix_only)),
            ["Alpha.Model", "Other.Model"],
        )

