    def test_qualified_type_heads_do_not_cross_classify_namespace_collisions(self) -> None:
        """A data type in one namespace cannot suppress a Prop in another."""

        declarations = [
            local_declaration(
                "Alpha.Token",
                "abbrev Token : Type := Nat",
            ),
            local_declaration(
                "Beta.Token",
                "def Token : Prop := True",
            ),
        ]
        proposition_heads = AUDIT.proposition_type_heads(declarations)
        data_heads = AUDIT.data_type_heads(declarations)

        self.assertIn("Alpha.Token", data_heads)
        self.assertIn("Beta.Token", proposition_heads)
        self.assertNotIn("Token", data_heads)
        self.assertNotIn("Token", proposition_heads)
        self.assertTrue(
            AUDIT.is_definitely_data_type(
                "Alpha.Token", proposition_heads=proposition_heads, data_heads=data_heads
            )
        )
        self.assertTrue(AUDIT.is_proposition_type("Beta.Token", proposition_heads))
        self.assertFalse(
            AUDIT.is_definitely_data_type(
                "Beta.Token", proposition_heads=proposition_heads, data_heads=data_heads
            )
        )
        self.assertFalse(
            AUDIT.is_definitely_data_type(
                "Token", proposition_heads=proposition_heads, data_heads=data_heads
            )
        )
        self.assertEqual(
            AUDIT.boundary_input_kind(
                "row",
                {"names": "h", "type": "Beta.Token"},
                proposition_heads=proposition_heads,
                data_heads=data_heads,
            ),
            "semantic_proposition_premise",
        )
        self.assertEqual(
            AUDIT.boundary_input_kind(
                "row",
                {"names": "h", "type": "Token"},
                proposition_heads=proposition_heads,
                data_heads=data_heads,
            ),
            "semantic_unknown_nondata_premise",
        )

    def test_proposition_alias_chain_uses_parent_lexical_namespace(self) -> None:
        """A nested alias must resolve its parent before a duplicate suffix."""

        declarations = [
            local_declaration(
                "Alpha.Visible",
                "def Visible (n : Nat) : Prop := n = n",
            ),
            local_declaration(
                "Other.Visible",
                "def Visible (n : Nat) : Prop := Eligible n",
            ),
            local_declaration(
                "Alpha.Inner.Covered",
                "abbrev Covered (n : Nat) := Visible n",
            ),
        ]
        aliases = AUDIT.parse_proposition_aliases(declarations)
        scoped_aliases = AUDIT.proposition_aliases_in_namespace(
            aliases, "Alpha.Inner"
        )

        self.assertIn("Alpha.Inner.Covered", aliases)
        self.assertEqual(
            AUDIT.proposition_type_relation(
                "Covered candidate",
                "candidate = candidate",
                scoped_aliases,
            ),
            "equivalent",
        )
        resolved = AUDIT.resolve_local_declaration_head(
            "Visible", declarations, context_namespace="Alpha.Inner"
        )
        self.assertIsNotNone(resolved)
        assert resolved is not None
        self.assertEqual(resolved.name, "Alpha.Visible")
        references, ambiguous = AUDIT.semantic_model_local_term_references(
            "Visible candidate",
            declarations,
            context_namespace="Alpha.Inner",
        )
        self.assertEqual([reference.name for reference in references], ["Alpha.Visible"])
        self.assertEqual(ambiguous, [])

