    def test_reachable_auxiliary_requires_exact_source_map_support(self) -> None:
        """A neutral transitive helper needs an exact FQN source route.

        The fixture intentionally avoids source-looking declaration names. The
        enforcement comes from the selected proof/type dependency graph and
        the exact source-map identity, not a helper-name convention.
        """

        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            paper = root / "papers" / "Fixture"
            (paper / "audit").mkdir(parents=True)
            status = paper / "status.json"
            status.write_text(
                json.dumps({"review_surface": {}}), encoding="utf-8"
            )
            (paper / "audit" / "paper_statement_map.json").write_text(
                json.dumps(
                    {
                        "items": {
                            "source_primitive": {
                                "source_location": "source.txt:12",
                                "support_lean_declarations": [
                                    "Fixture.PaperInterface.Cedar"
                                ],
                            }
                        }
                    }
                ),
                encoding="utf-8",
            )
            selected = local_declaration(
                "Fixture.PaperInterface.Iris",
                "theorem Iris (x : Birch) : True := Cedar x",
            )
            bridge = local_declaration(
                "Fixture.PaperInterface.Cedar",
                "def Cedar (x : Birch) : True := True.intro",
            )
            auxiliary = local_declaration(
                "Fixture.PaperInterface.Birch",
                "structure Birch where\n  proof : True",
            )
            routing = AUDIT.reachable_paper_interface_auxiliary_routing(
                paper_dir=paper,
                status_path=status,
                interface_declarations={
                    selected.name: selected.source,
                    bridge.name: bridge.source,
                    auxiliary.name: auxiliary.source,
                },
                selected_qualified_names={selected.name},
                selected_row_names_by_qualified={selected.name: {"Iris"}},
                auxiliary_qualified_names={bridge.name, auxiliary.name},
                quarantined_auxiliary_qualified_names=set(),
                local_declarations=[selected, bridge, auxiliary],
                dependency_graphs_by_qualified={
                    selected.name: elaborated_dependency_manifest(
                        selected.name,
                        [
                            (selected.name, bridge.name, "proof_uses_constant"),
                            (bridge.name, auxiliary.name, "type_uses_constant"),
                        ],
                    )
                },
            )

            by_declaration = {
                item["declaration"]
                for item in routing[
                    "reachable_paper_interface_auxiliary_dependencies"
                ]
            }
            self.assertEqual(
                by_declaration,
                {
                    "Fixture.PaperInterface.Birch",
                    "Fixture.PaperInterface.Cedar",
                },
            )
            supported = next(
                item
                for item in routing[
                    "reachable_paper_interface_auxiliary_dependencies"
                ]
                if item["declaration"] == "Fixture.PaperInterface.Cedar"
            )
            self.assertEqual(
                supported["disposition"], "explicit_source_map_route_or_support"
            )
            self.assertEqual(
                supported["source_map_routes"][0]["route_field"],
                "support_lean_declarations",
            )
            # Birch is reached through the same selected root but lacks a
            # separate exact source route, so it remains a visible failure.
            self.assertEqual(
                [item["declaration"] for item in routing[
                    "unresolved_reachable_paper_interface_auxiliaries"
                ]],
                ["Fixture.PaperInterface.Birch"],
            )
            cedar_paths = supported["transitively_referenced_from"]
            self.assertEqual(
                cedar_paths[0]["dependency_chain"],
                [
                    "Fixture.PaperInterface.Iris",
                    "Fixture.PaperInterface.Cedar",
                ],
            )

