    def test_nested_duplicate_short_name_prefers_namespace_or_audits_all(self) -> None:
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            path = root / "Fixture.lean"
            path.write_text(
                "namespace Alpha\n"
                "structure Quartz where\n"
                "  first : Wins 0 = true\n"
                "structure Cargo where\n"
                "  slot : Quartz\n"
                "end Alpha\n"
                "namespace Beta\n"
                "structure Quartz where\n"
                "  second : Eligible 0\n"
                "end Beta\n"
                "namespace Gamma\n"
                "structure Cargo where\n"
                "  slot : Quartz\n"
                "end Gamma\n",
                encoding="utf-8",
            )
            structures = AUDIT.parse_structures(root, [path])
            candidates = set(structures)
            alpha_fields, alpha_failures = AUDIT.recursively_collect_fields(
                "Alpha.Cargo", structures, candidates, {}, 4
            )
            self.assertEqual(alpha_failures, [])
            self.assertIn("Alpha.Quartz.first", {field.path.split(" -> ")[-1] for field in alpha_fields})
            self.assertNotIn("Beta.Quartz.second", {field.path.split(" -> ")[-1] for field in alpha_fields})

            gamma_fields, gamma_failures = AUDIT.recursively_collect_fields(
                "Gamma.Cargo", structures, candidates, {}, 4
            )
            self.assertEqual(gamma_failures, [])
            gamma_paths = {field.path.split(" -> ")[-1] for field in gamma_fields}
            self.assertIn("Alpha.Quartz.first", gamma_paths)
            self.assertIn("Beta.Quartz.second", gamma_paths)

