    def test_transparent_execution_aliases_expand_before_record_classification(self) -> None:
        """A proposition-level run alias cannot hide transition proof fields.

        The two cases deliberately use unrelated declaration spellings.  The
        route is selected by exact lexical identity and expanded semantic type,
        rather than a name convention such as ``Run`` or ``Transition``.
        """

        for index, (kind, alias_name, record_name) in enumerate(
            (
                ("abbrev", "TransitEnvelope", "RoundCertificate"),
                ("def", "Parcel", "MoveWitness"),
            )
        ):
            with self.subTest(kind=kind, alias=alias_name, record=record_name):
                alias = local_declaration(
                    f"Fixture.{alias_name}",
                    f"{kind} {alias_name} (n start finish : Nat) : Prop := "
                    f"Relation.ReflTransGen ({record_name} n) start finish",
                )
                reviewed = local_declaration(
                    "Fixture.PaperInterface.endpoint",
                    f"theorem endpoint (n start finish : Nat) "
                    f"(payload : {alias_name} n start finish) : Goal n := by "
                    "exact source_proof",
                )
                field = fixture_field(record_name, "preserves", "Premise n")
                structures = {
                    record_name: AUDIT.StructureInfo(
                        record_name,
                        "papers/Fixture/Model.lean",
                        1,
                        [field],
                        ["n", "start", "finish"],
                    )
                }
                declarations = [alias, reviewed]
                proposition_aliases = AUDIT.parse_proposition_aliases(declarations)
                inputs = AUDIT.visible_inputs_from_declaration(reviewed.source)

                roots = AUDIT.mentioned_structures_in_delta_expanded_scoped_inputs(
                    inputs,
                    {record_name},
                    {},
                    proposition_aliases=proposition_aliases,
                    semantic_declarations=declarations,
                    context_namespace="Fixture.PaperInterface",
                )
                self.assertEqual(roots, [record_name])

                items = AUDIT.conclusion_dependency_items(
                    row_names=["endpoint"],
                    declarations={"endpoint": reviewed.source},
                    row_inputs={"endpoint": inputs},
                    row_records={"endpoint": roots},
                    fields_by_root={record_name: [field]},
                    local_declarations=declarations,
                    aliases={},
                    structures=structures,
                    proposition_heads={"Premise", "Goal"},
                    proposition_aliases=proposition_aliases,
                    data_heads=set(AUDIT.KNOWN_DATA_TYPE_HEADS),
                    semantic_declarations=declarations,
                    row_qualified_names={
                        "endpoint": "Fixture.PaperInterface.endpoint"
                    },
                )
                record_items = [
                    item
                    for item in items
                    if item["kind"] == "record_conclusion_input"
                ]
                self.assertEqual(len(record_items), 1)
                item = record_items[0]
                self.assertEqual(item["binder_type"], f"{alias_name} n start finish")
                self.assertEqual(item["original_binder_type"], item["binder_type"])
                self.assertIn("Relation.ReflTransGen", item["expanded_binder_type"])
                self.assertEqual(item["record"], record_name)
                self.assertEqual(
                    item["conclusion_fields"][0]["judgment_key"],
                    f"{record_name}.preserves",
                )
                self.assertEqual(
                    item["proposition_alias_expansion"]["transparent_steps"][0][
                        "declaration"
                    ],
                    f"Fixture.{alias_name}",
                )
                self.assertFalse(
                    any(
                        item["kind"] == "unexpanded_local_reducible_type_input"
                        for item in items
                    )
                )

