    def test_record_subtype_domain_predicate_remains_boundary_obligation(self) -> None:
        exact_profile = local_declaration(
            "ExactProfile",
            "abbrev ExactProfile (budget : Nat) := "
            "{ counts : Nat -> Nat // Total counts = budget }",
        )
        profile_field = fixture_field(
            "SearchResult", "profile", "ExactProfile budget"
        )
        result = AUDIT.StructureInfo(
            "SearchResult",
            "papers/Fixture/Search.lean",
            1,
            [fixture_field("SearchResult", "budget", "Nat"), profile_field],
        )
        reviewed = (
            "theorem endpoint (result : SearchResult) : "
            "Feasible result.profile := by exact proof"
        )
        items = AUDIT.conclusion_dependency_items(
            row_names=["endpoint"],
            declarations={"endpoint": reviewed},
            row_inputs={"endpoint": AUDIT.visible_inputs_from_declaration(reviewed)},
            row_records={"endpoint": ["SearchResult"]},
            fields_by_root={"SearchResult": result.fields},
            local_declarations=[exact_profile],
            aliases={},
            structures={"SearchResult": result},
            proposition_heads={"Feasible"},
            proposition_aliases={},
            # The carrier alias may legitimately be inferred as data. Its
            # stored predicate must still survive as a proof obligation.
            data_heads=set(AUDIT.KNOWN_DATA_TYPE_HEADS) | {"ExactProfile"},
            semantic_declarations=[exact_profile],
        )
        record_items = [
            item for item in items if item["kind"] == "record_conclusion_input"
        ]
        self.assertEqual(len(record_items), 1)
        field = record_items[0]["conclusion_fields"][0]
        self.assertEqual(field["judgment_key"], "SearchResult.profile")
        self.assertEqual(field["hidden_subtype_predicate"], "Total counts = budget")
        self.assertEqual(field["semantic_kind"], "proposition")
        self.assertEqual(field["relation_to_row_result"], "")
        self.assertTrue(field["source_antecedent_eligible"])

        resolved, unresolved = AUDIT.partition_conclusion_dependencies(
            record_items,
            {
                "SearchResult.profile": {
                    "classification": "nonpropositional_witness_data",
                    "source_location": "source.tex:42",
                }
            },
        )
        self.assertEqual(resolved, [])
        self.assertEqual(len(unresolved), 1)

        resolved, unresolved = AUDIT.partition_conclusion_dependencies(
            record_items,
            {
                "SearchResult.profile": {
                    "classification": "validated_source_assumption",
                    "source_location": "source.tex:42",
                }
            },
        )
        self.assertEqual(len(resolved), 1)
        self.assertEqual(unresolved, [])

    def test_unrelated_subtype_predicate_used_through_helpers_fails_closed(self) -> None:
        renamings = [
            ("Capsule", "Seeded", "Prepared", "Delivered"),
            ("Parcel", "Admissible", "Converted", "Published"),
        ]
        for index, (wrapper, premise, intermediate, goal) in enumerate(renamings):
            with self.subTest(wrapper=wrapper, premise=premise, goal=goal):
                hidden = local_declaration(
                    wrapper,
                    f"abbrev {wrapper} (source : Nat) := "
                    f"{{ value : Nat // {premise} source }}",
                )
                first_helper = local_declaration(
                    f"step{index}a",
                    f"theorem step{index}a (n : Nat) : {premise} n -> "
                    f"{intermediate} n := by exact helper_one",
                )
                second_helper = local_declaration(
                    f"step{index}b",
                    f"theorem step{index}b (n : Nat) : {intermediate} n -> "
                    f"{goal} n := by exact helper_two",
                )
                structure_name = f"Envelope{index}"
                payload = fixture_field(
                    structure_name, "payload", f"{wrapper} n"
                )
                envelope = AUDIT.StructureInfo(
                    structure_name,
                    "papers/Fixture/Envelope.lean",
                    1,
                    [payload],
                    ["n"],
                )
                reviewed = (
                    f"theorem endpoint (n : Nat) (result : {structure_name} n) : "
                    f"{goal} n := by exact step{index}b n "
                    f"(step{index}a n result.payload.property)"
                )
                items = AUDIT.conclusion_dependency_items(
                    row_names=["endpoint"],
                    declarations={"endpoint": reviewed},
                    row_inputs={
                        "endpoint": AUDIT.visible_inputs_from_declaration(reviewed)
                    },
                    row_records={"endpoint": [structure_name]},
                    fields_by_root={structure_name: envelope.fields},
                    local_declarations=[hidden, first_helper, second_helper],
                    aliases={},
                    structures={structure_name: envelope},
                    proposition_heads={premise, intermediate, goal},
                    proposition_aliases={},
                    data_heads=set(AUDIT.KNOWN_DATA_TYPE_HEADS),
                    semantic_declarations=[hidden, first_helper, second_helper],
                    elaborated_manifests_by_qualified={
                        "endpoint": elaborated_dependency_manifest(
                            "endpoint",
                            [
                                (
                                    "endpoint",
                                    first_helper.name,
                                    "proof_uses_constant",
                                ),
                                (
                                    "endpoint",
                                    second_helper.name,
                                    "proof_uses_constant",
                                ),
                            ],
                        )
                    },
                )
                record_items = [
                    item
                    for item in items
                    if item["kind"] == "record_conclusion_input"
                ]
                self.assertEqual(len(record_items), 1)
                field = record_items[0]["conclusion_fields"][0]
                self.assertEqual(field["hidden_subtype_predicate"], f"{premise} n")
                self.assertEqual(field["semantic_kind"], "proposition")
                self.assertEqual(field["relation_to_row_result"], "")
                self.assertTrue(field["source_antecedent_eligible"])

