    def test_transparent_ordered_pair_binder_expands_to_strict_domain(self) -> None:
        """A local strict-pair abbrev must expose its carrier and predicate."""

        ordered_pair = local_declaration(
            "Fixture.OrderedPair",
            "abbrev OrderedPair (n : Nat) := "
            "{ p : Fin n × Fin n // p.2.val < p.1.val }",
        )
        reviewed = (
            "theorem endpoint (n : Nat) (p : Fixture.OrderedPair n) : "
            "RateBound n := by exact proof"
        )
        row = "endpoint"
        qualified = "Fixture.PaperInterface.endpoint"
        items = AUDIT.conclusion_dependency_items(
            row_names=[row],
            declarations={row: reviewed},
            row_inputs={row: AUDIT.visible_inputs_from_declaration(reviewed)},
            row_records={row: []},
            fields_by_root={},
            local_declarations=[ordered_pair],
            aliases={},
            structures={},
            proposition_heads={"RateBound"},
            proposition_aliases={},
            data_heads=set(AUDIT.KNOWN_DATA_TYPE_HEADS),
            semantic_declarations=[ordered_pair],
            row_qualified_names={row: qualified},
            elaborated_manifests_by_qualified={
                qualified: elaborated_dependency_manifest(
                    qualified,
                    [(qualified, ordered_pair.name, "type_uses_constant")],
                )
            },
        )
        subtype_items = [
            item
            for item in items
            if item["kind"] == "transparent_subtype_domain_input"
            and item["binder"] == "p"
        ]
        self.assertEqual(len(subtype_items), 1)
        item = subtype_items[0]
        self.assertEqual(
            item["expanded_subtype_carrier_type"], "Fin n × Fin n"
        )
        self.assertEqual(
            item["expanded_subtype_predicate"], "p.2.val < p.1.val"
        )
        self.assertEqual(item["subtype_predicate_result_bridges"], [])
        self.assertTrue(item["subtype_domain_semantic_data_only"])
        # Only the exact source-map association can later turn this into
        # nonpropositional data; parser-level expansion alone cannot waive the
        # source's ordered high/low domain.
        self.assertFalse(item["domain_data_only"])

