    def closure_completion_fixture(
        self,
    ) -> tuple[
        dict[str, object],
        dict[str, dict[str, object]],
        dict[str, object],
        dict[str, object],
    ]:
        """Return one exact closure parent plus a separately source-bound use."""

        def sha(value: str) -> str:
            return hashlib.sha256(value.encode("utf-8")).hexdigest()
        declaration = "Fixture.PaperInterface.neutral"
        root = "Fixture.SourceCarrier"
        declaration_identity = {
            "qualified_declaration": declaration,
            "declaration_sha256": sha("declaration"),
        }
        signature = {
            "qualified_declaration": declaration,
            "elaborated_signature_sha256": sha("signature"),
        }
        source_semantic_sha = sha("source semantics")
        association = {
            "schema": 2,
            "association_origin": "explicit_source_map_direct_route",
            "role": "direct_source_route",
            "semantic_association_sha256": semantic_association_record_digest(
                [source_semantic_sha], signature
            ),
            "reviewed_declaration_identity": declaration_identity,
            "reviewed_elaborated_signature_identity": signature,
            "source_item_identities": [
                {
                    "source_key": "fixture_source",
                    "source_location": "source.tex:10-14",
                    "source_map_item_sha256": sha("map item"),
                    "source_semantic_sha256": source_semantic_sha,
                }
            ],
        }
        proof_key = f"{root}.law"
        data_key = f"{root}.scale"
        component_specs = {
            proof_key: (sha("proof component"), sha("proof structural")),
            data_key: (sha("data component"), sha("data structural")),
        }
        raw_fields: list[dict[str, object]] = []
        raw_components: list[dict[str, object]] = []
        for index, (field_key, (component_sha, structural_sha)) in enumerate(
            component_specs.items()
        ):
            raw_field: dict[str, object] = {
                "judgment_key": field_key,
                "structure": root,
                "nested_structures": [],
                "structural_type_sha256": structural_sha,
            }
            if field_key == data_key:
                raw_field.update(
                    {
                        "proposition_sort": "false",
                        "payload_safety": "structural_data",
                        "elaborated_field_safety_receipt": {
                            "status": "ok",
                            "value_sort": "false",
                            "payload_safety": "structural_data",
                        },
                    }
                )
            raw_fields.append(raw_field)
            raw_components.append(
                {
                    "judgment_key": f"component::{index}",
                    "source_judgment_key": field_key,
                    "source_component_section": "recursive_field_items",
                    "source_claim_component_sha256": component_sha,
                    "structural_type_sha256": structural_sha,
                }
            )
        semantic_key = "semantic-model::neutral"
        raw: dict[str, object] = {
            "expected_field_judgment_keys": [proof_key, data_key],
            "recursive_field_items": raw_fields,
            "theorem_realization_component_items": raw_components,
            "semantic_model_items": [
                {
                    "judgment_key": semantic_key,
                    "reviewed_declaration_identity": declaration_identity,
                    "reviewed_elaborated_signature_identities": [signature],
                    "source_statement_association": association,
                    "record_input_bindings": [
                        {"record_roots": [root], "binder_names": ["carrier"]}
                    ],
                }
            ],
        }
        candidate = CLOSURE.current_record_field_closure_completion_candidates(raw)[0]
        attestation = {
            "schema": CLOSURE.RECORD_FIELD_CLOSURE_COMPLETION_ATTESTATION_SCHEMA,
            "closure_sha256": candidate.closure_sha256,
            "verdict": CLOSURE.RECORD_FIELD_CLOSURE_COMPLETION_ATTESTATION_VERDICT,
            "source_location": "source.tex:10-14",
            "closure_semantics": "The source specifies this complete carrier.",
            "lean_evidence": "The generated closure contains every stored field.",
        }
        attestation_sha = CLOSURE.closure_attestation_sha256(attestation)
        judgments: dict[str, dict[str, object]] = {
            semantic_key: {
                "classification": "semantic_model_review",
                CLOSURE.RECORD_FIELD_CLOSURE_COMPLETION_ATTESTATIONS_FIELD: [
                    attestation
                ],
            }
        }
        for field_key, component_key, component_sha, structural_sha in (
            candidate.field_components
        ):
            judgments[field_key] = {
                # The exact receipt, not this reviewer label, grants closure
                # credit.
                "classification": "semantic_model_review",
                CLOSURE.RECORD_FIELD_CLOSURE_COMPLETION_RECEIPT_FIELD: {
                    "schema": CLOSURE.RECORD_FIELD_CLOSURE_COMPLETION_RECEIPT_SCHEMA,
                    "closure_sha256": candidate.closure_sha256,
                    "attestation_sha256": attestation_sha,
                    "semantic_model_judgment_key": semantic_key,
                    "component_sha256": component_sha,
                    "structural_type_sha256": structural_sha,
                },
            }

        parent: dict[str, object] = {
            "kind": "record_conclusion_input",
            "judgment_key": "anything.parent",
            "record": root,
            "binder": "carrier",
            "reviewed_declaration_identity": declaration_identity,
            "reviewed_elaborated_signature_identities": [signature],
            "conclusion_fields": [
                {
                    "judgment_key": proof_key,
                    "source_antecedent_eligible": True,
                    "relation_to_row_result": "",
                },
                {
                    "judgment_key": data_key,
                    "source_antecedent_eligible": False,
                    "relation_to_row_result": "component_of_target",
                },
            ],
            # Constructor diagnostics are not the source-credit route and do
            # not erase the independent exact closure receipt.
            "rejected_constructors": [{"declaration": "Fixture.notTheRoute"}],
            "conditional_constructors": [],
            "valid_constructors": [],
        }
        reused = deepcopy(parent)
        reused.update(
            {
                "judgment_key": "unrelated_spelling.source_input",
                "binder": "renamed",
                "reviewed_declaration_identity": {
                    "qualified_declaration": "Fixture.PaperInterface.other",
                    "declaration_sha256": sha("other declaration"),
                },
                "reviewed_elaborated_signature_identities": [
                    {
                        "qualified_declaration": "Fixture.PaperInterface.other",
                        "elaborated_signature_sha256": sha("other signature"),
                    }
                ],
            }
        )
        judgments[str(reused["judgment_key"])] = {
            "classification": "validated_source_assumption",
            "source_location": "source.tex:20",
        }
        return raw, judgments, parent, reused

    def test_exact_closure_receipts_resolve_parent_and_source_bound_reuse(self) -> None:
        raw, judgments, parent, reused = self.closure_completion_fixture()

        resolved, unresolved = AUDIT.partition_conclusion_dependencies(
            [parent, reused], judgments, raw_audit=raw
        )

        self.assertEqual(unresolved, [])
        self.assertEqual(
            [item["resolution"] for item in resolved],
            [
                "record_field_closure_completion_parent",
                "accepted_source_record_with_closure_completion",
            ],
        )

    def test_closure_receipts_fail_closed_on_mutation_or_unbound_reuse(self) -> None:
        raw, judgments, parent, reused = self.closure_completion_fixture()
        reused_key = str(reused["judgment_key"])

        without_occurrence_credit = deepcopy(judgments)
        without_occurrence_credit.pop(reused_key)
        resolved, unresolved = AUDIT.partition_conclusion_dependencies(
            [reused], without_occurrence_credit, raw_audit=raw
        )
        self.assertEqual(resolved, [])
        self.assertEqual(len(unresolved), 1)
        self.assertTrue(unresolved[0]["unresolved_fields"])

        mutated = deepcopy(judgments)
        field_key = next(
            key
            for key, judgment in mutated.items()
            if CLOSURE.RECORD_FIELD_CLOSURE_COMPLETION_RECEIPT_FIELD in judgment
        )
        mutated[field_key][CLOSURE.RECORD_FIELD_CLOSURE_COMPLETION_RECEIPT_FIELD][
            "component_sha256"
        ] = "0" * 64
        resolved, unresolved = AUDIT.partition_conclusion_dependencies(
            [parent, reused], mutated, raw_audit=raw
        )
        self.assertEqual(resolved, [])
        self.assertEqual(len(unresolved), 2)

