    def test_approved_convention_partition_matches_provenance_gate(self) -> None:
        direct_key = "paper_row.hmodel : SourceModelCondition x"
        field_key = "SourceModel.endpoint_calculus"
        direct = {
            "kind": "aliased_conclusion_bridge_input",
            "judgment_key": direct_key,
            "conclusion_fields": [],
            "valid_constructors": [],
            "conditional_constructors": [],
        }
        record = {
            "kind": "record_conclusion_input",
            "judgment_key": "paper_row.model : SourceModel x",
            "conclusion_fields": [
                {
                    "judgment_key": field_key,
                    "source_antecedent_eligible": True,
                    "relation_to_row_result": "",
                    "semantic_kind": "proposition",
                }
            ],
            "valid_constructors": [],
            "conditional_constructors": [],
        }
        judgments = {
            direct_key: {
                "classification": "approved_source_convention",
                "source_location": "source.tex:10",
            },
            field_key: {
                "classification": "approved_source_convention",
                "source_location": "source.tex:11",
            },
        }

        resolved, unresolved = AUDIT.partition_conclusion_dependencies(
            [direct, record],
            judgments,
            approved_source_convention_input_keys={direct_key},
            approved_source_convention_field_keys={field_key},
        )

        self.assertEqual(unresolved, [])
        self.assertEqual(
            [item["resolution"] for item in resolved],
            ["accepted_source_convention", "accepted_source_fields"],
        )
        self.assertTrue(
            GATE.conclusion_input_is_accepted_source_antecedent(
                direct,
                set(),
                set(),
                {direct_key},
            )
        )
        self.assertEqual(
            GATE.unresolved_dependency_field_keys(
                record,
                set(),
                set(),
                {field_key},
            ),
            (),
        )

        # A model convention cannot hide a field that itself carries the row's
        # advertised conclusion.
        result_field_record = {
            **record,
            "conclusion_fields": [
                {
                    **record["conclusion_fields"][0],
                    "relation_to_row_result": "component_of_target",
                }
            ],
        }
        self.assertEqual(
            GATE.unresolved_dependency_field_keys(
                result_field_record,
                set(),
                set(),
                {field_key},
            ),
            (field_key,),
        )

