    def test_quantified_and_function_data_are_not_proposition_fields(self) -> None:
        data_heads = set(AUDIT.KNOWN_DATA_TYPE_HEADS)
        proposition_heads = {"IsMarkovKernel", "Measurable"}
        for type_text in (
            "ℝ≥0",
            "Ω → ℝ≥0",
            "Kernel ℝ≥0 ℝ≥0",
            "∀ j : Fin (count + 1), Kernel (Fin j.1 → ℝ) ℝ",
        ):
            with self.subTest(type_text=type_text):
                self.assertFalse(
                    AUDIT.is_proposition_type(
                        type_text,
                        proposition_heads,
                        data_heads,
                    )
                )
                self.assertTrue(
                    AUDIT.is_definitely_data_type(
                        type_text,
                        proposition_heads=proposition_heads,
                        data_heads=data_heads,
                    )
                )

        # The structural distinction is terminal sort, not the quantified
        # syntax: these similarly shaped proof fields must remain propositions.
        for type_text in (
            "0 < rate",
            "∀ omega, f omega ≤ g omega",
            "Kernel ℝ≥0 ℝ≥0 = K",
            "∀ j, IsMarkovKernel (endpointResponse j)",
            "∀ t, Measurable (count t)",
        ):
            with self.subTest(type_text=type_text):
                self.assertTrue(
                    AUDIT.is_proposition_type(
                        type_text,
                        proposition_heads,
                        data_heads,
                    )
                )
                self.assertFalse(
                    AUDIT.is_definitely_data_type(
                        type_text,
                        proposition_heads=proposition_heads,
                        data_heads=data_heads,
                    )
                )

    def test_exact_source_input_only_exempts_local_reducible_wrapper(self) -> None:
        exact_keys = {"paper_row.h : SourcePredicate data"}
        data_keys = {"paper_row.center : Ranking n"}
        self.assertTrue(
            GATE.conclusion_input_is_exact_source_antecedent(
                {
                    "kind": "unexpanded_local_reducible_type_input",
                    "judgment_key": "paper_row.h : SourcePredicate data",
                },
                exact_keys,
            )
        )
        self.assertTrue(
            GATE.conclusion_input_is_accepted_source_antecedent(
                {
                    "kind": "unexpanded_local_reducible_type_input",
                    "judgment_key": "paper_row.center : Ranking n",
                },
                exact_keys,
                data_keys,
            )
        )
        self.assertFalse(
            GATE.conclusion_input_is_exact_source_antecedent(
                {
                    "kind": "unexpanded_local_reducible_type_input",
                    "judgment_key": "paper_row.center : Ranking n",
                },
                exact_keys,
            )
        )
        self.assertTrue(
            GATE.conclusion_input_is_exact_source_antecedent(
                {
                    "kind": "direct_conclusion_input",
                    "judgment_key": "paper_row.h : SourcePredicate data",
                },
                exact_keys,
            )
        )
        self.assertFalse(
            GATE.conclusion_input_is_exact_source_antecedent(
                {
                    "kind": "unexpanded_local_reducible_type_input",
                    "judgment_key": "paper_row.other : SourcePredicate data",
                },
                exact_keys,
            )
        )
        self.assertFalse(
            GATE.conclusion_input_is_exact_source_antecedent(
                {
                    "kind": "record_conclusion_input",
                    "judgment_key": "paper_row.pkg : Package data",
                    "conclusion_fields": [
                        {"judgment_key": "Package.hidden_conclusion"}
                    ],
                },
                {"paper_row.pkg : Package data", "Package.hidden_conclusion"},
            )
        )

