    def test_checked_projection_accepts_exact_static_contract(self) -> None:
        item = conditional_projection_item()
        target_key = str(item["judgment_key"])
        antecedent_key = "Fixture.SourceModel.primitive"
        judgments = {
            target_key: checked_projection_judgment(
                contract=exact_checked_projection_contract()
            ),
            antecedent_key: {
                "classification": "validated_source_assumption",
                "source_location": "source.tex:12",
            },
        }

        resolved, unresolved = AUDIT.partition_conclusion_dependencies([item], judgments)

        self.assertEqual(unresolved, [])
        self.assertEqual(resolved[0]["resolution"], "checked_projection")
        self.assertTrue(
            GATE.dependency_has_resolved_constructor(
                item, {antecedent_key}, judgments
            )
        )

    def test_checked_projection_rejects_name_only_derivation_and_bad_contracts(self) -> None:
        item = conditional_projection_item()
        target_key = str(item["judgment_key"])
        antecedent_key = "Fixture.SourceModel.primitive"
        source_judgment = {
            "classification": "validated_source_assumption",
            "source_location": "source.tex:12",
        }
        cases = {
            "name_only": (
                checked_projection_judgment(),
                {antecedent_key},
                "no checked_projection",
            ),
            "wrong_result": (
                checked_projection_judgment(
                    contract=exact_checked_projection_contract(result_type="OtherGoal C")
                ),
                {antecedent_key},
                "result type",
            ),
            "circular_constructor": (
                checked_projection_judgment(
                    contract=exact_checked_projection_contract(
                        declaration="Fixture.circularGoal"
                    )
                ),
                {antecedent_key},
                "rejected/circular",
            ),
            "unlisted_constructor": (
                checked_projection_judgment(
                    contract=exact_checked_projection_contract(
                        declaration="Fixture.unlistedGoal"
                    )
                ),
                {antecedent_key},
                "not in this conclusion input's static conditional-constructor list",
            ),
            "unvalidated_antecedent": (
                checked_projection_judgment(
                    contract=exact_checked_projection_contract()
                ),
                set(),
                "lack current validated_source_assumption",
            ),
        }
        for label, (judgment, exact_keys, expected_reason) in cases.items():
            with self.subTest(label=label):
                judgments = {target_key: judgment, antecedent_key: source_judgment}
                result = AUDIT.dependency_checked_projection_result(
                    item, exact_keys, judgments
                )

                self.assertFalse(result.accepted)
                self.assertIn(expected_reason, result.reason)
                self.assertFalse(
                    GATE.dependency_has_resolved_constructor(
                        item, exact_keys, judgments
                    )
                )

