    def test_type_valued_certificate_results_use_lean_productive_role(self) -> None:
        """Lexical witnesses on assumption-side do not become result packages."""

        parcel = AUDIT.StructureInfo(
            "Parcel",
            "papers/Fixture/Model.lean",
            1,
            [fixture_field("Parcel", "obligation", "Verified n")],
            ["n"],
        )
        other = AUDIT.StructureInfo(
            "Other",
            "papers/Fixture/Model.lean",
            5,
            [fixture_field("Other", "obligation", "Verified n")],
            ["n"],
        )
        rows = [
            "antecedent_only",
            "negated_only",
            "productive",
            "productive_iff",
            "mixed",
        ]
        qualified = {row: f"Fixture.{row}" for row in rows}

        def receipt(head: str, path: str) -> dict[str, object]:
            return {
                "path": path,
                "occurrence_role": "provided_result",
                "witness_type_head": f"Fixture.{head}",
                "payload_safety": "structural_data",
                "normalized_type_sha256": "a" * 64,
            }

        items = AUDIT.type_valued_certificate_result_items(
            row_names=rows,
            declarations={
                "antecedent_only": (
                    "theorem antecedent_only (n : Nat) : "
                    "(Nonempty (Parcel n) → Ready n) ∧ Ready n := by exact source"
                ),
                "negated_only": (
                    "theorem negated_only (n : Nat) : "
                    "¬ Nonempty (Parcel n) := by exact source"
                ),
                "productive": (
                    "theorem productive (n : Nat) : "
                    "Ready n → Nonempty (Parcel n) := by exact source"
                ),
                "productive_iff": (
                    "theorem productive_iff (n : Nat) : "
                    "Ready n ↔ Nonempty (Parcel n) := by exact source"
                ),
                "mixed": (
                    "theorem mixed (n : Nat) : "
                    "(¬ Nonempty (Parcel n)) ∧ Nonempty (Other n) := by exact source"
                ),
            },
            structures={"Parcel": parcel, "Other": other},
            aliases={},
            proposition_heads={"Ready", "Verified"},
            row_qualified_names=qualified,
            elaborated_type_witness_receipts={
                "Fixture.antecedent_only": [],
                "Fixture.negated_only": [],
                "Fixture.productive": [
                    receipt("Parcel", "result/nonempty")
                ],
                "Fixture.productive_iff": [
                    receipt("Parcel", "result/right/nonempty")
                ],
                # The source parser sees both record names. The exact Lean
                # witness head permits only the record produced by the result.
                "Fixture.mixed": [
                    receipt("Other", "result/prop_argument_1/nonempty")
                ],
            },
        )

        self.assertEqual(
            [(item["row"], item["record"]) for item in items],
            [
                ("mixed", "Other"),
                ("productive", "Parcel"),
                ("productive_iff", "Parcel"),
            ],
        )
        for item in items:
            self.assertEqual(item["result_occurrence_role"], "provided_result")
            self.assertTrue(item["elaborated_witness_paths"])

