    def test_source_coverage_rejects_type_certificate_wrapper_but_allows_support(self) -> None:
        payload = {
            "prompt_version": REPO.REQUIRED_SOURCE_RECORD_PROMPT_VERSION,
            "source_record_audit_sha256": "digest",
            "import_module": "Fixture.PaperInterface",
            "recursive_field_count": 0,
            "boundary_input_count": 0,
            "rows_with_record_premises": [],
            "conclusion_dependency_items": [],
            "type_valued_certificate_result_items": [
                {
                    "row": "opaque_package",
                    "qualified_declaration": "Fixture.opaque_package",
                    "result_wrapper": "nonempty_type_witness",
                    "record": "RenamedPacket",
                    "proposition_fields": [
                        {
                            "path": "RenamedPacket.valid",
                            "type": "Goal n",
                        }
                    ],
                },
                {
                    "row": "inductive_package",
                    "qualified_declaration": "Fixture.inductive_package",
                    "result_wrapper": "proposition_wrapper_type_witness",
                    "proposition_wrapper": "NeutralClaim",
                    "record": "NeutralPacket",
                    "proposition_fields": [
                        {
                            "path": "NeutralPacket.satisfies",
                            "type": "Goal n",
                        }
                    ],
                },
            ],
        }
        direct_map = {
            "items": {
                "named_source_result": {
                    "source_kind": "theorem",
                    "proof_lean_declarations": ["Fixture.opaque_package"],
                },
                "wrapped_source_result": {
                    "source_kind": "claim",
                    "proof_lean_declarations": ["Fixture.inductive_package"],
                },
            }
        }
        direct_findings = self._check_source_record_fixture(
            payload, {}, statement_map=direct_map
        )
        self.assertTrue(
            any(
                "Type-valued certificate" in finding.message
                and "named_source_result" in finding.message
                and "wrapped_source_result" in finding.message
                and "RenamedPacket.valid" in finding.message
                and "NeutralPacket.satisfies" in finding.message
                for finding in direct_findings
            )
        )

        support_only_map = {
            "items": {
                "named_source_result": {
                    "source_kind": "theorem",
                    "proof_lean_declarations": ["Fixture.visible_goal"],
                    "support_lean_declarations": ["Fixture.opaque_package"],
                }
            }
        }
        support_findings = self._check_source_record_fixture(
            payload, {}, statement_map=support_only_map
        )
        self.assertFalse(
            any(
                "Type-valued certificate" in finding.message
                for finding in support_findings
            )
        )

        contract_evidence_map = {
            "items": {
                "contract_source_result": {
                    "source_kind": "theorem",
                    "lean_declarations": ["Fixture.visible_goal"],
                    "semantic_contract": {
                        "evidence_declaration": "Fixture.opaque_package",
                    },
                }
            }
        }
        contract_evidence_findings = self._check_source_record_fixture(
            payload, {}, statement_map=contract_evidence_map
        )
        self.assertTrue(
            any(
                "Type-valued certificate" in finding.message
                and "contract_source_result" in finding.message
                and "RenamedPacket.valid" in finding.message
                for finding in contract_evidence_findings
            )
        )

