    def test_cache_reuses_only_direct_administrative_source_status_edits(self) -> None:
        """A current v8 receipt can skip scans only for bookkeeping-only drift."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper_dir = root / "papers" / "Fixture"
            audit_dir = paper_dir / "audit"
            audit_dir.mkdir(parents=True)
            (paper_dir / "PaperInterface.lean").write_text(
                "namespace Fixture\nend Fixture\n", encoding="utf-8"
            )
            (paper_dir / "status.json").write_text(
                json.dumps(
                    {
                        "status": "formalized",
                        "review_surface": {
                            "source_file": "papers/Fixture/PaperInterface.lean"
                        },
                    }
                ),
                encoding="utf-8",
            )
            map_path = audit_dir / "paper_statement_map.json"
            source_item = {
                "source_kind": "theorem",
                "title": "Theorem 1.",
                "statement": "Every admissible input has a witness.",
                "source_status": "under_review",
                "source_note": "The theorem uses the finite source model.",
                "lean_declarations": ["Fixture.PaperInterface.endpoint"],
                "corrected_target": {
                    "statement": "Every finite admissible input has a witness.",
                    "approval_id": "FIXTURE-CORRECTION",
                },
                "source_model": {"carrier": "finite"},
            }

            def write_map(item: dict[str, object]) -> tuple[str, str]:
                map_path.write_text(
                    json.dumps(
                        {
                            "source_coverage_mode": "named_theoretical_statements",
                            "items": {"opaque_source_item": item},
                        },
                        sort_keys=True,
                    ),
                    encoding="utf-8",
                )
                return AUDIT.paper_statement_map_cache_receipts(paper_dir)

            original_full, original_semantic = write_map(source_item)
            identity_args = SimpleNamespace(
                paper="Fixture", max_depth=4, no_lean=False
            )
            fingerprint = AUDIT.source_record_input_fingerprint(
                identity_args,
                root,
                paper_dir,
                paper_statement_map_sha256=original_full,
                paper_statement_map_semantic_sha256=original_semantic,
            )
            assert fingerprint is not None
            self.assertEqual(fingerprint["schema"], 10)
            payload: dict[str, object] = {
                "paper": "Fixture",
                "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
                "source_record_input_fingerprint": fingerprint,
                # This is intentionally the historical full byte receipt.  It
                # must remain available as provenance even when only the
                # administrative status has subsequently changed.
                "paper_statement_map_sha256": original_full,
            }
            self._complete_successful_scan(payload)
            stamp_source_record_audit_receipts(payload)
            (audit_dir / "source_record_audit.json").write_text(
                json.dumps(payload), encoding="utf-8"
            )
            reusable_args = SimpleNamespace(
                paper="Fixture",
                max_depth=4,
                no_lean=False,
                force=False,
                refresh_judgment_summary=False,
                ignore_current_judgments=False,
            )

            administrative_item = deepcopy(source_item)
            administrative_item["source_status"] = "resolved"
            administrative_full, administrative_semantic = write_map(
                administrative_item
            )
            self.assertNotEqual(administrative_full, original_full)
            self.assertEqual(administrative_semantic, original_semantic)
            with patch.object(
                AUDIT,
                "refresh_existing_judgment_summary",
                return_value={"reused": True},
            ) as refresh:
                self.assertEqual(
                    AUDIT.reusable_source_record_audit(
                        reusable_args,
                        root,
                        paper_dir,
                        paper_statement_map_sha256=administrative_full,
                        paper_statement_map_semantic_sha256=administrative_semantic,
                    ),
                    {"reused": True},
                )
                self.assertEqual(refresh.call_count, 1)
                self.assertEqual(
                    refresh.call_args.kwargs["paper_statement_map_sha256"],
                    administrative_full,
                )
                self.assertEqual(
                    refresh.call_args.kwargs["paper_statement_map_semantic_sha256"],
                    administrative_semantic,
                )

            for label, mutate in (
                (
                    "source note",
                    lambda item: item.update(
                        {"source_note": "The theorem uses a different model."}
                    ),
                ),
                (
                    "source route",
                    lambda item: item.update(
                        {
                            "lean_declarations": [
                                "Fixture.PaperInterface.repaired_endpoint"
                            ]
                        }
                    ),
                ),
                (
                    "corrected target",
                    lambda item: item["corrected_target"].update(  # type: ignore[index]
                        {"statement": "Every finite input has a repaired witness."}
                    ),
                ),
                (
                    "nested source-model field",
                    lambda item: item["source_model"].update(  # type: ignore[index]
                        {"carrier": "countably_infinite"}
                    ),
                ),
                (
                    "legacy phrase-only convention route",
                    lambda item: item.update(
                        {"source_status": "documented source model convention"}
                    ),
                ),
                (
                    "support-only route",
                    lambda item: item.update({"source_status": "support_only"}),
                ),
                (
                    "quarantined source defect",
                    lambda item: item.update(
                        {"source_status": "quarantined_source_defect"}
                    ),
                ),
            ):
                with self.subTest(change=label):
                    changed_item = deepcopy(source_item)
                    mutate(changed_item)
                    changed_full, changed_semantic = write_map(changed_item)
                    self.assertNotEqual(changed_semantic, original_semantic)
                    with patch.object(
                        AUDIT,
                        "refresh_existing_judgment_summary",
                    ) as refresh:
                        self.assertIsNone(
                            AUDIT.reusable_source_record_audit(
                                reusable_args,
                                root,
                                paper_dir,
                                paper_statement_map_sha256=changed_full,
                                paper_statement_map_semantic_sha256=changed_semantic,
                            )
                        )
                        refresh.assert_not_called()

