class SourceRecordCacheIdentityBoundaryTests(unittest.TestCase):
    """Exercise the cheap cache identity boundary without a Lean scan."""

    def test_cache_ignores_nonproducer_files_and_rejects_surface_changes(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper_dir = root / "papers" / "Fixture"
            audit_dir = paper_dir / "audit"
            audit_dir.mkdir(parents=True)
            interface = paper_dir / "PaperInterface.lean"
            dependency = paper_dir / "Dependency.lean"
            source_artifact = paper_dir / "source.tex"
            map_path = audit_dir / "paper_statement_map.json"
            status_path = paper_dir / "status.json"
            interface_original = (
                "import Fixture.Dependency\n"
                "namespace Fixture\n"
                "theorem reviewed : True := by trivial\n"
                "end Fixture\n"
            )
            dependency_original = (
                "namespace Fixture\n"
                "def dependencyValue : Nat := 1\n"
                "end Fixture\n"
            )
            source_original = "Theorem 1. Every input has a witness.\n"
            interface.write_text(interface_original, encoding="utf-8")
            dependency.write_text(dependency_original, encoding="utf-8")
            source_artifact.write_text(source_original, encoding="utf-8")

            def write_status(*, include_names: list[str] | None = None) -> None:
                status_path.write_text(
                    json.dumps(
                        {
                            "status": "formalized",
                            "review_surface": {
                                "source_file": "papers/Fixture/PaperInterface.lean",
                                "include_names": include_names or [],
                            },
                        },
                        sort_keys=True,
                    ),
                    encoding="utf-8",
                )

            def write_map(statement: str) -> tuple[str, str]:
                map_path.write_text(
                    json.dumps(
                        {
                            "source_artifact_path": "source.tex",
                            "source_artifact_sha256": hashlib.sha256(
                                source_artifact.read_bytes()
                            ).hexdigest(),
                            "items": {
                                "opaque_source_item": {
                                    "source_kind": "theorem",
                                    "statement": statement,
                                }
                            },
                        },
                        sort_keys=True,
                    ),
                    encoding="utf-8",
                )
                return AUDIT.paper_statement_map_cache_receipts(paper_dir)

            def identity() -> tuple[dict[str, object], str, str]:
                full, semantic = AUDIT.paper_statement_map_cache_receipts(paper_dir)
                fingerprint = AUDIT.source_record_input_fingerprint(
                    SimpleNamespace(paper="Fixture", max_depth=4, no_lean=False),
                    root,
                    paper_dir,
                    paper_statement_map_sha256=full,
                    paper_statement_map_semantic_sha256=semantic,
                )
                assert fingerprint is not None
                return fingerprint, full, semantic

            write_status()
            write_map("Every input has a witness.")
            nonproducer_paths = (
                "scripts/audit_evidence_integrity.py",
                "scripts/audit_repository.py",
                "scripts/review_dashboard.py",
                "scripts/refresh_validation_report_audit_summaries.py",
                "docs/FORMALIZATION.md",
                "audit/diagnostic.json",
            )
            for relative in nonproducer_paths:
                path = root / relative
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text("before\n", encoding="utf-8")

            baseline, full, semantic = identity()
            payload: dict[str, object] = {
                "paper": "Fixture",
                "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
                "source_record_input_fingerprint": baseline,
                "paper_statement_map_sha256": full,
            }
            SourceRecordRawIntegrityCacheTests._complete_successful_scan(payload)
            stamp_source_record_audit_receipts(payload)
            (audit_dir / "source_record_audit.json").write_text(
                json.dumps(payload), encoding="utf-8"
            )
            reusable_args = SimpleNamespace(
                paper="Fixture",
                max_depth=4,
                no_lean=False,
                force=False,
                refresh_judgment_summary=False,
                ignore_current_judgments=False,
            )

            # These files can affect validation/reporting/migration workflow,
            # but none is a byte-hashed raw-surface input.  An obligation
            # producer change is instead made explicit below via its version.
            for relative in nonproducer_paths:
                (root / relative).write_text("after\n", encoding="utf-8")
            self.assertEqual(identity()[0], baseline)
            with patch.object(
                AUDIT,
                "refresh_existing_judgment_summary",
                return_value={"reused": True},
            ) as refresh:
                self.assertEqual(
                    AUDIT.reusable_source_record_audit(
                        reusable_args,
                        root,
                        paper_dir,
                        paper_statement_map_sha256=full,
                        paper_statement_map_semantic_sha256=semantic,
                    ),
                    {"reused": True},
                )
                refresh.assert_called_once()

            def assert_cache_rejects_current_surface(label: str) -> None:
                current_full, current_semantic = (
                    AUDIT.paper_statement_map_cache_receipts(paper_dir)
                )
                with self.subTest(surface_change=label), patch.object(
                    AUDIT, "refresh_existing_judgment_summary"
                ) as refresh:
                    self.assertIsNone(
                        AUDIT.reusable_source_record_audit(
                            reusable_args,
                            root,
                            paper_dir,
                            paper_statement_map_sha256=current_full,
                            paper_statement_map_semantic_sha256=current_semantic,
                        )
                    )
                    refresh.assert_not_called()

            interface.write_text(interface_original + "-- changed surface\n", encoding="utf-8")
            assert_cache_rejects_current_surface("review interface")
            interface.write_text(interface_original, encoding="utf-8")

            dependency.write_text(
                dependency_original + "-- changed dependency\n", encoding="utf-8"
            )
            assert_cache_rejects_current_surface("imported Lean dependency")
            dependency.write_text(dependency_original, encoding="utf-8")

            source_artifact.write_text(
                "Theorem 1. Every input has a changed witness.\n", encoding="utf-8"
            )
            assert_cache_rejects_current_surface("source artifact")
            source_artifact.write_text(source_original, encoding="utf-8")

            write_status(include_names=["new_configured_review_row"])
            assert_cache_rejects_current_surface("review configuration")
            write_status()

            write_map("Every input has a changed witness.")
            assert_cache_rejects_current_surface("source-map semantic content")
            write_map("Every input has a witness.")

            with patch.dict(
                AUDIT.SOURCE_RECORD_SURFACE_ENGINE_VERSIONS,
                {"scripts/source_named_result_index.py": "source-named-result-selection-v2"},
            ):
                assert_cache_rejects_current_surface("explicit producer version")


class RepositoryRawAuditReuseTests(unittest.TestCase):
    """The repository gate reuses only an identity-validated canonical raw audit."""

    @staticmethod
    def _write_current_raw_audit(root: Path) -> tuple[Path, dict[str, object]]:
        folder = root / "papers" / "Fixture"
        audit = folder / "audit"
        audit.mkdir(parents=True)
        (audit / "paper_statement_map.json").write_text("{}\n", encoding="utf-8")
        payload: dict[str, object] = {
            "paper": "Fixture",
            "prompt_version": REPO.REQUIRED_SOURCE_RECORD_PROMPT_VERSION,
            "source_record_input_fingerprint": {"max_depth": 4, "no_lean": False},
            "paper_statement_map_sha256": "a" * 64,
            "semantic_model_items": [],
        }
        stamp_source_record_audit_receipts(payload)
        (audit / "source_record_audit.json").write_text(
            json.dumps(payload), encoding="utf-8"
        )
        return folder, payload

    def test_repository_reuses_identity_validated_canonical_raw_audit(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            _folder, payload = self._write_current_raw_audit(root)
            old_papers = REPO.PAPERS
            try:
                REPO.PAPERS = root / "papers"
                with (
                    patch.object(
                        REPO, "source_record_audit_identity_error", return_value=""
                    ) as identity,
                    patch.object(REPO.subprocess, "run") as scan,
                ):
                    result, error = REPO.run_source_record_audit_helper("Fixture")
            finally:
                REPO.PAPERS = old_papers

        self.assertEqual(error, "")
        self.assertEqual(result, payload)
        identity.assert_called_once()
        scan.assert_not_called()

    def test_stale_canonical_raw_audit_falls_back_to_full_scan(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            self._write_current_raw_audit(root)
            old_papers = REPO.PAPERS
            try:
                REPO.PAPERS = root / "papers"

                def full_scan(command: list[str], **_kwargs: object) -> subprocess.CompletedProcess[str]:
                    output_path = Path(command[command.index("--out") + 1])
                    output_path.write_text('{"fresh": true}', encoding="utf-8")
                    return subprocess.CompletedProcess(command, 0, "")

                with (
                    patch.object(
                        REPO,
                        "source_record_audit_identity_error",
                        return_value="source_record_input_fingerprint is stale",
                    ),
                    patch.object(REPO.subprocess, "run", side_effect=full_scan) as scan,
                ):
                    result, error = REPO.run_source_record_audit_helper("Fixture")
            finally:
                REPO.PAPERS = old_papers

        self.assertEqual(error, "")
        self.assertEqual(result, {"fresh": True})
        scan.assert_called_once()

    def test_identity_gate_checks_tampered_canonical_raw_audit_once(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            folder, payload = self._write_current_raw_audit(root)
            payload["semantic_model_items"] = [{"tampered": True}]
            (folder / "audit" / "source_record_audit.json").write_text(
                json.dumps(payload), encoding="utf-8"
            )
            old_papers = REPO.PAPERS
            try:
                REPO.PAPERS = root / "papers"
                with patch.object(
                    REPO,
                    "source_record_audit_identity_error",
                    side_effect=lambda candidate, **_kwargs: (
                        source_record_audit_receipt_error(candidate)
                    ),
                ) as identity:
                    result = REPO.current_saved_source_record_audit("Fixture")
            finally:
                REPO.PAPERS = old_papers

        self.assertIsNone(result)
        identity.assert_called_once()


class SourceRecordScanCompletenessTests(unittest.TestCase):
    """Current v10 evidence requires a completed generator scan, not JSON shape."""

    @staticmethod
    def valid_payload() -> dict[str, object]:
        source_file = "papers/Fixture/PaperInterface.lean"
        source_sha256 = "a" * 64
        fresh = {
            "mode": "isolated_temp_overlay",
            "returncode": 0,
            "source_file": source_file,
            "source_sha256": source_sha256,
        }
        selected = {
            "row": "fixture_row",
            "qualified_declaration": "Fixture.PaperInterface.fixture_row",
        }
        return {
            "source_record_input_fingerprint": {"max_depth": 4, "no_lean": False},
            "missing_configured_review_rows": [],
            "configured_review_rows": [{}],
            "configured_review_rows_count": 1,
            "configured_review_row_count": 1,
            "review_row_count": 1,
            "recursive_field_count": 0,
            "recursion_failures": [],
            "recursion_failure_count": 0,
            "constructor_result_type_check_error": "",
            "source_premise_consistency_schema": 1,
            "source_premise_consistency_error": "",
            "source_premise_consistency_items": [],
            "source_premise_consistency_item_count": 0,
            "review_interface_source": {
                "path": source_file,
                "sha256": source_sha256,
            },
            "fresh_source_elaboration": dict(fresh),
            "lean_check": {
                "returncode": 0,
                "requested_checked_rows": [dict(selected)],
                "checked_rows": [dict(selected)],
                "fresh_source_elaboration": dict(fresh),
            },
        }

    def test_fast_gate_rejects_incomplete_or_mismatched_scan_metadata(self) -> None:
        cases = {
            "no_lean": lambda payload: payload["source_record_input_fingerprint"].update(  # type: ignore[index,union-attr]
                {"no_lean": True}
            ),
            "failed_lean": lambda payload: payload["lean_check"].update(  # type: ignore[index,union-attr]
                {"returncode": 1}
            ),
            "recursion": lambda payload: payload.update(
                {"recursion_failures": [{"kind": "depth"}], "recursion_failure_count": 1}
            ),
            "constructor": lambda payload: payload.update(
                {"constructor_result_type_check_error": "incompatible constructor"}
            ),
            "source_premise": lambda payload: payload.update(
                {"source_premise_consistency_error": "Lean query failed"}
            ),
            "configured_count": lambda payload: payload.update(
                {"configured_review_rows_count": 2}
            ),
            "configured_rows": lambda payload: payload.update(
                {"configured_review_rows": "not a list"}
            ),
            "missing_rows": lambda payload: payload.update(
                {"missing_configured_review_rows": ["missing_source_row"]}
            ),
        }
        for label, mutate in cases.items():
            with self.subTest(label=label):
                payload = self.valid_payload()
                mutate(payload)
                self.assertTrue(
                    EVIDENCE.source_record_raw_scan_completeness_error(payload),
                    label,
                )

    def test_aggregate_only_items_never_supply_stale_item_freshness(self) -> None:
        """Only generated eligible:true items may feed every narrow-digest map."""

        key = "fixture.row : SourceCondition"
        clean_aggregate_only = {
            "judgment_key": key,
            "kind": "semantic_proposition_premise",
            "source_record_item_reuse_eligibility": {
                "eligible": False,
                "blockers": ["no source-content semantic identity"],
            },
        }
        payload = {"boundary_input_items": [clean_aggregate_only]}
        self.assertEqual(
            reusable_item_metadata_error(
                clean_aggregate_only,
                expected_item_digest_schema=REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            ),
            "",
        )
        self.assertNotIn(key, AUDIT.current_item_digests(payload))
        self.assertNotIn(key, EVIDENCE.source_record_required_item_digests(payload))
        self.assertNotIn(key, REPO.source_record_expected_item_digests(payload))
        self.assertNotIn(key, REPO.source_record_expected_item_digest_pins(payload))
        self.assertNotIn(key, GATE.current_item_digests(payload))
        self.assertNotIn(key, GATE.current_item_digest_pins(payload))
        self.assertFalse(
            REPO.source_record_judgment_current(
                key,
                {
                    "source_record_audit_sha256": "old-aggregate",
                    "source_record_item_digest_schema": REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
                    "source_record_item_sha256": "a" * 64,
                },
                digest="new-aggregate",
                expected_item_digests=REPO.source_record_expected_item_digests(payload),
                expected_item_digest_pins=REPO.source_record_expected_item_digest_pins(
                    payload
                ),
            )
        )

        malformed = {
            **clean_aggregate_only,
            "source_record_item_sha256": "a" * 64,
        }
        self.assertIn(
            "retaining item-level metadata",
            reusable_item_metadata_error(
                malformed,
                expected_item_digest_schema=REPO.SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            ),
        )


