    def test_identity_only_cli_reports_one_pass_reissue_hint(self) -> None:
        """The standalone evidence helper must not invite a retry loop."""

        def missing_closure(
            _args: argparse.Namespace,
            _root: Path,
            *,
            failure_reason: list[str] | None = None,
        ) -> None:
            assert failure_reason is not None
            failure_reason.append(
                "could not replay current Lean import closure: "
                "saved raw audit has no current Lean import-closure receipt"
            )
            return None

        stderr = io.StringIO()
        with (
            patch.object(
                AUDIT,
                "source_record_identity_only_payload",
                side_effect=missing_closure,
            ),
            patch.object(
                sys,
                "argv",
                [
                    "source_record_audit.py",
                    "--paper",
                    "Fixture",
                    "--root",
                    ".",
                    "--identity-only",
                ],
            ),
            redirect_stderr(stderr),
        ):
            self.assertEqual(AUDIT.main(), 2)

        text = stderr.getvalue()
        self.assertIn("saved raw audit has no current Lean import-closure receipt", text)
        self.assertIn("run one current source-record reissue", text)

