    def test_identity_rechecks_repo_external_declared_anchor_artifact(self) -> None:
        """A map-routed source outside the paper tree is rechecked after edit."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper = root / "papers" / "Fixture"
            audit_dir = paper / "audit"
            audit_dir.mkdir(parents=True)
            helper = (
                root
                / "skills"
                / "econcs-formalizer"
                / "scripts"
                / "source_record_audit.py"
            )
            helper.parent.mkdir(parents=True)
            helper.write_text("# fixture\n", encoding="utf-8")
            (paper / "status.json").write_text("{}\n", encoding="utf-8")
            external = root / "sources" / "shared.txt"
            external.parent.mkdir(parents=True)
            external.write_text("first source version\n", encoding="utf-8")
            statement_map = {
                "items": {
                    # The arbitrary row key is routing metadata, never the
                    # artifact identity used by this test.
                    "renamable-row": {
                        "source_anchor_evidence": [
                            {"path": "sources/shared.txt", "line_start": 1}
                        ]
                    }
                }
            }
            map_path = audit_dir / "paper_statement_map.json"
            map_path.write_text(json.dumps(statement_map), encoding="utf-8")
            map_sha256 = hashlib.sha256(map_path.read_bytes()).hexdigest()

            def fingerprint(source_sha256: str) -> dict[str, object]:
                return {
                    "schema": 10,
                    "paper": "Fixture",
                    "max_depth": 4,
                    "no_lean": False,
                    "source_artifact_identities": [
                        {
                            "path": "sources/shared.txt",
                            "sha256": source_sha256,
                            "status": "present",
                        }
                    ],
                }

            old_sha256 = hashlib.sha256(external.read_bytes()).hexdigest()
            stored = fingerprint(old_sha256)
            raw = {
                "source_record_input_fingerprint": stored,
                "paper_statement_map_sha256": map_sha256,
            }
            old_identity = {
                "paper": "Fixture",
                "paper_statement_map_sha256": map_sha256,
                "source_record_input_fingerprint": stored,
            }
            previous_root = EVIDENCE.ROOT
            EVIDENCE.ROOT = root
            self.addCleanup(setattr, EVIDENCE, "ROOT", previous_root)

            def helper_result(identity: dict[str, object]) -> SimpleNamespace:
                return SimpleNamespace(
                    returncode=0, stdout=json.dumps(identity), stderr=""
                )

            with (
                patch.object(
                    EVIDENCE.subprocess,
                    "run",
                    side_effect=[
                        helper_result(old_identity),
                        helper_result(old_identity),
                        helper_result(
                            {
                                **old_identity,
                                "source_record_input_fingerprint": fingerprint(
                                    hashlib.sha256(
                                        b"second source version\n"
                                    ).hexdigest()
                                ),
                            }
                        ),
                    ],
                ) as run,
            ):
                self.assertEqual(
                    EVIDENCE.source_record_current_input_fingerprint_error(paper, raw),
                    "",
                )
                self.assertEqual(
                    EVIDENCE.source_record_current_input_fingerprint_error(paper, raw),
                    "",
                )
                self.assertEqual(run.call_count, 2)

                external.write_text("second source version\n", encoding="utf-8")
                error = EVIDENCE.source_record_current_input_fingerprint_error(
                    paper, raw
                )

            self.assertEqual(run.call_count, 3)
            self.assertIn("source_record_input_fingerprint is stale", error)

    def test_identity_watch_resolves_structured_status_and_map_artifacts(self) -> None:
        """Every schema-owned source path is watched independent of row names."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper = root / "papers" / "Fixture"
            audit_dir = paper / "audit"
            audit_dir.mkdir(parents=True)
            status_paths = {
                "source_file": "shared/PaperInterface.lean",
                "human_source_file": "shared/HumanReview.lean",
                "assumption_source_file": "shared/Assumptions.lean",
            }
            (paper / "status.json").write_text(
                json.dumps({"review_surface": status_paths}), encoding="utf-8"
            )
            map_paths = {
                "source": "shared/source.txt",
                "canonical": "shared/canonical.txt",
                "anchor": "shared/anchor.txt",
            }
            (audit_dir / "paper_statement_map.json").write_text(
                json.dumps(
                    {
                        "source_artifact_path": map_paths["source"],
                        "items": {
                            "arbitrary-row-key": {
                                "canonical_source_artifact_path": map_paths[
                                    "canonical"
                                ],
                                "source_anchor_evidence": [
                                    {"path": map_paths["anchor"]}
                                ],
                            }
                        },
                    }
                ),
                encoding="utf-8",
            )
            for relative in (*status_paths.values(), *map_paths.values()):
                path = root / relative
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(relative + "\n", encoding="utf-8")
            previous_root = EVIDENCE.ROOT
            EVIDENCE.ROOT = root
            self.addCleanup(setattr, EVIDENCE, "ROOT", previous_root)

            paths, markers = EVIDENCE._source_record_identity_declared_watch_paths(
                paper
            )

            expected = {
                (root / relative).resolve()
                for relative in (*status_paths.values(), *map_paths.values())
            }
            self.assertTrue(expected.issubset(paths))
            self.assertTrue(all("trusted" in marker for marker in markers))

