    def test_evidence_identity_accepts_only_v7_administrative_map_drift(self) -> None:
        """The fast evidence gate retains full provenance and rejects semantic drift."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper_dir = root / "papers" / "Fixture"
            audit_dir = paper_dir / "audit"
            audit_dir.mkdir(parents=True)
            map_path = audit_dir / "paper_statement_map.json"

            def write_map(*, status: str, note: str) -> tuple[str, str]:
                map_path.write_text(
                    json.dumps(
                        {
                            "items": {
                                "opaque_source_item": {
                                    "source_kind": "theorem",
                                    "statement": "Every input has a witness.",
                                    "source_status": status,
                                    "source_note": note,
                                }
                            }
                        },
                        sort_keys=True,
                    ),
                    encoding="utf-8",
                )
                return AUDIT.paper_statement_map_cache_receipts(paper_dir)

            original_full, original_semantic = write_map(
                status="under_review", note="The source uses a finite model."
            )
            stored_fingerprint = {
                "schema": 7,
                "paper": "Fixture",
                "max_depth": 4,
                "no_lean": False,
                "paper_statement_map_semantic_sha256": original_semantic,
            }
            audit_payload = {
                "source_record_audit_sha256": "a" * 64,
                "paper_statement_map_sha256": original_full,
                "source_record_input_fingerprint": stored_fingerprint,
            }
            helper = (
                root
                / "skills"
                / "econcs-formalizer"
                / "scripts"
                / "source_record_audit.py"
            )
            helper.parent.mkdir(parents=True)
            helper.write_text("# fixture identity helper\n", encoding="utf-8")
            previous_root = EVIDENCE.ROOT
            EVIDENCE.ROOT = root
            self.addCleanup(setattr, EVIDENCE, "ROOT", previous_root)

            # v6 recorded the full map byte identity in its fingerprint. A
            # v7 helper may recognize it only while that full provenance still
            # matches exactly; this mirrors the aggregate-cache compatibility
            # path without granting a legacy map-edit exception.
            legacy_fingerprint = deepcopy(stored_fingerprint)
            legacy_fingerprint["schema"] = 6
            legacy_fingerprint.pop("paper_statement_map_semantic_sha256")
            legacy_fingerprint["paper_statement_map_sha256"] = original_full
            legacy_audit_payload = {
                "source_record_audit_sha256": "a" * 64,
                "paper_statement_map_sha256": original_full,
                "source_record_input_fingerprint": legacy_fingerprint,
            }
            legacy_identity_payload = {
                "schema": 1,
                "paper": "Fixture",
                "paper_statement_map_sha256": original_full,
                "paper_statement_map_semantic_sha256": original_semantic,
                "source_record_input_fingerprint": deepcopy(stored_fingerprint),
            }
            with patch.object(
                EVIDENCE.subprocess,
                "run",
                return_value=SimpleNamespace(
                    returncode=0,
                    stdout=json.dumps(legacy_identity_payload),
                    stderr="",
                ),
            ):
                self.assertEqual(
                    EVIDENCE.source_record_current_input_fingerprint_error(
                        paper_dir, legacy_audit_payload
                    ),
                    "",
                )

            administrative_full, administrative_semantic = write_map(
                status="resolved", note="The source uses a finite model."
            )
            self.assertNotEqual(administrative_full, original_full)
            self.assertEqual(administrative_semantic, original_semantic)
            identity_payload = {
                "schema": 1,
                "paper": "Fixture",
                "paper_statement_map_sha256": administrative_full,
                "paper_statement_map_semantic_sha256": administrative_semantic,
                "source_record_input_fingerprint": deepcopy(stored_fingerprint),
            }
            with patch.object(
                EVIDENCE.subprocess,
                "run",
                return_value=SimpleNamespace(
                    returncode=0,
                    stdout=json.dumps(identity_payload),
                    stderr="",
                ),
            ):
                self.assertEqual(
                    EVIDENCE.source_record_current_input_fingerprint_error(
                        paper_dir, audit_payload
                    ),
                    "",
                )
                self.assertIn(
                    "source_record_input_fingerprint is stale",
                    EVIDENCE.source_record_current_input_fingerprint_error(
                        paper_dir, legacy_audit_payload
                    ),
                )
            # This is the map-pin check used after the current v10 identity
            # check. It can accept only the same separately pinned semantic map.
            self.assertEqual(
                EVIDENCE.source_record_audit_identity_error(
                    audit_payload,
                    expected_paper_statement_map_sha256=administrative_full,
                    folder=paper_dir,
                ),
                "",
            )

            changed_full, changed_semantic = write_map(
                status="resolved", note="The source uses a different finite model."
            )
            self.assertNotEqual(changed_semantic, original_semantic)
            changed_fingerprint = deepcopy(stored_fingerprint)
            changed_fingerprint["paper_statement_map_semantic_sha256"] = changed_semantic
            changed_identity_payload = {
                "schema": 1,
                "paper": "Fixture",
                "paper_statement_map_sha256": changed_full,
                "paper_statement_map_semantic_sha256": changed_semantic,
                "source_record_input_fingerprint": changed_fingerprint,
            }
            with patch.object(
                EVIDENCE.subprocess,
                "run",
                return_value=SimpleNamespace(
                    returncode=0,
                    stdout=json.dumps(changed_identity_payload),
                    stderr="",
                ),
            ):
                self.assertIn(
                    "source_record_input_fingerprint is stale",
                    EVIDENCE.source_record_current_input_fingerprint_error(
                        paper_dir, audit_payload
                    ),
                )
            self.assertIn(
                "paper_statement_map_sha256 is stale",
                EVIDENCE.source_record_audit_identity_error(
                    audit_payload,
                    expected_paper_statement_map_sha256=changed_full,
                    folder=paper_dir,
                ),
            )
            declaration_authority = EVIDENCE.CurrentSemanticReuseAuthority(
                paper="Fixture",
                raw_audit_file_sha256="b" * 64,
                semantic_identity_sha256="c" * 64,
                reviewed_declarations=("Fixture.Spec",),
                watched_repository_material=(),
                result={"current": True},
            )
            self.assertEqual(
                EVIDENCE._source_record_audit_identity_error(
                    audit_payload,
                    expected_paper_statement_map_sha256=changed_full,
                    folder=paper_dir,
                    semantic_reuse_authority=declaration_authority,
                ),
                "",
            )

