    def test_input_fingerprint_records_narrow_raw_producer_code_identity(self) -> None:
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper_dir = root / "papers" / "Fixture"
            audit_dir = paper_dir / "audit"
            audit_dir.mkdir(parents=True)
            interface = paper_dir / "PaperInterface.lean"
            interface.write_text("namespace Fixture\nend Fixture\n", encoding="utf-8")
            (paper_dir / "status.json").write_text(
                json.dumps(
                    {
                        "status": "partially formalized",
                        "review_surface": {
                            "source_file": "papers/Fixture/PaperInterface.lean"
                        },
                    }
                ),
                encoding="utf-8",
            )
            map_path = audit_dir / "paper_statement_map.json"
            map_path.write_text("{}\n", encoding="utf-8")
            fingerprint = AUDIT.source_record_input_fingerprint(
                SimpleNamespace(paper="Fixture", max_depth=4, no_lean=False),
                root,
                paper_dir,
                paper_statement_map_sha256=hashlib.sha256(map_path.read_bytes()).hexdigest(),
            )
            assert fingerprint is not None
            self.assertEqual(fingerprint["schema"], 10)
            self.assertNotIn("implementation_sha256", fingerprint)
            self.assertEqual(
                fingerprint["audit_engine_identities"],
                AUDIT.source_record_engine_identities(root),
            )
            self.assertEqual(
                fingerprint["raw_producer_code_identity_schema"],
                AUDIT.SOURCE_RECORD_RAW_PRODUCER_CODE_IDENTITY_SCHEMA,
            )
            producer_identities = fingerprint["raw_producer_code_identities"]
            self.assertEqual(
                {
                    identity["path"]
                    for identity in producer_identities
                },
                {
                    "skills/econcs-formalizer/scripts/source_record_audit.py"
                    "#fresh-raw-generation",
                    "scripts/lean_signature_manifest_helper.lean",
                },
            )
            self.assertTrue(
                all(
                    identity["status"] == "present"
                    and len(identity["sha256"]) == 64
                    for identity in producer_identities
                )
            )
            conditional_text = (
                "Proposition 1. Suppose the model has finite support.\n"
                "(i) The first premise holds.\n"
                "(ii) The second premise holds.\n"
                "Then the conclusion holds.\n"
            )
            source_path = paper_dir / "source.txt"
            source_path.write_text(conditional_text, encoding="utf-8")
            feature_map = {
                "source_coverage_mode": "named_theoretical_statements",
                "source_artifact_path": "source.txt",
                "source_artifact_sha256": hashlib.sha256(
                    conditional_text.encode("utf-8")
                ).hexdigest(),
                "items": {
                    "opaque_source_grammar_key": {
                        "lean_declarations": ["Fixture.unrelatedRoute"],
                    },
                },
            }
            map_path.write_text(json.dumps(feature_map), encoding="utf-8")
            feature_fingerprint = AUDIT.source_record_input_fingerprint(
                SimpleNamespace(paper="Fixture", max_depth=4, no_lean=False),
                root,
                paper_dir,
                paper_statement_map_sha256=hashlib.sha256(
                    map_path.read_bytes()
                ).hexdigest(),
            )
            assert feature_fingerprint is not None
            self.assertIn(
                AUDIT.CONDITIONAL_ANTECEDENT_SUBPART_SURFACE_ENGINE_IDENTITY,
                feature_fingerprint["audit_engine_identities"],
            )
            self.assertNotEqual(fingerprint, feature_fingerprint)
            (audit_dir / "source_proof_fidelity.json").write_text(
                json.dumps(
                    {
                        "model_conventions": [
                            {
                                "id": "fixture_scope",
                                "recursive_field_source_scope": {
                                    "schema": 1,
                                    "entries": [],
                                },
                            }
                        ]
                    }
                ),
                encoding="utf-8",
            )
            scoped_fingerprint = AUDIT.source_record_input_fingerprint(
                SimpleNamespace(paper="Fixture", max_depth=4, no_lean=False),
                root,
                paper_dir,
                paper_statement_map_sha256=hashlib.sha256(
                    map_path.read_bytes()
                ).hexdigest(),
            )
            assert scoped_fingerprint is not None
            self.assertIn(
                AUDIT.RECURSIVE_FIELD_SOURCE_SCOPE_SURFACE_ENGINE_IDENTITY,
                scoped_fingerprint["audit_engine_identities"],
            )
            self.assertNotEqual(fingerprint, scoped_fingerprint)
            with patch.dict(
                AUDIT.SOURCE_RECORD_SURFACE_ENGINE_VERSIONS,
                {
                    "scripts/source_named_result_index.py": (
                        "source-named-result-selection-v2"
                    )
                },
            ):
                changed = AUDIT.source_record_input_fingerprint(
                    SimpleNamespace(paper="Fixture", max_depth=4, no_lean=False),
                    root,
                    paper_dir,
                    paper_statement_map_sha256=hashlib.sha256(
                        map_path.read_bytes()
                    ).hexdigest(),
                )
            self.assertNotEqual(fingerprint, changed)

    def test_transparent_spec_raw_identity_reissue_is_feature_scoped(self) -> None:
        """Spec maps differ by semantic feature identity, not hash aliases."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper_dir = root / "papers" / "Fixture"
            audit_dir = paper_dir / "audit"
            audit_dir.mkdir(parents=True)
            (paper_dir / "PaperInterface.lean").write_text(
                "namespace Fixture\nend Fixture\n", encoding="utf-8"
            )
            (paper_dir / "status.json").write_text(
                json.dumps(
                    {
                        "status": "formalized",
                        "review_surface": {
                            "source_file": "papers/Fixture/PaperInterface.lean"
                        },
                    }
                ),
                encoding="utf-8",
            )
            map_path = audit_dir / "paper_statement_map.json"
            args = SimpleNamespace(paper="Fixture", max_depth=4, no_lean=False)

            map_path.write_text(json.dumps({"items": {}}), encoding="utf-8")
            ordinary = AUDIT.source_record_input_fingerprint(
                args,
                root,
                paper_dir,
                paper_statement_map_sha256=hashlib.sha256(
                    map_path.read_bytes()
                ).hexdigest(),
            )
            assert ordinary is not None
            self.assertEqual(
                ordinary["raw_producer_code_identities"],
                AUDIT.source_record_raw_producer_code_identities(),
            )
            self.assertNotIn(
                AUDIT.DIRECT_TRANSPARENT_SPEC_ROOT_IDENTITY_SURFACE_ENGINE_IDENTITY,
                ordinary["audit_engine_identities"],
            )

            map_path.write_text(
                json.dumps(
                    {
                        "items": {
                            "source_item": {
                                "claim_bearing": True,
                                "semantic_contract": {
                                    "evidence_declaration": "Fixture.evidence",
                                    "spec_declaration": "Fixture.spec",
                                },
                            }
                        }
                    }
                ),
                encoding="utf-8",
            )
            paired = AUDIT.source_record_input_fingerprint(
                args,
                root,
                paper_dir,
                paper_statement_map_sha256=hashlib.sha256(
                    map_path.read_bytes()
                ).hexdigest(),
            )
            assert paired is not None
            self.assertEqual(
                paired["raw_producer_code_identities"],
                ordinary["raw_producer_code_identities"],
            )
            self.assertIn(
                AUDIT.DIRECT_TRANSPARENT_SPEC_ROOT_IDENTITY_SURFACE_ENGINE_IDENTITY,
                paired["audit_engine_identities"],
            )
            self.assertNotEqual(ordinary, paired)

            # The compatibility route is exact, not a standing bypass for
            # later raw-producer changes.
            with patch.object(
                AUDIT,
                "_source_record_raw_generation_code_identity",
                return_value={
                    "path": (
                        "skills/econcs-formalizer/scripts/source_record_audit.py"
                        "#fresh-raw-generation"
                    ),
                    "sha256": "f" * 64,
                    "status": "present",
                },
            ):
                self.assertNotEqual(
                    AUDIT.source_record_raw_producer_code_identities(),
                    ordinary["raw_producer_code_identities"],
                )

