    def test_semantic_dimension_migration_identity_is_defect_scoped_and_sticky(self) -> None:
        """Only the old empty-dimensional direct-route receipt is reopened."""

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            paper_dir = root / "papers" / "Fixture"
            audit_dir = paper_dir / "audit"
            audit_dir.mkdir(parents=True)
            (paper_dir / "PaperInterface.lean").write_text(
                "namespace Fixture\nend Fixture\n", encoding="utf-8"
            )
            (paper_dir / "status.json").write_text(
                json.dumps(
                    {
                        "status": "formalized",
                        "review_surface": {
                            "source_file": "papers/Fixture/PaperInterface.lean",
                            "semantic_model_review": {
                                "schema": AUDIT.SEMANTIC_MODEL_REVIEW_SCHEMA,
                                "required_dimensions": list(
                                    AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER
                                ),
                            },
                        },
                    }
                ),
                encoding="utf-8",
            )
            map_path = audit_dir / "paper_statement_map.json"

            def write_map(items: dict[str, object]) -> str:
                map_path.write_text(
                    json.dumps(
                        {
                            "source_coverage_mode": "deep_paper_with_all_prose_claims",
                            "items": items,
                        }
                    ),
                    encoding="utf-8",
                )
                return hashlib.sha256(map_path.read_bytes()).hexdigest()

            no_route_digest = write_map(
                {
                    "unrouted_source_presentation": {
                        "source_location": "source.txt:1",
                        "statement": "A source-presented model description.",
                    }
                }
            )
            args = SimpleNamespace(paper="Fixture", max_depth=4, no_lean=False)
            no_route_fingerprint = AUDIT.source_record_input_fingerprint(
                args,
                root,
                paper_dir,
                paper_statement_map_sha256=no_route_digest,
            )
            assert no_route_fingerprint is not None
            self.assertNotIn(
                AUDIT.SEMANTIC_MODEL_DIMENSION_CONFIGURATION_SURFACE_ENGINE_IDENTITY,
                no_route_fingerprint["audit_engine_identities"],
            )
            self.assertEqual(
                no_route_fingerprint["audit_engine_identities"],
                AUDIT.source_record_engine_identities(root),
            )

            routed_digest = write_map(
                {
                    "source_presentation_with_explicit_route": {
                        "source_location": "source.txt:1",
                        "statement": "A source-presented model result.",
                        "lean_declarations": [
                            "Fixture.PaperInterface.source_facing_result"
                        ],
                    }
                }
            )
            legacy_fingerprint = AUDIT.source_record_input_fingerprint(
                args,
                root,
                paper_dir,
                paper_statement_map_sha256=routed_digest,
            )
            assert legacy_fingerprint is not None
            self.assertNotIn(
                AUDIT.SEMANTIC_MODEL_DIMENSION_CONFIGURATION_SURFACE_ENGINE_IDENTITY,
                legacy_fingerprint["audit_engine_identities"],
            )

            # This reproduces precisely the legacy generated surface: the
            # source route is present but the semantic-model dimensions are
            # empty. A raw whose saved fingerprint predates the migration
            # identity must no longer be cache-reusable.
            defective_payload: dict[str, object] = {
                "paper": "Fixture",
                "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
                "source_record_input_fingerprint": legacy_fingerprint,
                "paper_statement_map_sha256": routed_digest,
                "semantic_model_items": [
                    {
                        "judgment_key": "semantic-model::source_facing_result",
                        "dimensions": [],
                        "source_statement_association": {
                            "role": "direct_source_route",
                            "source_item_identities": [
                                {"source_key": "source_presentation_with_explicit_route"}
                            ],
                        },
                    }
                ],
            }
            SourceRecordRawIntegrityCacheTests._complete_successful_scan(
                defective_payload
            )
            stamp_source_record_audit_receipts(defective_payload)
            (audit_dir / "source_record_audit.json").write_text(
                json.dumps(defective_payload), encoding="utf-8"
            )

            migration_fingerprint = AUDIT.source_record_input_fingerprint(
                args,
                root,
                paper_dir,
                paper_statement_map_sha256=routed_digest,
            )
            assert migration_fingerprint is not None
            self.assertIn(
                AUDIT.SEMANTIC_MODEL_DIMENSION_CONFIGURATION_SURFACE_ENGINE_IDENTITY,
                migration_fingerprint["audit_engine_identities"],
            )
            reusable_args = SimpleNamespace(
                paper="Fixture",
                max_depth=4,
                no_lean=False,
                force=False,
                refresh_judgment_summary=False,
                ignore_current_judgments=False,
            )
            with patch.object(AUDIT, "refresh_existing_judgment_summary") as refresh:
                self.assertIsNone(
                    AUDIT.reusable_source_record_audit(
                        reusable_args,
                        root,
                        paper_dir,
                        paper_statement_map_sha256=routed_digest,
                    )
                )
                refresh.assert_not_called()

            corrected_payload: dict[str, object] = {
                "paper": "Fixture",
                "prompt_version": AUDIT.SOURCE_RECORD_PROMPT_VERSION,
                "source_record_input_fingerprint": migration_fingerprint,
                "paper_statement_map_sha256": routed_digest,
                "semantic_model_items": [
                    {
                        "judgment_key": "semantic-model::source_facing_result",
                        "dimensions": [
                            {"id": dimension}
                            for dimension in AUDIT.SEMANTIC_MODEL_DIMENSION_ORDER
                        ],
                        "source_statement_association": {
                            "role": "direct_source_route",
                            "source_item_identities": [
                                {"source_key": "source_presentation_with_explicit_route"}
                            ],
                        },
                    }
                ],
            }
            SourceRecordRawIntegrityCacheTests._complete_successful_scan(
                corrected_payload
            )
            stamp_source_record_audit_receipts(corrected_payload)
            (audit_dir / "source_record_audit.json").write_text(
                json.dumps(corrected_payload), encoding="utf-8"
            )
            self.assertEqual(
                AUDIT.source_record_input_fingerprint(
                    args,
                    root,
                    paper_dir,
                    paper_statement_map_sha256=routed_digest,
                ),
                migration_fingerprint,
            )

